function isAdmin(usuario) {
  return (
    usuario?.perfil ===
    "ADMINISTRADOR"
  );
}

function isCoord(usuario) {
  return (
    usuario?.perfil ===
      "COORDENADOR"

    ||

    isAdmin(usuario)
  );
}

function isGerencia(usuario) {
  return (
    usuario?.perfil ===
    "GERENCIA"
  );
}

function isCadastro(usuario) {
  return usuario?.perfil === "CADASTRO";
}

// V3.4.20: mensagens privadas pertencem à comunicação operacional, nunca ao perfil Cadastro.
function podeUsarMensagensPrivadasV3420(usuario) {
  return Boolean(usuario) && !isCadastro(usuario) && [
    "ADMINISTRADOR",
    "COORDENADOR",
    "GERENCIA",
    "FUNCIONARIO"
  ].includes(usuario.perfil);
}

// V3.4.20: chat geral restrito à equipe Digital real. Cadastro e usuários apenas Convencionais ficam fora.
function podeAcessarChatEquipeDigitalV3420(usuario) {
  if (!usuario || isCadastro(usuario)) return false;
  if (isCoord(usuario)) return true;
  if (isGerencia(usuario)) return areasUsuarioV31(usuario).includes("DIGITAL");
  if (usuario.perfil !== "FUNCIONARIO") return false;
  if (!areasUsuarioV31(usuario).includes("DIGITAL")) return false;
  return setoresUsuarioV31(usuario, "DIGITAL").some(setor => SETORES.includes(setor));
}

// V3.4.18: cadastro pode criar/editar remessas e pacientes, sem herdar gestão de produção.
function podeCadastrarDigitalV3418(usuario) {
  return isCadastro(usuario) || podeGerenciarAreaV31(usuario, "DIGITAL");
}

function retornoCadastroDigitalV3418(usuario, cicloId = 0, chave = "", mensagem = "") {
  const base = isCadastro(usuario) ? "/cadastro" : "/digital";
  const params = new URLSearchParams();
  if (Number(cicloId || 0) > 0) params.set("ciclo", String(Number(cicloId)));
  if (chave && mensagem) params.set(chave, String(mensagem));
  const qs = params.toString();
  return qs ? `${base}?${qs}` : base;
}

function podeVerGestao(usuario) {
  return (
    isCoord(usuario)

    ||

    isGerencia(usuario)
  );
}

function listaPipeV31(valor) {
  return String(valor || "")
    .split("|")
    .map(item => item.trim())
    .filter(Boolean);
}

function areasUsuarioV31(usuario) {
  return areasUsuarioBaseV31(usuario);
}

function areasUsuarioBaseV31(usuario) {
  const areas = areasUsuarioCruV31(usuario);
  return MODO_CONVENCIONAL_ATIVO ? areas : areas.filter(a => a !== "CONVENCIONAL");
}

function areasUsuarioCruV31(usuario) {
  if (!usuario) return [];
  if (isCoord(usuario)) return ["DIGITAL", "CONVENCIONAL"];

  const novas = listaPipeV31(usuario.areas_v31);
  if (novas.length) return [...new Set(novas)];

  // Fallback de compatibilidade apenas para funcionários antigos.
  if (usuario.perfil === "FUNCIONARIO") {
    const legado = String(usuario.area_producao || "DIGITAL").toUpperCase();
    if (legado === "AMBOS") return ["DIGITAL", "CONVENCIONAL"];
    if (["DIGITAL", "CONVENCIONAL"].includes(legado)) return [legado];
  }
  return [];
}

function setoresUsuarioV31(usuario, area) {
  if (!usuario) return [];
  if (isCoord(usuario)) {
    return area === "CONVENCIONAL" ? [...SETORES_CONVENCIONAIS] : [...SETORES];
  }
  if (isGerencia(usuario) && areasUsuarioV31(usuario).includes(area)) {
    return area === "CONVENCIONAL" ? [...SETORES_CONVENCIONAIS] : [...SETORES];
  }

  const prefixo = `${area}:`;
  const novos = listaPipeV31(usuario.setores_v31)
    .filter(item => item.startsWith(prefixo))
    .map(item => item.slice(prefixo.length));
  if (novos.length) return [...new Set(novos)];

  // Fallback legado até todos os cadastros serem revisados na V3.1.
  if (usuario.perfil === "FUNCIONARIO") {
    if (area === "DIGITAL" && usuario.setor) return [String(usuario.setor)];
    if (area === "CONVENCIONAL" && usuario.setor_convencional) return [String(usuario.setor_convencional)];
  }
  return [];
}

function areaGerenciaV31(usuario) {
  if (!isGerencia(usuario)) return null;
  const areas = areasUsuarioV31(usuario);
  return areas.length === 1 ? areas[0] : null;
}

function podeGerenciarAreaV31(usuario, area) {
  if (isCoord(usuario)) return true;
  return isGerencia(usuario) && areasUsuarioV31(usuario).includes(area);
}

function usuarioParticipaBonusV31(usuario, area) {
  if (!usuario || usuario.perfil !== "FUNCIONARIO") return false;
  const prefixo = `${area}:`;
  const registro = listaPipeV31(usuario.bonus_areas_v31)
    .find(item => item.startsWith(prefixo));
  if (!registro) return true; // compatibilidade com funcionário migrado.
  return registro.slice(prefixo.length) === "1";
}

function podeOperarEtapa(
  usuario,
  setor
) {
  if (!usuarioTemAreaDigital(usuario)) return false;
  if (isCoord(usuario) || isGerencia(usuario)) return true;
  return usuario?.perfil === "FUNCIONARIO"
    && setoresUsuarioV31(usuario, "DIGITAL").includes(setor);
}


function nomeAreaProducao(area) {
  const mapa = {
    DIGITAL: "Digital",
    CONVENCIONAL: "Convencional",
    AMBOS: "Digital + Convencional"
  };
  return mapa[area] || area || "Digital";
}

function nomeSetorConvencional(setor) {
  const mapa = {
    ARTICULACAO: "Articulação",
    MONTAGEM: "Montagem",
    ENCERRAMENTO: "Encerramento",
    ESCULTURA: "Escultura",
    INCLUSAO: "Inclusão",
    ACRILIZACAO: "Acrilização",
    DESINCLUSAO: "Desinclusão",
    ACABAMENTO: "Acabamento",
    QUALIDADE: "Qualidade"
  };
  return mapa[setor] || setor || "—";
}

function usuarioTemAreaDigital(usuario) {
  return areasUsuarioV31(usuario).includes("DIGITAL");
}

function usuarioTemAreaConvencional(usuario) {
  return areasUsuarioV31(usuario).includes("CONVENCIONAL");
}

function podeOperarConvencional(usuario, setor) {
  if (!usuarioTemAreaConvencional(usuario)) return false;
  if (isCoord(usuario) || isGerencia(usuario)) return true;
  return usuario?.perfil === "FUNCIONARIO"
    && setoresUsuarioV31(usuario, "CONVENCIONAL").includes(setor);
}

/* =========================================================
   V3.4.5 · VISIBILIDADE DIGITAL POR DESIGNAÇÃO
   Funcionário vê:
   - tarefas dos próprios setores designadas a ele;
   - tarefas dos próprios setores ainda sem designação.
   Gestão Digital continua vendo tudo.
========================================================= */

function clausulaVisibilidadeTrabalhoDigitalV345(usuario, aliasTrabalho = "t") {
  if (!usuario || podeGerenciarAreaV31(usuario, "DIGITAL")) {
    return { sql: "", args: [] };
  }

  if (usuario.perfil !== "FUNCIONARIO" || !usuarioTemAreaDigital(usuario)) {
    return { sql: " AND 1=0 ", args: [] };
  }

  const setores = setoresUsuarioV31(usuario, "DIGITAL")
    .filter(setor => SETORES.includes(setor));

  if (!setores.length) {
    return { sql: " AND 1=0 ", args: [] };
  }

  const clausulas = [];
  const args = [];
  const setoresEtapas = setores.filter(setor => setor !== "IMPRESSAO");

  if (setoresEtapas.length) {
    clausulas.push(`
      EXISTS (
        SELECT 1
        FROM etapas ev345
        WHERE ev345.trabalho_id = ${aliasTrabalho}.id
          AND ev345.setor IN (${setoresEtapas.map(() => "?").join(",")})
          AND (
            ev345.responsavel_id = ?
            OR (
              ev345.responsavel_id IS NULL
              AND ev345.status IN ('AGUARDANDO','EM_ANDAMENTO')
            )
          )
      )
    `);
    args.push(...setoresEtapas, Number(usuario.id));
  }

  if (setores.includes("IMPRESSAO")) {
    clausulas.push(`
      EXISTS (
        SELECT 1
        FROM componentes_impressao cv345
        WHERE cv345.trabalho_id = ${aliasTrabalho}.id
          AND (
            cv345.responsavel_id = ?
            OR (
              cv345.responsavel_id IS NULL
              AND cv345.status IN ('AGUARDANDO','EM_ANDAMENTO')
            )
          )
      )
    `);
    args.push(Number(usuario.id));
  }

  clausulas.push(`
    EXISTS (
      SELECT 1
      FROM retrabalhos rv345
      WHERE rv345.trabalho_id = ${aliasTrabalho}.id
        AND rv345.setor IN (${setores.map(() => "?").join(",")})
        AND rv345.status IN ('ABERTO','EM_ANDAMENTO')
        AND (
          rv345.executado_por IS NULL
          OR rv345.executado_por = ?
        )
    )
  `);
  args.push(...setores, Number(usuario.id));

  return {
    sql: ` AND (${clausulas.join(" OR ")}) `,
    args
  };
}

function sqlVisibilidadeTrabalhoDigitalLiteralV345(usuario, aliasTrabalho = "t") {
  if (!usuario || podeGerenciarAreaV31(usuario, "DIGITAL")) return "";

  if (usuario.perfil !== "FUNCIONARIO" || !usuarioTemAreaDigital(usuario)) {
    return " AND 1=0 ";
  }

  const usuarioId = Number(usuario.id);
  const setores = setoresUsuarioV31(usuario, "DIGITAL")
    .filter(setor => SETORES.includes(setor));

  if (!Number.isSafeInteger(usuarioId) || usuarioId < 1 || !setores.length) {
    return " AND 1=0 ";
  }

  const quote = valor => `'${String(valor).replaceAll("'", "''")}'`;
  const clausulas = [];
  const setoresEtapas = setores.filter(setor => setor !== "IMPRESSAO");

  if (setoresEtapas.length) {
    clausulas.push(`
      EXISTS (
        SELECT 1
        FROM etapas ev345
        WHERE ev345.trabalho_id = ${aliasTrabalho}.id
          AND ev345.setor IN (${setoresEtapas.map(quote).join(",")})
          AND (
            ev345.responsavel_id = ${usuarioId}
            OR (
              ev345.responsavel_id IS NULL
              AND ev345.status IN ('AGUARDANDO','EM_ANDAMENTO')
            )
          )
      )
    `);
  }

  if (setores.includes("IMPRESSAO")) {
    clausulas.push(`
      EXISTS (
        SELECT 1
        FROM componentes_impressao cv345
        WHERE cv345.trabalho_id = ${aliasTrabalho}.id
          AND (
            cv345.responsavel_id = ${usuarioId}
            OR (
              cv345.responsavel_id IS NULL
              AND cv345.status IN ('AGUARDANDO','EM_ANDAMENTO')
            )
          )
      )
    `);
  }

  clausulas.push(`
    EXISTS (
      SELECT 1
      FROM retrabalhos rv345
      WHERE rv345.trabalho_id = ${aliasTrabalho}.id
        AND rv345.setor IN (${setores.map(quote).join(",")})
        AND rv345.status IN ('ABERTO','EM_ANDAMENTO')
        AND (
          rv345.executado_por IS NULL
          OR rv345.executado_por = ${usuarioId}
        )
    )
  `);

  return ` AND (${clausulas.join(" OR ")}) `;
}

async function usuarioPodeVerTrabalhoDigitalV345(env, usuario, trabalhoId) {
  if (!usuario || !usuarioTemAreaDigital(usuario)) return false;
  if (podeGerenciarAreaV31(usuario, "DIGITAL")) return true;

  const visibilidade = clausulaVisibilidadeTrabalhoDigitalV345(usuario, "t");

  const item = await env.db.prepare(`
    SELECT t.id
    FROM trabalhos t
    WHERE t.id = ?
      AND t.excluido = 0
      ${visibilidade.sql}
    LIMIT 1
  `).bind(Number(trabalhoId), ...visibilidade.args).first();

  return Boolean(item);
}


