async function resumoPainel(env) {

  const [
    retencao,
    urgentes,
    municipios
  ] =
    await Promise.all([

      env.db.prepare(`

        SELECT
          COUNT(*) AS total

        FROM trabalhos

        WHERE
          excluido = 0

          AND entregue = 1

          AND data_entrega
            IS NOT NULL

          AND date(
            data_entrega,
            '+4 months'
          )
          <=
          date('now')

          AND (
            retencao_adiada_ate
              IS NULL

            OR

            date(
              retencao_adiada_ate
            )
            <=
            date('now')
          )

      `).first(),

      env.db.prepare(`

        SELECT
          COUNT(*) AS total

        FROM avisos_coordenador

        WHERE
          urgente = 1

          AND encerrado = 0

      `).first(),

      env.db.prepare(`

        SELECT

          COUNT(
            DISTINCT
            lower(
              trim(
                municipio
              )
            )
          )
          AS total

        FROM trabalhos

        WHERE
          excluido = 0

          AND trim(
            municipio
          ) <> ''

      `).first()
    ]);

  return {

    retencao:
      Number(
        retencao?.total
        ||
        0
      ),

    urgentes:
      Number(
        urgentes?.total
        ||
        0
      ),

    municipios:
      Number(
        municipios?.total
        ||
        0
      )
  };
}

