/* =========================================================
   DASHBOARD DO COORDENADOR · V2.6
   VISÃO OPERACIONAL + ALERTAS + REMESSAS + EQUIPE + BÔNUS
========================================================= */

function areaDashboardV26(valor) {
  const area = String(valor || "AMBOS").toUpperCase();
  return ["DIGITAL", "CONVENCIONAL", "AMBOS"].includes(area) ? area : "AMBOS";
}

function hojeIsoV26() {
  return new Date().toISOString().slice(0, 10);
}

function inicioSemanaIsoV26(dataIso = hojeIsoV26()) {
  const d = new Date(`${dataIso}T00:00:00Z`);
  const dia = d.getUTCDay();
  const deslocamento = dia === 0 ? -6 : 1 - dia;
  d.setUTCDate(d.getUTCDate() + deslocamento);
  return d.toISOString().slice(0, 10);
}

function inicioMesIsoV26(dataIso = hojeIsoV26()) {
  return `${String(dataIso).slice(0, 7)}-01`;
}

function periodoDashboardV26(url) {
  const hoje = hojeIsoV26();
  let inicio = String(url.searchParams.get("inicio") || hoje);
  let fim = String(url.searchParams.get("fim") || hoje);
  if (!dataIsoValidaV25(inicio) || !dataIsoValidaV25(fim) || fim < inicio) {
    inicio = hoje;
    fim = hoje;
  }
  return { inicio, fim };
}

function chaveBonusV26(area, setor, usuarioId) {
  return `${area}|${setor}|${Number(usuarioId || 0)}`;
}

function regraBonusV26(regras, area, setor, usuarioId) {
  const especifica = regras.find(item =>
    String(item.area) === area &&
    String(item.setor) === setor &&
    Number(item.funcionario_id || 0) === Number(usuarioId)
  );
  if (especifica) return especifica;
  return regras.find(item =>
    String(item.area) === area &&
    String(item.setor) === setor &&
    (item.funcionario_id === null || Number(item.funcionario_id || 0) === 0)
  ) || null;
}

async function dadosDashboardV26(env, inicio, fim, area) {
  const incluirDigital = area !== "CONVENCIONAL";
  const incluirConvencional = area !== "DIGITAL";

  const [usuariosRes, digitalUnidades, convRes, regrasRes, ajustesRes, alertas, remessasRes] = await Promise.all([
    env.db.prepare(`
      SELECT id, nome, usuario, setor, setor_convencional, area_producao, ativo
      FROM usuarios
      WHERE perfil = 'FUNCIONARIO' AND excluido = 0
      ORDER BY nome ASC
    `).all(),

    incluirDigital ? unidadesConcluidas(env, inicio, fim) : Promise.resolve([]),

    incluirConvencional ? env.db.prepare(`
      SELECT
        e.responsavel_id AS usuario_id,
        e.setor,
        p.trabalho_id,
        p.tipo_protese,
        e.concluido_em AS data
      FROM etapas_convencionais e
      INNER JOIN pecas_convencionais p ON p.id = e.peca_id
      WHERE e.status = 'CONCLUIDO'
        AND e.responsavel_id IS NOT NULL
        AND e.concluido_em IS NOT NULL
        AND date(e.concluido_em, '-3 hours') BETWEEN date(?) AND date(?)
      ORDER BY e.concluido_em ASC, e.id ASC
    `).bind(inicio, fim).all() : Promise.resolve({ results: [] }),

    env.db.prepare(`
      SELECT *
      FROM metas_bonificacao
      WHERE ativo = 1
        AND date(vigencia_inicio) <= date(?)
        AND (vigencia_fim IS NULL OR date(vigencia_fim) >= date(?))
      ORDER BY date(vigencia_inicio) DESC, id DESC
    `).bind(inicio, fim).all(),

    env.db.prepare(`
      SELECT *
      FROM ajustes_dias_bonificacao
      WHERE periodo_inicio = ? AND periodo_fim = ?
    `).bind(inicio, fim).all(),

    Promise.all([
      env.db.prepare(`
        SELECT COUNT(DISTINCT trabalho_id) AS total
        FROM etapas
        WHERE status = 'EM_ANDAMENTO'
          AND iniciado_em IS NOT NULL
          AND datetime(iniciado_em) <= datetime('now','-2 days')
      `).first(),
      env.db.prepare(`
        SELECT COUNT(DISTINCT p.trabalho_id) AS total
        FROM etapas_convencionais e
        INNER JOIN pecas_convencionais p ON p.id = e.peca_id
        WHERE e.status = 'EM_ANDAMENTO'
          AND e.iniciado_em IS NOT NULL
          AND datetime(e.iniciado_em) <= datetime('now','-2 days')
      `).first(),
      env.db.prepare(`
        SELECT COUNT(*) AS total
        FROM remessas
        WHERE data_entrega_real IS NULL
          AND date(data_prevista_entrega) >= date('now')
          AND date(data_prevista_entrega) <= date('now','+3 days')
      `).first(),
      env.db.prepare(`
        SELECT COUNT(*) AS total
        FROM remessas
        WHERE data_entrega_real IS NULL
          AND date(data_prevista_entrega) < date('now')
      `).first(),
      env.db.prepare(`
        SELECT COUNT(*) AS total
        FROM etapas_convencionais e
        INNER JOIN pecas_convencionais p ON p.id = e.peca_id
        INNER JOIN trabalhos_convencionais t ON t.id = p.trabalho_id
        WHERE t.excluido = 0
          AND e.setor = 'QUALIDADE'
          AND e.status = 'AGUARDANDO'
      `).first(),
      env.db.prepare(`
        SELECT COUNT(*) AS total
        FROM retrabalhos_convencionais
        WHERE status IN ('AGUARDANDO','EM_ANDAMENTO')
      `).first(),
      env.db.prepare(`
        SELECT COUNT(*) AS total
        FROM cargas_muflas_convencionais
        WHERE ativo = 1
      `).first()
    ]),

    env.db.prepare(`
      SELECT
        r.*,
        (SELECT COUNT(*) FROM trabalhos t
         WHERE t.excluido = 0 AND t.remessa_id = r.id) AS digital_total,
        (SELECT COUNT(*) FROM trabalhos t
         WHERE t.excluido = 0 AND t.remessa_id = r.id
           AND NOT EXISTS (
             SELECT 1 FROM etapas e
             WHERE e.trabalho_id = t.id AND e.status != 'CONCLUIDO'
           )) AS digital_prontos,
        (SELECT COUNT(*) FROM trabalhos_convencionais tc
         WHERE tc.excluido = 0 AND tc.remessa_id = r.id) AS convencional_total,
        (SELECT COUNT(*) FROM trabalhos_convencionais tc
         WHERE tc.excluido = 0 AND tc.remessa_id = r.id
           AND tc.status IN ('LIBERADO_ENTREGA','CONCLUIDO')) AS convencional_prontos
      FROM remessas r
      WHERE r.data_entrega_real IS NULL
      ORDER BY
        CASE WHEN date(r.data_prevista_entrega) < date('now') THEN 0 ELSE 1 END,
        date(r.data_prevista_entrega) ASC,
        r.id DESC
      LIMIT 12
    `).all()
  ]);

  const usuarios = usuariosRes.results || [];
  const usuarioMap = new Map(usuarios.map(item => [Number(item.id), item]));
  const convencionalUnidades = convRes.results || [];
  const regras = regrasRes.results || [];
  const ajustes = ajustesRes.results || [];
  const ajusteMap = new Map(ajustes.map(item => [
    chaveBonusV26(item.area, item.setor, item.funcionario_id),
    item
  ]));

  const setoresDigital = new Map(SETORES.map(setor => [setor, 0]));
  const setoresConv = new Map(SETORES_CONVENCIONAIS.map(setor => [setor, 0]));
  const porFuncionario = new Map();
  const porFuncionarioSetor = new Map();

  function registrarUnidade(unidade, areaUnidade) {
    const usuarioId = Number(unidade.usuario_id || 0);
    const setor = String(unidade.setor || "");
    if (!usuarioId || !setor) return;

    if (areaUnidade === "DIGITAL") {
      setoresDigital.set(setor, Number(setoresDigital.get(setor) || 0) + 1);
    } else {
      setoresConv.set(setor, Number(setoresConv.get(setor) || 0) + 1);
    }

    if (!porFuncionario.has(usuarioId)) {
      porFuncionario.set(usuarioId, { total: 0, digital: 0, convencional: 0, bonus_centavos: 0, sem_regra: 0 });
    }
    const geral = porFuncionario.get(usuarioId);
    geral.total += 1;
    if (areaUnidade === "DIGITAL") geral.digital += 1;
    else geral.convencional += 1;

    const chave = chaveBonusV26(areaUnidade, setor, usuarioId);
    if (!porFuncionarioSetor.has(chave)) {
      porFuncionarioSetor.set(chave, {
        area: areaUnidade,
        setor,
        usuario_id: usuarioId,
        quantidade: 0,
        dias: new Set()
      });
    }
    const detalhe = porFuncionarioSetor.get(chave);
    detalhe.quantidade += 1;
    if (unidade.data) detalhe.dias.add(String(unidade.data).slice(0, 10));
  }

  if (incluirDigital) {
    for (const unidade of digitalUnidades || []) registrarUnidade(unidade, "DIGITAL");
  }
  if (incluirConvencional) {
    for (const unidade of convencionalUnidades) registrarUnidade(unidade, "CONVENCIONAL");
  }

  for (const detalhe of porFuncionarioSetor.values()) {
    const funcionario = porFuncionario.get(Number(detalhe.usuario_id));
    if (!funcionario) continue;
    const regra = regraBonusV26(regras, detalhe.area, detalhe.setor, detalhe.usuario_id);
    if (!regra) {
      funcionario.sem_regra += 1;
      continue;
    }
    const ajuste = ajusteMap.get(chaveBonusV26(detalhe.area, detalhe.setor, detalhe.usuario_id)) || null;
    const dias = ajuste ? Number(ajuste.dias_considerados || 0) : detalhe.dias.size;
    const metaPeriodo = Number(regra.meta_diaria || 0) * dias;
    const excedente = Math.max(0, detalhe.quantidade - metaPeriodo);
    funcionario.bonus_centavos += excedente * Number(regra.valor_excedente_centavos || 0);
  }

  const equipe = [];
  for (const [usuarioId, dados] of porFuncionario.entries()) {
    const usuario = usuarioMap.get(Number(usuarioId));
    if (!usuario) continue;
    equipe.push({ ...usuario, ...dados });
  }
  equipe.sort((a, b) => Number(b.total) - Number(a.total) || String(a.nome).localeCompare(String(b.nome), "pt-BR"));

  const remessas = (remessasRes.results || []).filter(remessa => {
    const d = Number(remessa.digital_total || 0) > 0;
    const c = Number(remessa.convencional_total || 0) > 0;
    if (area === "DIGITAL") return d;
    if (area === "CONVENCIONAL") return c;
    return d || c;
  }).slice(0, 8).map(remessa => {
    const total = (area === "CONVENCIONAL" ? 0 : Number(remessa.digital_total || 0)) +
      (area === "DIGITAL" ? 0 : Number(remessa.convencional_total || 0));
    const prontos = (area === "CONVENCIONAL" ? 0 : Number(remessa.digital_prontos || 0)) +
      (area === "DIGITAL" ? 0 : Number(remessa.convencional_prontos || 0));
    const percentual = total > 0 ? Math.min(100, Math.round((prontos / total) * 100)) : 0;
    return { ...remessa, total_filtrado: total, prontos_filtrado: prontos, percentual };
  });

  const [paradosDigital, paradosConv, remessasPrazo, remessasAtrasadas, qualidade, retrabalhosConv, muflas] = alertas;
  const alertasResumo = {
    parados_digital: incluirDigital ? Number(paradosDigital?.total || 0) : 0,
    parados_convencional: incluirConvencional ? Number(paradosConv?.total || 0) : 0,
    remessas_prazo: Number(remessasPrazo?.total || 0),
    remessas_atrasadas: Number(remessasAtrasadas?.total || 0),
    qualidade: incluirConvencional ? Number(qualidade?.total || 0) : 0,
    retrabalhos_conv: incluirConvencional ? Number(retrabalhosConv?.total || 0) : 0,
    muflas_ativas: incluirConvencional ? Number(muflas?.total || 0) : 0
  };

  return {
    setoresDigital,
    setoresConv,
    equipe,
    remessas,
    alertas: alertasResumo,
    total_producao: equipe.reduce((soma, item) => soma + Number(item.total || 0), 0),
    total_bonus_centavos: equipe.reduce((soma, item) => soma + Number(item.bonus_centavos || 0), 0)
  };
}

function paginaDashboardV26(usuario, dados, inicio, fim, area) {
  const hoje = hojeIsoV26();
  const semana = inicioSemanaIsoV26(hoje);
  const mes = inicioMesIsoV26(hoje);
  const podeBonus = isCoord(usuario);

  const qsArea = encodeURIComponent(area);
  const linkPeriodo = (a, b) => `/dashboard?area=${qsArea}&inicio=${encodeURIComponent(a)}&fim=${encodeURIComponent(b)}`;
  const totalParados = Number(dados.alertas.parados_digital || 0) + Number(dados.alertas.parados_convencional || 0);

  const linhasDigital = [...dados.setoresDigital.entries()].map(([setor, total]) => `
    <tr><td>${escapeHtml(setor)}</td><td style="text-align:right"><strong>${Number(total || 0)}</strong></td></tr>
  `).join("");
  const linhasConv = [...dados.setoresConv.entries()].map(([setor, total]) => `
    <tr><td>${escapeHtml(nomeSetorConvencional(setor))}</td><td style="text-align:right"><strong>${Number(total || 0)}</strong></td></tr>
  `).join("");

  const alertas = [
    area !== "CONVENCIONAL" ? { total: dados.alertas.parados_digital, titulo: "Digital em andamento há 2+ dias", href: "/trabalhos" } : null,
    area !== "DIGITAL" ? { total: dados.alertas.parados_convencional, titulo: "Convencional em andamento há 2+ dias", href: "/convencional" } : null,
    { total: dados.alertas.remessas_atrasadas, titulo: "Remessas atrasadas", href: "/municipios" },
    { total: dados.alertas.remessas_prazo, titulo: "Remessas vencendo em até 3 dias", href: "/municipios" },
    area !== "DIGITAL" ? { total: dados.alertas.qualidade, titulo: "Peças aguardando Qualidade", href: "/convencional/setor?setor=QUALIDADE" } : null,
    area !== "DIGITAL" ? { total: dados.alertas.retrabalhos_conv, titulo: "Retrabalhos convencionais ativos", href: "/convencional" } : null,
    area !== "DIGITAL" ? { total: dados.alertas.muflas_ativas, titulo: "Cargas de mufla em uso", href: "/convencional/muflas" } : null
  ].filter(Boolean);

  const cardsAlertas = alertas.map(item => `
    <a href="${item.href}" class="card" style="text-decoration:none;color:inherit;display:block;border-left:4px solid ${Number(item.total || 0) > 0 ? '#d78b00' : '#2f9e73'}">
      <div class="mini">${escapeHtml(item.titulo)}</div>
      <strong style="font-size:28px">${Number(item.total || 0)}</strong>
    </a>
  `).join("");

  const linhasEquipe = dados.equipe.slice(0, 10).map((item, indice) => `
    <tr>
      <td><strong>${indice + 1}º</strong></td>
      <td>${escapeHtml(item.nome)}</td>
      <td>${Number(item.total || 0)}</td>
      <td>${Number(item.digital || 0)}</td>
      <td>${Number(item.convencional || 0)}</td>
      ${podeBonus ? `<td><strong>${formatarMoedaCentavosV25(item.bonus_centavos)}</strong>${Number(item.sem_regra || 0) ? `<div class="mini">${Number(item.sem_regra)} setor(es) sem regra</div>` : ""}</td>` : ""}
    </tr>
  `).join("");

  const linhasRemessas = dados.remessas.map(item => {
    const atrasada = !item.data_entrega_real && String(item.data_prevista_entrega || "") < hoje;
    const modo = modoProducaoRemessa(item);
    return `
      <tr>
        <td><a href="/municipios/detalhe?nome=${encodeURIComponent(item.municipio)}"><strong>${escapeHtml(item.municipio)} · ${String(item.numero).padStart(2, "0")}</strong></a><div class="mini">${escapeHtml(modo)}</div></td>
        <td>${escapeHtml(formatarDataCurta(item.data_recebimento))}</td>
        <td>${escapeHtml(formatarDataCurta(item.data_prevista_entrega))}${atrasada ? `<div class="mini" style="font-weight:800">ATRASADA</div>` : ""}</td>
        <td>${Number(item.prontos_filtrado || 0)} / ${Number(item.total_filtrado || 0)}</td>
        <td><strong>${Number(item.percentual || 0)}%</strong><div style="height:8px;background:#e6ecee;border-radius:99px;overflow:hidden;margin-top:5px"><div style="width:${Number(item.percentual || 0)}%;height:100%;background:currentColor;opacity:.55"></div></div></td>
      </tr>
    `;
  }).join("");

  return layout(`
    <div class="cabecalho-pagina">
      <div>
        <h2>▣ Dashboard operacional</h2>
        <p class="nota">Visão consolidada do laboratório. “Parado” aqui significa etapa em andamento há pelo menos 2 dias.</p>
      </div>
      <div class="acoes"><a class="botao botao-sec" href="/producao-equipe">Produção da equipe</a><a class="botao" href="/">← Painel</a></div>
    </div>

    <div class="card" style="margin-bottom:17px">
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px">
        <strong>Período rápido:</strong>
        <a class="botao botao-sec" style="margin:0" href="${linkPeriodo(hoje, hoje)}">Hoje</a>
        <a class="botao botao-sec" style="margin:0" href="${linkPeriodo(semana, hoje)}">Esta semana</a>
        <a class="botao botao-sec" style="margin:0" href="${linkPeriodo(mes, hoje)}">Este mês</a>
      </div>
      <form method="GET" action="/dashboard">
        <div class="form-grid">
          <label>Início<input type="date" name="inicio" value="${escapeHtml(inicio)}" required></label>
          <label>Fim<input type="date" name="fim" value="${escapeHtml(fim)}" required></label>
          <label>Área<select name="area"><option value="AMBOS" ${area === "AMBOS" ? "selected" : ""}>Digital + Convencional</option><option value="DIGITAL" ${area === "DIGITAL" ? "selected" : ""}>Digital</option><option value="CONVENCIONAL" ${area === "CONVENCIONAL" ? "selected" : ""}>Convencional</option></select></label>
          <div style="align-self:end"><button>Atualizar dashboard</button></div>
        </div>
      </form>
    </div>

    <div class="grid" style="margin-bottom:17px">
      <div class="card"><h2>Produção no período</h2><strong style="font-size:30px">${Number(dados.total_producao || 0)}</strong><p class="nota">operações/peças concluídas nos setores exibidos.</p></div>
      <div class="card"><h2>Equipe ativa no período</h2><strong style="font-size:30px">${dados.equipe.length}</strong><p class="nota">funcionário(s) com produção concluída.</p></div>
      <div class="card"><h2>Em andamento há 2+ dias</h2><strong style="font-size:30px">${totalParados}</strong><p class="nota">trabalhos que merecem conferência.</p></div>
      ${podeBonus ? `<div class="card"><h2>Bonificação estimada</h2><strong style="font-size:30px">${formatarMoedaCentavosV25(dados.total_bonus_centavos)}</strong><p class="nota">considerando regras aplicáveis ao período.</p></div>` : ""}
    </div>

    <h2>Alertas operacionais</h2>
    <div class="grid" style="margin-bottom:22px">${cardsAlertas}</div>

    <div class="grid" style="margin-bottom:22px">
      ${area !== "CONVENCIONAL" ? `<div class="card"><h2>🖥 Digital</h2><p class="nota">Produção concluída no período por setor.</p><div class="tabela-wrap"><table><thead><tr><th>Setor</th><th style="text-align:right">Produção</th></tr></thead><tbody>${linhasDigital}</tbody></table></div></div>` : ""}
      ${area !== "DIGITAL" ? `<div class="card"><h2>🦷 Convencional</h2><p class="nota">Produção concluída no período por setor.</p><div class="tabela-wrap"><table><thead><tr><th>Setor</th><th style="text-align:right">Produção</th></tr></thead><tbody>${linhasConv}</tbody></table></div></div>` : ""}
    </div>

    <div class="card" style="margin-bottom:22px">
      <div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap"><div><h2 style="margin-bottom:3px">Produção da equipe</h2><p class="nota" style="margin:0">Ranking operacional do período selecionado.</p></div><a class="botao botao-sec" href="/producao-equipe?area=${area === "CONVENCIONAL" ? "CONVENCIONAL" : "DIGITAL"}&inicio=${encodeURIComponent(inicio)}&fim=${encodeURIComponent(fim)}">Abrir relatório completo</a></div>
      <div class="tabela-wrap" style="margin-top:14px"><table><thead><tr><th>#</th><th>Funcionário</th><th>Total</th><th>Digital</th><th>Convencional</th>${podeBonus ? "<th>Bonificação estimada</th>" : ""}</tr></thead><tbody>${linhasEquipe || `<tr><td colspan="${podeBonus ? 6 : 5}">Nenhuma produção encontrada no período.</td></tr>`}</tbody></table></div>
    </div>

    <div class="card">
      <div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap"><div><h2 style="margin-bottom:3px">Remessas abertas</h2><p class="nota" style="margin:0">Andamento por pacientes vinculados à remessa.</p></div><a class="botao botao-sec" href="/municipios">Abrir Municípios / Remessas</a></div>
      <div class="tabela-wrap" style="margin-top:14px"><table><thead><tr><th>Município / remessa</th><th>Chegada</th><th>Previsão</th><th>Prontos</th><th>Progresso</th></tr></thead><tbody>${linhasRemessas || `<tr><td colspan="5">Nenhuma remessa aberta encontrada para este filtro.</td></tr>`}</tbody></table></div>
    </div>
  `, "Dashboard", usuario);
}

/* =========================================================
   MUNICÍPIOS
========================================================= */

async function listarMunicipiosResumo(
  env,
  busca = ""
) {
  const q = String(busca || "").trim().toLowerCase();
  const termo = `%${q}%`;

  const resultado = await env.db.prepare(`
    WITH nomes AS (
      SELECT lower(trim(municipio)) AS chave, trim(municipio) AS municipio
      FROM trabalhos
      WHERE excluido = 0 AND trim(municipio) <> ''

      UNION ALL

      SELECT lower(trim(municipio)) AS chave, trim(municipio) AS municipio
      FROM trabalhos_convencionais
      WHERE excluido = 0 AND trim(municipio) <> ''

      UNION ALL

      SELECT lower(trim(municipio)) AS chave, trim(municipio) AS municipio
      FROM remessas
      WHERE trim(municipio) <> ''
    ),
    municipios AS (
      SELECT chave, MIN(municipio) AS municipio
      FROM nomes
      GROUP BY chave
    )
    SELECT
      m.municipio,
      m.chave,

      (SELECT COUNT(*) FROM remessas r
       WHERE lower(trim(r.municipio)) = m.chave) AS total_remessas,

      (SELECT COUNT(*) FROM remessas r
       WHERE lower(trim(r.municipio)) = m.chave
         AND r.data_finalizacao IS NULL
         AND r.data_entrega_real IS NULL) AS remessas_em_producao,

      (SELECT COUNT(*) FROM remessas r
       WHERE lower(trim(r.municipio)) = m.chave
         AND r.data_finalizacao IS NOT NULL
         AND r.data_entrega_real IS NULL) AS remessas_finalizadas,

      (SELECT COUNT(*) FROM remessas r
       WHERE lower(trim(r.municipio)) = m.chave
         AND r.data_entrega_real IS NOT NULL) AS remessas_entregues,

      (SELECT COUNT(*) FROM trabalhos t
       WHERE t.excluido = 0
         AND lower(trim(t.municipio)) = m.chave) AS digital_total,

      (SELECT COUNT(*) FROM trabalhos t
       WHERE t.excluido = 0
         AND lower(trim(t.municipio)) = m.chave
         AND t.entregue = 1) AS digital_entregues,

      (SELECT COUNT(*) FROM trabalhos t
       WHERE t.excluido = 0
         AND lower(trim(t.municipio)) = m.chave
         AND t.entregue = 0
         AND NOT EXISTS (
           SELECT 1 FROM etapas e
           WHERE e.trabalho_id = t.id AND e.status != 'CONCLUIDO'
         )) AS digital_concluidos,

      (SELECT COUNT(*) FROM trabalhos t
       WHERE t.excluido = 0
         AND lower(trim(t.municipio)) = m.chave
         AND t.entregue = 0
         AND EXISTS (
           SELECT 1 FROM etapas e
           WHERE e.trabalho_id = t.id AND e.status != 'CONCLUIDO'
         )) AS digital_em_producao,

      (SELECT COUNT(*) FROM trabalhos_convencionais tc
       WHERE tc.excluido = 0
         AND lower(trim(tc.municipio)) = m.chave) AS convencional_total,

      (SELECT COUNT(*) FROM trabalhos_convencionais tc
       WHERE tc.excluido = 0
         AND lower(trim(tc.municipio)) = m.chave
         AND tc.status = 'QUALIDADE') AS convencional_qualidade,

      (SELECT COUNT(*) FROM trabalhos_convencionais tc
       WHERE tc.excluido = 0
         AND lower(trim(tc.municipio)) = m.chave
         AND tc.status IN ('LIBERADO_ENTREGA','CONCLUIDO')) AS convencional_liberados,

      (SELECT COUNT(*) FROM trabalhos_convencionais tc
       WHERE tc.excluido = 0
         AND lower(trim(tc.municipio)) = m.chave
         AND tc.status NOT IN ('LIBERADO_ENTREGA','CONCLUIDO')) AS convencional_em_producao

    FROM municipios m
    WHERE
      ? = ''
      OR m.chave LIKE ?
      OR EXISTS (
        SELECT 1
        FROM remessas r
        WHERE lower(trim(r.municipio)) = m.chave
          AND (
            lower('remessa ' || printf('%02d', r.numero)) LIKE ?
            OR CAST(r.numero AS TEXT) LIKE ?
          )
      )
    ORDER BY m.municipio COLLATE NOCASE
  `).bind(q, termo, termo, termo).all();

  return resultado.results || [];
}

function modoProducaoMunicipio(item) {
  const digital = Number(item.digital_total || 0) > 0;
  const convencional = Number(item.convencional_total || 0) > 0;
  if (digital && convencional) return "DIGITAL + CONVENCIONAL";
  if (digital) return "DIGITAL";
  if (convencional) return "CONVENCIONAL";
  return "SEM PRODUÇÃO VINCULADA";
}

