function normalizarNomeMunicipio(nome) {
  return String(nome || "").trim().replace(/\s+/g, " ");
}

async function contarTrabalhosMunicipio(env, municipio) {
  const resultado = await env.db.prepare(`
    SELECT
      (SELECT COUNT(*) FROM trabalhos
       WHERE lower(trim(municipio)) = lower(trim(?)))
      +
      (SELECT COUNT(*) FROM trabalhos_convencionais
       WHERE lower(trim(municipio)) = lower(trim(?)))
      +
      (SELECT COUNT(*) FROM remessas
       WHERE lower(trim(municipio)) = lower(trim(?))) AS total
  `).bind(municipio, municipio, municipio).first();
  return Number(resultado?.total || 0);
}

