async function listarAcessos(env) {

  const resultado =
    await env.db.prepare(`

      SELECT
        id,
        nome,
        usuario,
        perfil,
        ativo

      FROM usuarios

      WHERE
        perfil IN (
          'ADMINISTRADOR',
          'COORDENADOR',
          'GERENCIA',
          'CADASTRO'
        )

        AND excluido = 0

      ORDER BY

        CASE perfil

          WHEN 'ADMINISTRADOR'
          THEN 1

          WHEN 'COORDENADOR'
          THEN 2

          ELSE 3

        END,

        nome

    `)
    .all();

  return (
    resultado.results
    ||
    []
  );
}

