function blocoVincularRemessa(
  usuario,
  trabalho,
  remessas
) {

  if (
    !isCoord(usuario)
    ||
    trabalho.remessa_id
  ) {
    return "";
  }

  const lista =
    [
      ...(remessas || [])
    ]
    .sort(
      (a, b) => {

        const municipioTrabalho =
          String(
            trabalho.municipio
            ||
            ""
          )
          .trim()
          .toLowerCase();

        const aMesmo =
          String(
            a.municipio
            ||
            ""
          )
          .trim()
          .toLowerCase()
          ===
          municipioTrabalho
          ? 0
          : 1;

        const bMesmo =
          String(
            b.municipio
            ||
            ""
          )
          .trim()
          .toLowerCase()
          ===
          municipioTrabalho
          ? 0
          : 1;

        if (aMesmo !== bMesmo) {
          return aMesmo - bMesmo;
        }

        return String(
          a.data_prevista_entrega
          ||
          ""
        )
        .localeCompare(
          String(
            b.data_prevista_entrega
            ||
            ""
          )
        );
      }
    );

  if (!lista.length) {

    return `

<div
  class="info"
  style="margin-top:20px"
>
Este paciente está sem remessa. Ainda não existe nenhuma remessa disponível para vinculá-lo.
</div>
`;
  }

  const opcoes =
    lista.map(
      remessa => `

<option value="${remessa.id}">
${escapeHtml(
  remessa.municipio
)} · Remessa ${String(
  remessa.numero
  ||
  ""
).padStart(2, "0")} · entrega ${escapeHtml(
  formatarDataCurta(
    remessa.data_prevista_entrega
  )
)}
</option>
`
    )
    .join("");

  return `

<div
  class="card"
  style="
    margin-top:20px;
    border-color:#b9e6fe;
  "
>

<h2 style="margin-bottom:6px">
Vincular paciente a uma remessa
</h2>

<p class="nota">
Este paciente foi cadastrado sem remessa. Selecione uma remessa já existente. Ao vincular, o município do paciente será ajustado para o município da remessa escolhida.
</p>

<form
  method="POST"
  action="/trabalhos/${trabalho.id}/vincular-remessa"
  onsubmit="return confirm('Tem certeza que deseja vincular este paciente à remessa selecionada?');"
>

<label>
Atendimento / remessa

<select
  name="remessa_id"
  required
>

<option value="">
Selecione
</option>

${opcoes}

</select>

</label>

<button>
Adicionar à remessa
</button>

</form>

</div>
`;
}

