async function resumoEquipe(
  env,
  inicio,
  fim
) {

  const usuarios =
    (
      await env.db.prepare(`

        SELECT
          id,
          nome,
          setor,
          ativo

        FROM usuarios

        WHERE
          perfil =
            'FUNCIONARIO'

          AND excluido = 0

        ORDER BY
          setor,
          nome

      `)
      .all()
    ).results
    ||
    [];

  const unidades =
    await unidadesConcluidas(
      env,
      inicio,
      fim
    );

  const retrabalhos =
    (
      await env.db.prepare(`

        SELECT

          executado_por
            AS usuario_id,

          COUNT(*)
            AS total

        FROM retrabalhos

        WHERE
          status =
            'CONCLUIDO'

          AND executado_por
            IS NOT NULL

          AND date(
            concluido_em
          )
          BETWEEN ?
          AND ?

        GROUP BY
          executado_por

      `)
      .bind(
        inicio,
        fim
      )
      .all()
    ).results
    ||
    [];

  const retrabalhoMap =
    new Map(

      retrabalhos.map(
        item => [

          String(
            item.usuario_id
          ),

          Number(
            item.total
            ||
            0
          )
        ]
      )
    );

  return usuarios.map(
    usuario => {

      const producao =
        unidades.filter(
          item =>
            Number(
              item.usuario_id
            )
            ===
            Number(
              usuario.id
            )
        );

      const pacientes =
        new Map();

      for (
        const item
        of producao
      ) {

        if (
          !pacientes.has(
            String(
              item.trabalho_id
            )
          )
        ) {

          pacientes.set(
            String(
              item.trabalho_id
            ),
            item
          );
        }
      }

      return {

        ...usuario,

        quantidade:
          producao.length,

        pacientes:
          [
            ...pacientes.values()
          ],

        retrabalhos:
          retrabalhoMap.get(
            String(
              usuario.id
            )
          )
          ||
          0
      };
    }
  );
}

