/* =========================================================
   V3.4.20 · CHAT GERAL DA EQUIPE DIGITAL · 48 HORAS
========================================================= */

function siglaSetorChatDigitalV3420(setor) {
  const mapa = {
    "CAD/CAM": "CAD",
    FATIAMENTO: "FAT",
    IMPRESSAO: "IMP",
    ACABAMENTO: "ACB"
  };
  return mapa[String(setor || "").toUpperCase()] || String(setor || "").slice(0, 5);
}

function seloAutorChatDigitalV3420(item) {
  if (item.perfil === "ADMINISTRADOR") return "👑 ADM";
  if (item.perfil === "COORDENADOR") return "◆ COORDENADOR";
  if (item.perfil === "GERENCIA") return "★ GERENTE DIGITAL";
  const setores = listaPipeV31(item.setores_digitais)
    .filter(setor => SETORES.includes(setor))
    .map(siglaSetorChatDigitalV3420);
  return setores.length ? `● ${setores.join(" + ")}` : "● FUNCIONÁRIO";
}

function corAutorChatDigitalV3420(id, nome = "") {
  const paleta = [
    "#22c55e", "#38bdf8", "#f59e0b", "#e879f9", "#fb7185", "#a78bfa",
    "#2dd4bf", "#f97316", "#84cc16", "#60a5fa", "#f472b6", "#c084fc"
  ];
  let hash = Number(id) || 0;
  for (const ch of String(nome)) hash = ((hash * 33) + ch.charCodeAt(0)) >>> 0;
  return paleta[Math.abs(hash) % paleta.length];
}

async function limparChatEquipeDigitalV3420(env) { return await limparChatEquipeDigitalV3420ServiceV54(env); }

async function listarChatEquipeDigitalV3420(env) { return await listarChatEquipeDigitalV3420ServiceV54(env); }

function rotuloDiaChatV313(dataIso){
  const d = new Date(dataIso);
  const fmt = (x) => new Intl.DateTimeFormat("en-CA", {timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(x);
  const dia = fmt(d);
  const hoje = fmt(new Date());
  const ontem = fmt(new Date(Date.now() - 24*60*60*1000));
  if (dia === hoje) return "Hoje";
  if (dia === ontem) return "Ontem";
  return new Intl.DateTimeFormat("pt-BR", {timeZone:"America/Sao_Paulo",day:"2-digit",month:"2-digit",year:"numeric"}).format(d);
}

function horaCurtaChatV313(dataIso){
  const d = new Date(dataIso);
  return new Intl.DateTimeFormat("pt-BR", {timeZone:"America/Sao_Paulo",hour:"2-digit",minute:"2-digit",hour12:false}).format(d);
}

function avatarChatV313(item, classe){
  const av = avatarEmojiV310(item.avatar);
  if (av) return `<span class="${classe}">${av}</span>`;
  if (item.tem_foto) return `<span class="${classe}"><img src="/foto-usuario/${Number(item.autor_id)}" alt="" onerror="this.remove()" style="width:100%;height:100%;object-fit:cover;border-radius:50%"></span>`;
  const inicial = String(item.nome || "U").trim().slice(0, 1).toUpperCase();
  const cor = corAutorChatDigitalV3420(item.autor_id, item.nome);
  return `<span class="${classe}" style="background:${cor}22;border-color:${cor};color:${cor};font-weight:800">${escapeHtml(inicial)}</span>`;
}

function renderChatEquipeDigitalV3420(mensagens, usuario) {
  if (!mensagens.length) {
    return `<div class="chat-vazio-v313"><div><strong>Nada por aqui ainda.</strong><br><span class="mini">Mande a primeira mensagem para a equipe.</span></div></div>`;
  }
  let html = "";
  let ultimoDia = null;
  let i = 0;
  while (i < mensagens.length) {
    const item = mensagens[i];
    const dia = rotuloDiaChatV313(item.criado_em);
    if (dia !== ultimoDia) {
      html += `<div class="chat-separador-dia-v313"><span>${escapeHtml(dia)}</span></div>`;
      ultimoDia = dia;
    }
    const minha = Number(item.autor_id) === Number(usuario.id);
    const anterior = i > 0 ? mensagens[i-1] : null;
    const primeiroDoBloco = !anterior || Number(anterior.autor_id) !== Number(item.autor_id) || rotuloDiaChatV313(anterior.criado_em) !== dia;
    let fimDoBloco = true;
    const proximo = mensagens[i+1];
    if (proximo && Number(proximo.autor_id) === Number(item.autor_id) && rotuloDiaChatV313(proximo.criado_em) === dia) fimDoBloco = false;
    const cor = corAutorChatDigitalV3420(item.autor_id, item.nome);
    html += `<div class="chat-linha-v313 ${minha ? "chat-linha-meu" : "chat-linha-outro"}${fimDoBloco ? "" : " chat-sem-espaco"}" data-chat-id="${Number(item.id)}" data-chat-autor="${Number(item.autor_id || 0)}">
      ${!minha ? `<div class="chat-lado-avatar-v313">${primeiroDoBloco ? avatarChatV313(item, "chat-avatar-v311") : ""}</div>` : ""}
      <div class="chat-bloco-v313">
        ${!minha && primeiroDoBloco ? `<div class="chat-autor-v313"><span style="color:${cor}">${escapeHtml(item.nome || "Usuário")}</span><span class="chat-cargo-v313">${escapeHtml(seloAutorChatDigitalV3420(item))}</span></div>` : ""}
        <div class="chat-balao-v313${minha ? " chat-balao-meu" : ""}">
          <div class="chat-texto-v313">${escapeHtml(item.mensagem)}</div>
          ${Number(item.favorita) ? `<div class="chat-fav-marca-v313">⭐ Favoritada</div>` : ""}
          <div class="chat-hora-v313">${escapeHtml(horaCurtaChatV313(item.criado_em))}</div>
          <form method="POST" action="/digital/chat-equipe/favoritar" class="chat-fav-form-v313">
            <input type="hidden" name="id" value="${Number(item.id)}">
            <input type="hidden" name="favorita" value="${Number(item.favorita) ? 0 : 1}">
            <button type="submit" class="chat-fav-botao" title="${Number(item.favorita) ? "Desfavoritar" : "Favoritar: a mensagem não será apagada"}">${Number(item.favorita) ? "★" : "☆"}</button>
          </form>
        </div>
      </div>
    </div>`;
    i++;
  }
  return html;
}

function paginaChatEquipeDigitalV3420(usuario, mensagens, mensagem = "", tipo = "sucesso") {
  const setores = usuario.perfil === "FUNCIONARIO"
    ? setoresUsuarioV31(usuario, "DIGITAL").filter(s => SETORES.includes(s)).map(siglaSetorChatDigitalV3420).join(" + ")
    : "Gestão Digital";
  return layout(`
    <div class="cabecalho-pagina">
      <div>
        <h2>💬 Chat da equipe Digital</h2>
        <p class="nota">CAD/CAM, Fatiamento, Impressão, Acabamento e gestão no mesmo canal. As mensagens somem sozinhas ao completar 48 horas. A ⭐ marca o que fica guardado, e só sai quando alguém desfavoritar.</p>
      </div>
      <a class="botao botao-sec" href="/digital">← Área Digital</a>
    </div>
    ${mensagem ? `<div class="${tipo}">${escapeHtml(mensagem)}</div>` : ""}
    <div class="chat-equipe-wrap">
      <section class="card chat-equipe-info">
        <div><strong>Equipe Digital</strong><div class="mini">Você está identificado como ${escapeHtml(setores || perfilNome(usuario.perfil))}.</div></div>
        <div class="chat-equipe-legenda">
          <span class="chat-equipe-selo">👑 ADM</span><span class="chat-equipe-selo">◆ Coordenador</span><span class="chat-equipe-selo">★ Gerente</span><span class="chat-equipe-selo">● CAD / FAT / IMP / ACB</span>
          <div class="chat-notificacao-controles">
            <button type="button" class="botao botao-sec" id="chat-equipe-som-v35" style="padding:6px 10px">🔊 Ativar som</button>
            <button type="button" class="botao botao-sec" id="chat-equipe-testar-som-v35" style="padding:6px 10px">🎵 Testar som</button>
            <button type="button" class="botao botao-sec" id="chat-equipe-popup-v35" style="padding:6px 10px">🔔 Ativar pop-up</button>
            <span class="chat-notificacao-status" id="chat-equipe-status-v35"></span>
          </div>
        </div>
      </section>
      <section class="chat-equipe-lista chat-lista-v313" id="chat-equipe-lista">${renderChatEquipeDigitalV3420(mensagens, usuario)}</section>
      <form class="chat-rodape-v313" method="POST" action="/digital/chat-equipe">
        <textarea name="mensagem" required minlength="1" maxlength="1500" placeholder="Mensagem" rows="1"></textarea>
        <button type="submit" title="Enviar" aria-label="Enviar">➤</button>
      </form>
    </div>
    <script>
    (function(){
      const caixa=document.getElementById('chat-equipe-lista');
      const botaoSom=document.getElementById('chat-equipe-som-v35');
      const botaoTesteSom=document.getElementById('chat-equipe-testar-som-v35');
      const botaoPopup=document.getElementById('chat-equipe-popup-v35');
      const statusAviso=document.getElementById('chat-equipe-status-v35');
      if(!caixa)return;
      const meuId=${Number(usuario?.id || 0)};
      const chaveSom='fluxolab-chat-digital-som-v35';
      let somAtivo=localStorage.getItem(chaveSom)==='1';
      let audioCtx=null;
      let audioLiberado=false;
      const maiorId=(raiz)=>Math.max(0,...[...raiz.querySelectorAll('[data-chat-id]')].map(el=>Number(el.dataset.chatId||0)));
      let ultimoId=maiorId(caixa);
      const irParaOFim=()=>{caixa.scrollTop=caixa.scrollHeight;};
      irParaOFim();
      const campoTexto=document.querySelector('.chat-rodape-v313 textarea');
      if(campoTexto){
        campoTexto.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();campoTexto.form.requestSubmit();}});
      }
      const informar=(texto)=>{if(statusAviso)statusAviso.textContent=texto||'';};
      const atualizarSom=()=>{
        if(!botaoSom)return;
        botaoSom.textContent=somAtivo?(audioLiberado?'🔊 Som ativo':'🔊 Som ativo · aguardando liberação'):'🔇 Ativar som';
      };
      const atualizarPopup=()=>{
        if(!botaoPopup)return;
        if(!('Notification' in window)){botaoPopup.textContent='🔕 Pop-up indisponível';botaoPopup.disabled=true;return;}
        if(Notification.permission==='granted')botaoPopup.textContent='🔔 Pop-up ativo';
        else if(Notification.permission==='denied')botaoPopup.textContent='🚫 Pop-up bloqueado';
        else botaoPopup.textContent='🔔 Ativar pop-up';
      };
      const prepararAudio=async(forcar=false)=>{
        if(!somAtivo&&!forcar)return false;
        try{
          const Ctx=window.AudioContext||window.webkitAudioContext;
          if(!Ctx){informar('Este navegador não oferece áudio do chat.');return false;}
          if(!audioCtx)audioCtx=new Ctx();
          if(audioCtx.state==='suspended')await audioCtx.resume();
          audioLiberado=audioCtx.state==='running';
          atualizarSom();
          return audioLiberado;
        }catch(_){audioLiberado=false;atualizarSom();return false;}
      };
      const tocarSom=async(forcar=false)=>{
        if(!somAtivo&&!forcar)return false;
        if(!(await prepararAudio(forcar)))return false;
        try{
          const agora=audioCtx.currentTime;
          [[0,740],[0.11,920],[0.22,1120]].forEach(([atraso,freq])=>{
            const osc=audioCtx.createOscillator(),ganho=audioCtx.createGain();
            osc.type='sine';osc.frequency.setValueAtTime(freq,agora+atraso);
            ganho.gain.setValueAtTime(0.0001,agora+atraso);
            ganho.gain.exponentialRampToValueAtTime(0.28,agora+atraso+0.018);
            ganho.gain.exponentialRampToValueAtTime(0.0001,agora+atraso+0.105);
            osc.connect(ganho);ganho.connect(audioCtx.destination);
            osc.start(agora+atraso);osc.stop(agora+atraso+0.12);
          });
          return true;
        }catch(_){return false;}
      };
      const ativarSomETestar=async()=>{
        somAtivo=true;
        localStorage.setItem(chaveSom,'1');
        const ok=await prepararAudio(true);
        if(ok){await tocarSom(true);informar('Som liberado. O teste acabou de tocar.');}
        else informar('O navegador bloqueou o áudio. Clique novamente em “Testar som” e confira o volume da aba/sistema.');
        atualizarSom();
      };
      if(botaoSom)botaoSom.addEventListener('click',async()=>{
        if(somAtivo){
          somAtivo=false;localStorage.setItem(chaveSom,'0');informar('Som do chat desativado.');atualizarSom();
        }else await ativarSomETestar();
      });
      if(botaoTesteSom)botaoTesteSom.addEventListener('click',async()=>{
        if(!somAtivo){await ativarSomETestar();return;}
        const ok=await tocarSom(true);
        informar(ok?'Teste de som executado.':'Não foi possível liberar o áudio. Confira o volume e a permissão do navegador.');
      });
      const armarPorInteracao=async()=>{if(somAtivo&&!audioLiberado)await prepararAudio(true);};
      window.addEventListener('pointerdown',armarPorInteracao,{once:true,capture:true});
      window.addEventListener('keydown',armarPorInteracao,{once:true,capture:true});
      const ativarPopup=async()=>{
        if(!('Notification' in window)){informar('Este navegador não suporta notificações do sistema.');return;}
        if(Notification.permission==='denied'){
          informar('Pop-up bloqueado pelo navegador. Libere Notificações nas permissões deste site e recarregue a página.');
          atualizarPopup();return;
        }
        try{
          const permissao=Notification.permission==='granted'?'granted':await Notification.requestPermission();
          atualizarPopup();
          if(permissao==='granted'){
            informar('Pop-up de mensagens ativado.');
            const n=new Notification('Fluxo Lab · notificações ativadas',{body:'As novas mensagens do Chat Digital poderão aparecer aqui.'});
            setTimeout(()=>{try{n.close();}catch(_){ }},4500);
          }else informar('Permissão de notificação não concedida.');
        }catch(_){informar('Não foi possível solicitar a permissão de notificação.');}
      };
      if(botaoPopup)botaoPopup.addEventListener('click',ativarPopup);
      const garantirToastArea=()=>{
        let area=document.getElementById('chat-notificacao-toast-area-v35');
        if(!area){area=document.createElement('div');area.id='chat-notificacao-toast-area-v35';area.className='chat-notificacao-toast-area';document.body.appendChild(area);}
        return area;
      };
      const dadosMensagem=(el)=>({
        id:Number(el?.dataset?.chatId||0),
        autor:Number(el?.dataset?.chatAutor||0),
        nome:(el?.querySelector('.chat-autor-v313')?.textContent||'Equipe Digital').trim(),
        texto:(el?.querySelector('.chat-texto-v313')?.textContent||'Nova mensagem').trim()
      });
      const mostrarToast=(novas)=>{
        if(!novas.length)return;
        const dados=dadosMensagem(novas[novas.length-1]);
        const area=garantirToastArea();
        const toast=document.createElement('div');toast.className='chat-notificacao-toast';
        const extra=novas.length>1?'<span class="mini">+'+(novas.length-1)+' outra(s) mensagem(ns)</span>':'';
        toast.innerHTML='<strong>💬 '+escapeHtmlCliente(dados.nome)+'</strong><span class="mini">'+escapeHtmlCliente(dados.texto.slice(0,180))+'</span>'+extra;
        toast.addEventListener('click',()=>{window.focus();caixa.scrollTop=caixa.scrollHeight;toast.remove();});
        area.appendChild(toast);
        setTimeout(()=>toast.remove(),8000);
      };
      const escapeHtmlCliente=(valor)=>String(valor??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      const notificarSistema=(novas)=>{
        if(!novas.length||!('Notification' in window)||Notification.permission!=='granted')return;
        const dados=dadosMensagem(novas[novas.length-1]);
        const titulo=novas.length>1?'Fluxo Lab · '+novas.length+' novas mensagens':'Fluxo Lab · '+dados.nome;
        const corpo=(novas.length>1?'Última: ':'')+(dados.texto||'Nova mensagem no Chat Digital').slice(0,220);
        try{
          const n=new Notification(titulo,{body:corpo,tag:'fluxolab-chat-digital-'+dados.id});
          n.onclick=()=>{try{window.focus();location.href='/digital/chat-equipe';n.close();}catch(_){ }};
          setTimeout(()=>{try{n.close();}catch(_){ }},12000);
        }catch(_){ }
      };
      atualizarSom();
      atualizarPopup();
      const irFim=()=>{caixa.scrollTop=caixa.scrollHeight;};
      irFim();
      setInterval(async()=>{
        try{
          const pertoFim=(caixa.scrollHeight-caixa.scrollTop-caixa.clientHeight)<120;
          caixa.dataset.carregando='1';
          const r=await fetch('/api/digital/chat-equipe',{headers:{'x-fluxolab':'1'},cache:'no-store'});
          if(r.ok){
            const html=await r.text();
            const temp=document.createElement('div');temp.innerHTML=html;
            const itens=[...temp.querySelectorAll('[data-chat-id]')];
            const novas=itens.filter(el=>Number(el.dataset.chatId||0)>ultimoId&&Number(el.dataset.chatAutor||0)!==meuId);
            caixa.innerHTML=html;
            ultimoId=maiorId(caixa);
            if(pertoFim)irFim();
            if(novas.length){
              tocarSom();
              mostrarToast(novas);
              notificarSistema(novas);
            }
          }
        }catch(e){}finally{delete caixa.dataset.carregando;}
      },12000);
    })();
    </script>
  `, "Chat equipe Digital", usuario);
}

function erroMigracaoChatDigitalV3420(erro) {
  return /no such table:\s*chat_equipe_digital/i.test(String(erro?.message || erro));
}

/* =========================================================
   MENSAGENS PRIVADAS
========================================================= */

function perfilGestaoMensagens(perfil) {
  return [
    "ADMINISTRADOR",
    "COORDENADOR",
    "GERENCIA"
  ].includes(
    perfil
  );
}

async function existeConversaPrivada(env, usuarioA, usuarioB) { return await existeConversaPrivadaServiceV54(env, usuarioA, usuarioB); }

async function podeConversarPrivado(env, usuario, alvo) { return await podeConversarPrivadoServiceV54(env, usuario, alvo, { perfilGestaoMensagens, isGerencia, areaGerenciaV31, areasUsuarioV31 }); }

function iniciaisUsuario(nome) {
  return String(
    nome
    ||
    "U"
  )
  .trim()
  .split(/\s+/)
  .slice(0, 2)
  .map(
    parte =>
      parte.charAt(0)
  )
  .join("")
  .toUpperCase();
}

async function listarContatosMensagens(
  env,
  usuario
) {

  if (
    perfilGestaoMensagens(
      usuario.perfil
    )
  ) {

    const resultado =
      await env.db.prepare(`

        SELECT

          u.id,
          u.nome,
          u.usuario,
          u.setor,
          u.perfil,
          u.ativo,
          u.excluido,

          (
            SELECT
              COUNT(*)

            FROM mensagens_privadas m

            WHERE
              m.remetente_id = u.id

              AND m.destinatario_id = ?

              AND m.lido = 0
          )
          AS nao_lidas,

          (
            SELECT
              MAX(m.criado_em)

            FROM mensagens_privadas m

            WHERE
              (
                m.remetente_id = u.id
                AND m.destinatario_id = ?
              )

              OR

              (
                m.remetente_id = ?
                AND m.destinatario_id = u.id
              )
          )
          AS ultima_mensagem

        FROM usuarios u

        WHERE
          u.perfil =
            'FUNCIONARIO'

          AND u.ativo = 1

          AND u.excluido = 0

        ORDER BY

          CASE
            WHEN ultima_mensagem IS NULL
            THEN 1
            ELSE 0
          END,

          ultima_mensagem DESC,

          u.nome
            COLLATE NOCASE

      `)
      .bind(
        usuario.id,
        usuario.id,
        usuario.id
      )
      .all();

    let contatos = resultado.results || [];
    if (isGerencia(usuario)) {
      const area = areaGerenciaV31(usuario);
      if (!area) return [];
      const permitidos = await env.db.prepare(`
        SELECT usuario_id
        FROM usuario_areas
        WHERE area = ? AND ativo = 1
      `).bind(area).all();
      const ids = new Set((permitidos.results || []).map(item => Number(item.usuario_id)));
      contatos = contatos.filter(item => ids.has(Number(item.id)));
    }
    return contatos;
  }

  if (
    usuario.perfil ===
      "FUNCIONARIO"
  ) {

    const resultado =
      await env.db.prepare(`

        SELECT

          u.id,
          u.nome,
          u.usuario,
          u.setor,
          u.perfil,
          u.ativo,
          u.excluido,

          (
            SELECT
              COUNT(*)

            FROM mensagens_privadas m

            WHERE
              m.remetente_id = u.id

              AND m.destinatario_id = ?

              AND m.lido = 0
          )
          AS nao_lidas,

          (
            SELECT
              MAX(m.criado_em)

            FROM mensagens_privadas m

            WHERE
              (
                m.remetente_id = u.id
                AND m.destinatario_id = ?
              )

              OR

              (
                m.remetente_id = ?
                AND m.destinatario_id = u.id
              )
          )
          AS ultima_mensagem

        FROM usuarios u

        WHERE
          u.perfil IN (
            'ADMINISTRADOR',
            'COORDENADOR',
            'GERENCIA'
          )

          AND u.ativo = 1

          AND u.excluido = 0

        ORDER BY
          ultima_mensagem DESC,
          u.nome COLLATE NOCASE

      `)
      .bind(
        usuario.id,
        usuario.id,
        usuario.id
      )
      .all();

    const contatos = resultado.results || [];
    const areasFuncionario = new Set(areasUsuarioV31(usuario));
    if (!areasFuncionario.size) return contatos.filter(item => ["ADMINISTRADOR", "COORDENADOR"].includes(item.perfil));

    const gerencias = contatos.filter(item => item.perfil === "GERENCIA");
    const idsGerencia = gerencias.map(item => Number(item.id)).filter(Number.isSafeInteger);
    let gerenciasPermitidas = new Set();
    if (idsGerencia.length) {
      const rAreas = await env.db.prepare(`
        SELECT usuario_id, area
        FROM usuario_areas
        WHERE ativo = 1
          AND usuario_id IN (${idsGerencia.map(() => "?").join(",")})
      `).bind(...idsGerencia).all();
      for (const row of rAreas.results || []) {
        if (areasFuncionario.has(row.area)) gerenciasPermitidas.add(Number(row.usuario_id));
      }
    }
    return contatos.filter(item => item.perfil !== "GERENCIA" || gerenciasPermitidas.has(Number(item.id)));
  }

  return [];
}

