async function listarAvisosCoord(env) {

  const resultado =
    await env.db.prepare(`

      SELECT

        a.*,

        u.nome
          AS remetente,

        u.setor,

        t.codigo,
        t.paciente,
        t.municipio,

        ur.nome
          AS respondedor

      FROM avisos_coordenador a

      INNER JOIN usuarios u
        ON u.id =
           a.remetente_id

      LEFT JOIN trabalhos t
        ON t.id =
           a.trabalho_id

      LEFT JOIN usuarios ur
        ON ur.id =
           a.respondido_por

      ORDER BY
        a.encerrado ASC,
        a.urgente DESC,
        a.id DESC

      LIMIT 200

    `)
    .all();

  return (
    resultado.results
    ||
    []
  );
}

