async function listarMeusAvisos(
  env,
  usuarioId
) {

  const resultado =
    await env.db.prepare(`

      SELECT

        a.*,

        t.codigo,
        t.paciente,
        t.municipio,

        u.nome
          AS respondedor

      FROM avisos_coordenador a

      LEFT JOIN trabalhos t
        ON t.id =
           a.trabalho_id

      LEFT JOIN usuarios u
        ON u.id =
           a.respondido_por

      WHERE
        a.remetente_id = ?

      ORDER BY
        a.id DESC

      LIMIT 100

    `)
    .bind(
      usuarioId
    )
    .all();

  return (
    resultado.results
    ||
    []
  );
}

