/* =========================================================
   PRODUÇÃO CONVENCIONAL · V2.4
========================================================= */

function nomeStatusConvencional(status) {
  const mapa = {
    ARTICULACAO: "Articulação",
    MONTAGEM: "Montagem",
    ENCERRAMENTO: "Encerramento",
    ESCULTURA: "Escultura",
    INCLUSAO: "Inclusão",
    ACRILIZACAO: "Acrilização",
    DESINCLUSAO: "Desinclusão",
    ACABAMENTO: "Acabamento",
    QUALIDADE: "Qualidade",
    LIBERADO_ENTREGA: "Liberado para entrega",
    CONCLUIDO: "Concluído"
  };
  return mapa[status] || status || "—";
}

function nomeStatusEtapaConvencional(status) {
  const mapa = {
    BLOQUEADO: "Aguardando setor anterior",
    AGUARDANDO: "Aguardando",
    AGUARDANDO_PAR: "Aguardando o par",
    EM_ANDAMENTO: "Em andamento",
    CONCLUIDO: "Concluído"
  };
  return mapa[status] || status || "—";
}

function classeStatusEtapaConvencional(status) {
  if (status === "CONCLUIDO") return "ok";
  if (status === "EM_ANDAMENTO") return "andamento";
  if (status === "AGUARDANDO") return "alerta";
  return "neutro";
}

function nomeTipoConvencional(tipo) {
  if (tipo === "PT") return "PT";
  if (tipo === "PPR") return "PPR";
  return "Tipo não definido";
}

const LIMITE_LOTE_CONVENCIONAL = 40;

function lerIdsLoteConvencional(dados, campo) {
  const ids = [...new Set(
    dados.getAll(campo)
      .map(valor => Number(valor))
      .filter(valor => Number.isInteger(valor) && valor > 0)
  )];
  return ids.slice(0, LIMITE_LOTE_CONVENCIONAL + 1);
}

function textoPecasLoteConvencional(item) {
  return [
    Number(item.tem_superior) ? `SUP · ${nomeTipoConvencional(item.tipo_superior)}` : "",
    Number(item.tem_inferior) ? `INF · ${nomeTipoConvencional(item.tipo_inferior)}` : ""
  ].filter(Boolean).join(" / ");
}

function proximoSetorConvencional(setor) {
  const ordem = [
    "ARTICULACAO",
    "MONTAGEM",
    "ENCERRAMENTO",
    "ESCULTURA",
    "INCLUSAO",
    "ACRILIZACAO",
    "DESINCLUSAO",
    "ACABAMENTO",
    "QUALIDADE",
    "LIBERADO_ENTREGA",
    "CONCLUIDO"
  ];
  const i = ordem.indexOf(setor);
  return i >= 0 && i < ordem.length - 1 ? ordem[i + 1] : null;
}


function setorAnteriorConvencional(setor) {
  const mapa = {
    MONTAGEM: "ARTICULACAO",
    ENCERRAMENTO: "MONTAGEM",
    ESCULTURA: "ENCERRAMENTO",
    INCLUSAO: "ESCULTURA",
    ACRILIZACAO: "INCLUSAO",
    DESINCLUSAO: "ACRILIZACAO",
    ACABAMENTO: "DESINCLUSAO",
    QUALIDADE: "ACABAMENTO"
  };
  return mapa[setor] || null;
}

function podeEditarGestaoConvencional(usuario) {
  return podeGerenciarAreaV31(usuario, "CONVENCIONAL");
}

async function listarFuncionariosConvencionais(env) {
  const resultado = await env.db.prepare(`
    SELECT
      u.id,
      u.nome,
      u.perfil,
      u.setor_convencional,
      u.area_producao,
      (
        SELECT GROUP_CONCAT(us.setor, '|')
        FROM usuario_setores us
        WHERE us.usuario_id = u.id
          AND us.area = 'CONVENCIONAL'
          AND us.ativo = 1
      ) AS setores_v31
    FROM usuarios u
    WHERE u.ativo = 1
      AND u.excluido = 0
      AND (
        u.perfil IN ('ADMINISTRADOR','COORDENADOR')
        OR EXISTS (
          SELECT 1
          FROM usuario_areas ua
          WHERE ua.usuario_id = u.id
            AND ua.area = 'CONVENCIONAL'
            AND ua.ativo = 1
        )
      )
    ORDER BY u.nome ASC
  `).all();
  return (resultado.results || []).map(item => ({
    ...item,
    setor_convencional: item.setor_convencional || listaPipeV31(item.setores_v31)[0] || null
  }));
}

async function nomeUsuarioPorIdConvencional(env, id) {
  if (!id) return "Sem responsável";
  const usuario = await env.db.prepare(`
    SELECT nome FROM usuarios WHERE id = ? LIMIT 1
  `).bind(id).first();
  return usuario?.nome || `Usuário #${id}`;
}

async function garantirEtapasBasicasConvencionais(env) {
  await env.db.prepare(`
    INSERT OR IGNORE INTO etapas_convencionais (peca_id, setor, status)
    SELECT id, 'ARTICULACAO',
      CASE WHEN setor_atual = 'ARTICULACAO' THEN 'AGUARDANDO' ELSE 'CONCLUIDO' END
    FROM pecas_convencionais
  `).run();

  const ordem = [
    "MONTAGEM",
    "ENCERRAMENTO",
    "ESCULTURA",
    "INCLUSAO",
    "ACRILIZACAO",
    "DESINCLUSAO",
    "ACABAMENTO",
    "QUALIDADE"
  ];
  const ranking = {
    ARTICULACAO: 1, MONTAGEM: 2, ENCERRAMENTO: 3, ESCULTURA: 4,
    INCLUSAO: 5, ACRILIZACAO: 6, DESINCLUSAO: 7, ACABAMENTO: 8,
    QUALIDADE: 9, LIBERADO_ENTREGA: 10, CONCLUIDO: 11
  };

  for (const setor of ordem) {
    const alvo = ranking[setor];
    await env.db.prepare(`
      INSERT OR IGNORE INTO etapas_convencionais (peca_id, setor, status)
      SELECT
        id,
        ?,
        CASE
          WHEN CASE setor_atual
            WHEN 'ARTICULACAO' THEN 1 WHEN 'MONTAGEM' THEN 2 WHEN 'ENCERRAMENTO' THEN 3
            WHEN 'ESCULTURA' THEN 4 WHEN 'INCLUSAO' THEN 5 WHEN 'ACRILIZACAO' THEN 6
            WHEN 'DESINCLUSAO' THEN 7 WHEN 'ACABAMENTO' THEN 8 WHEN 'QUALIDADE' THEN 9
            WHEN 'LIBERADO_ENTREGA' THEN 10 WHEN 'CONCLUIDO' THEN 11 ELSE 1 END > ?
            THEN 'CONCLUIDO'
          WHEN setor_atual = ? THEN 'AGUARDANDO'
          ELSE 'BLOQUEADO'
        END
      FROM pecas_convencionais
    `).bind(setor, alvo, setor).run();
  }

  // Migração segura da V2.2.x: peças que já estavam concluídas
  // passam pela Qualidade quando a nova etapa estiver aguardando.
  await env.db.prepare(`
    UPDATE pecas_convencionais
    SET setor_atual = 'QUALIDADE', status = 'AGUARDANDO'
    WHERE setor_atual = 'CONCLUIDO'
      AND EXISTS (
        SELECT 1
        FROM etapas_convencionais e
        WHERE e.peca_id = pecas_convencionais.id
          AND e.setor = 'QUALIDADE'
          AND e.status = 'AGUARDANDO'
      )
  `).run();
}

async function obterCicloConvencional(env, id = 0) {
  if (id) {
    return await env.db.prepare(`SELECT * FROM ciclos_convencionais WHERE id = ? LIMIT 1`).bind(id).first();
  }
  return await env.db.prepare(`
    SELECT * FROM ciclos_convencionais
    WHERE ativo = 1
    ORDER BY id DESC
    LIMIT 1
  `).first();
}

async function listarCiclosConvencionais(env) {
  const resultado = await env.db.prepare(`
    SELECT
      c.*,
      (SELECT COUNT(*) FROM faixas_convencionais f WHERE f.ciclo_id = c.id) AS total_faixas,
      (SELECT COUNT(*) FROM trabalhos_convencionais t WHERE t.ciclo_id = c.id AND t.excluido = 0) AS total_trabalhos
    FROM ciclos_convencionais c
    ORDER BY c.ativo DESC, date(c.data_inicio) DESC, c.id DESC
  `).all();
  return resultado.results || [];
}

async function listarFaixasConvencionais(env, cicloId) {
  if (!cicloId) return [];
  const resultado = await env.db.prepare(`
    SELECT f.*, r.numero AS remessa_numero, r.data_prevista_entrega AS remessa_entrega
    FROM faixas_convencionais f
    LEFT JOIN remessas r ON r.id = f.remessa_id
    WHERE f.ciclo_id = ?
    ORDER BY f.numero_inicio ASC, f.numero_fim ASC
  `).bind(cicloId).all();
  return resultado.results || [];
}

async function resumoConvencional(env, cicloId) {
  if (!cicloId) return { trabalhos: 0, pecas: 0, superior: 0, inferior: 0, pt: 0, ppr: 0 };
  const resultado = await env.db.prepare(`
    SELECT
      COUNT(DISTINCT t.id) AS trabalhos,
      COUNT(p.id) AS pecas,
      SUM(CASE WHEN p.arcada = 'SUPERIOR' THEN 1 ELSE 0 END) AS superior,
      SUM(CASE WHEN p.arcada = 'INFERIOR' THEN 1 ELSE 0 END) AS inferior,
      SUM(CASE WHEN p.tipo_protese = 'PT' THEN 1 ELSE 0 END) AS pt,
      SUM(CASE WHEN p.tipo_protese = 'PPR' THEN 1 ELSE 0 END) AS ppr
    FROM trabalhos_convencionais t
    LEFT JOIN pecas_convencionais p ON p.trabalho_id = t.id
    WHERE t.ciclo_id = ? AND t.excluido = 0
  `).bind(cicloId).first();
  return {
    trabalhos: Number(resultado?.trabalhos || 0),
    pecas: Number(resultado?.pecas || 0),
    superior: Number(resultado?.superior || 0),
    inferior: Number(resultado?.inferior || 0),
    pt: Number(resultado?.pt || 0),
    ppr: Number(resultado?.ppr || 0)
  };
}

async function listarTrabalhosConvencionais(env, cicloId, busca = "") {
  if (!cicloId) return [];
  const q = String(busca || "").trim().toLowerCase();
  const termo = `%${q}%`;
  const whereBusca = q ? `
    AND (
      lower(t.paciente) LIKE ? OR lower(t.municipio) LIKE ? OR CAST(t.numero_articulador AS TEXT) LIKE ?
    )
  ` : "";

  let stmt = env.db.prepare(`
    SELECT
      t.*,
      f.numero_inicio,
      f.numero_fim,
      (SELECT COUNT(*) FROM pecas_convencionais p WHERE p.trabalho_id = t.id) AS total_pecas,
      (SELECT tipo_protese FROM pecas_convencionais p WHERE p.trabalho_id = t.id AND p.arcada = 'SUPERIOR' LIMIT 1) AS tipo_superior,
      (SELECT tipo_protese FROM pecas_convencionais p WHERE p.trabalho_id = t.id AND p.arcada = 'INFERIOR' LIMIT 1) AS tipo_inferior
    FROM trabalhos_convencionais t
    LEFT JOIN faixas_convencionais f ON f.id = t.faixa_id
    WHERE t.ciclo_id = ? AND t.excluido = 0 ${whereBusca}
    ORDER BY t.numero_articulador ASC, t.id ASC
    LIMIT 1000
  `);

  stmt = q ? stmt.bind(cicloId, termo, termo, termo) : stmt.bind(cicloId);
  const resultado = await stmt.all();
  return resultado.results || [];
}

async function obterTrabalhoConvencional(env, id) {
  return await env.db.prepare(`
    SELECT
      t.*,
      c.nome AS ciclo_nome,
      c.codigo AS ciclo_codigo,
      c.data_inicio AS ciclo_inicio,
      c.data_fim AS ciclo_fim,
      f.numero_inicio,
      f.numero_fim,
      u.nome AS criador
    FROM trabalhos_convencionais t
    INNER JOIN ciclos_convencionais c ON c.id = t.ciclo_id
    LEFT JOIN faixas_convencionais f ON f.id = t.faixa_id
    LEFT JOIN usuarios u ON u.id = t.criado_por
    WHERE t.id = ? AND t.excluido = 0
    LIMIT 1
  `).bind(id).first();
}

async function listarPecasConvencionais(env, trabalhoId) {
  const resultado = await env.db.prepare(`
    SELECT
      p.*,
      (SELECT m.numero_mufla FROM muflas_convencionais m WHERE m.peca_id = p.id ORDER BY m.ativo DESC, m.id DESC LIMIT 1) AS numero_mufla,
      (SELECT m.ativo FROM muflas_convencionais m WHERE m.peca_id = p.id ORDER BY m.ativo DESC, m.id DESC LIMIT 1) AS mufla_ativa,
      (SELECT m.status FROM muflas_convencionais m WHERE m.peca_id = p.id ORDER BY m.ativo DESC, m.id DESC LIMIT 1) AS mufla_status,
      (SELECT iq.resultado FROM inspecoes_qualidade_convencional iq WHERE iq.peca_id = p.id ORDER BY iq.id DESC LIMIT 1) AS qualidade_resultado,
      (SELECT iq.motivo FROM inspecoes_qualidade_convencional iq WHERE iq.peca_id = p.id ORDER BY iq.id DESC LIMIT 1) AS qualidade_motivo,
      (SELECT iq.setor_retorno FROM inspecoes_qualidade_convencional iq WHERE iq.peca_id = p.id ORDER BY iq.id DESC LIMIT 1) AS qualidade_setor_retorno,
      (SELECT iq.criado_em FROM inspecoes_qualidade_convencional iq WHERE iq.peca_id = p.id ORDER BY iq.id DESC LIMIT 1) AS qualidade_em,
      (SELECT u.nome FROM inspecoes_qualidade_convencional iq LEFT JOIN usuarios u ON u.id = iq.responsavel_id WHERE iq.peca_id = p.id ORDER BY iq.id DESC LIMIT 1) AS qualidade_responsavel
    FROM pecas_convencionais p
    WHERE p.trabalho_id = ?
    ORDER BY CASE p.arcada WHEN 'SUPERIOR' THEN 1 ELSE 2 END
  `).bind(trabalhoId).all();
  return resultado.results || [];
}

async function listarEtapasTrabalhoConvencional(env, trabalhoId) {
  const resultado = await env.db.prepare(`
    SELECT
      e.*,
      p.arcada,
      p.tipo_protese,
      u.nome AS responsavel_nome
    FROM etapas_convencionais e
    INNER JOIN pecas_convencionais p ON p.id = e.peca_id
    LEFT JOIN usuarios u ON u.id = e.responsavel_id
    WHERE p.trabalho_id = ?
    ORDER BY
      CASE p.arcada WHEN 'SUPERIOR' THEN 1 ELSE 2 END,
      CASE e.setor
        WHEN 'ARTICULACAO' THEN 1
        WHEN 'MONTAGEM' THEN 2
        WHEN 'ENCERRAMENTO' THEN 3
        WHEN 'ESCULTURA' THEN 4
        WHEN 'INCLUSAO' THEN 5
        WHEN 'ACRILIZACAO' THEN 6
        WHEN 'DESINCLUSAO' THEN 7
        WHEN 'ACABAMENTO' THEN 8
        WHEN 'QUALIDADE' THEN 9
        ELSE 99
      END
  `).bind(trabalhoId).all();
  return resultado.results || [];
}

async function recalcularStatusTrabalhoConvencional(env, trabalhoId) {
  const resultado = await env.db.prepare(`
    SELECT setor_atual FROM pecas_convencionais WHERE trabalho_id = ?
  `).bind(trabalhoId).all();
  const pecas = resultado.results || [];
  if (!pecas.length) return;
  const ordem = {
    ARTICULACAO: 1,
    MONTAGEM: 2,
    ENCERRAMENTO: 3,
    ESCULTURA: 4,
    INCLUSAO: 5,
    ACRILIZACAO: 6,
    DESINCLUSAO: 7,
    ACABAMENTO: 8,
    QUALIDADE: 9,
    LIBERADO_ENTREGA: 10,
    CONCLUIDO: 11
  };
  const atual = pecas.reduce((a, p) => {
    if (!a) return p.setor_atual;
    return (ordem[p.setor_atual] || 99) < (ordem[a] || 99) ? p.setor_atual : a;
  }, null) || "ARTICULACAO";
  await env.db.prepare(`UPDATE trabalhos_convencionais SET status = ? WHERE id = ?`).bind(atual, trabalhoId).run();
}

