async function listarPecasCargaMuflaConvencional(env, cargaId, setor = '') {
  const filtroSetor = setor ? `AND e.setor = ?` : '';
  let stmt = env.db.prepare(`
    SELECT
      m.id AS mufla_item_id,
      m.carga_id,
      m.numero_mufla,
      m.status AS mufla_item_status,
      m.ativo AS mufla_item_ativo,
      p.id AS peca_id,
      p.arcada,
      p.tipo_protese,
      p.trabalho_id,
      t.numero_articulador,
      t.paciente,
      t.municipio,
      t.uf,
      e.id AS etapa_id,
      e.setor,
      e.status AS etapa_status,
      e.responsavel_id,
      u.nome AS responsavel_nome
    FROM muflas_convencionais m
    INNER JOIN pecas_convencionais p ON p.id = m.peca_id
    INNER JOIN trabalhos_convencionais t ON t.id = p.trabalho_id
    LEFT JOIN etapas_convencionais e ON e.peca_id = p.id
    LEFT JOIN usuarios u ON u.id = e.responsavel_id
    WHERE m.carga_id = ?
      AND m.ativo = 1
      AND t.excluido = 0
      ${filtroSetor}
    ORDER BY t.numero_articulador ASC, CASE p.arcada WHEN 'SUPERIOR' THEN 1 ELSE 2 END
  `);
  stmt = setor ? stmt.bind(cargaId, setor) : stmt.bind(cargaId);
  const resultado = await stmt.all();
  return resultado.results || [];
}

async function listarRastreioMuflasConvencional(env, busca = "") {
  const q = String(busca || "").trim();
  const numero = Number(q || 0);
  let stmt;
  if (q && Number.isInteger(numero) && numero > 0) {
    stmt = env.db.prepare(`
      SELECT
        carga.id AS carga_id,
        carga.numero_mufla,
        carga.status AS carga_status,
        carga.ativo AS carga_ativa,
        carga.incluido_em,
        carga.acrilizado_em,
        carga.desincluido_em,
        m.id AS mufla_item_id,
        m.status AS item_status,
        m.ativo AS item_ativo,
        p.id AS peca_id,
        p.arcada,
        p.tipo_protese,
        t.id AS trabalho_id,
        t.numero_articulador,
        t.paciente,
        t.municipio,
        t.uf,
        c.nome AS ciclo_nome,
        pp.arcada AS par_arcada,
        pp.tipo_protese AS par_tipo_protese,
        mp.numero_mufla AS par_mufla,
        edp.status AS par_desinclusao_status
      FROM cargas_muflas_convencionais carga
      LEFT JOIN muflas_convencionais m ON m.carga_id = carga.id
      LEFT JOIN pecas_convencionais p ON p.id = m.peca_id
      LEFT JOIN trabalhos_convencionais t ON t.id = p.trabalho_id
      LEFT JOIN ciclos_convencionais c ON c.id = t.ciclo_id
      LEFT JOIN pecas_convencionais pp ON pp.trabalho_id = t.id AND pp.id != p.id
      LEFT JOIN muflas_convencionais mp ON mp.peca_id = pp.id AND mp.ativo = 1
      LEFT JOIN etapas_convencionais edp ON edp.peca_id = pp.id AND edp.setor = 'DESINCLUSAO'
      WHERE carga.numero_mufla = ?
        AND (t.id IS NULL OR t.excluido = 0)
      ORDER BY carga.ativo DESC, carga.id DESC, t.numero_articulador ASC
      LIMIT 500
    `).bind(numero);
  } else {
    stmt = env.db.prepare(`
      SELECT
        carga.id AS carga_id,
        carga.numero_mufla,
        carga.status AS carga_status,
        carga.ativo AS carga_ativa,
        carga.incluido_em,
        carga.acrilizado_em,
        carga.desincluido_em,
        m.id AS mufla_item_id,
        m.status AS item_status,
        m.ativo AS item_ativo,
        p.id AS peca_id,
        p.arcada,
        p.tipo_protese,
        t.id AS trabalho_id,
        t.numero_articulador,
        t.paciente,
        t.municipio,
        t.uf,
        c.nome AS ciclo_nome,
        pp.arcada AS par_arcada,
        pp.tipo_protese AS par_tipo_protese,
        mp.numero_mufla AS par_mufla,
        edp.status AS par_desinclusao_status
      FROM cargas_muflas_convencionais carga
      LEFT JOIN muflas_convencionais m ON m.carga_id = carga.id
      LEFT JOIN pecas_convencionais p ON p.id = m.peca_id
      LEFT JOIN trabalhos_convencionais t ON t.id = p.trabalho_id
      LEFT JOIN ciclos_convencionais c ON c.id = t.ciclo_id
      LEFT JOIN pecas_convencionais pp ON pp.trabalho_id = t.id AND pp.id != p.id
      LEFT JOIN muflas_convencionais mp ON mp.peca_id = pp.id AND mp.ativo = 1
      LEFT JOIN etapas_convencionais edp ON edp.peca_id = pp.id AND edp.setor = 'DESINCLUSAO'
      WHERE carga.ativo = 1
        AND (t.id IS NULL OR t.excluido = 0)
      ORDER BY carga.numero_mufla ASC, carga.id DESC, t.numero_articulador ASC
      LIMIT 1000
    `);
  }
  const resultado = await stmt.all();
  const rows = resultado.results || [];
  const mapa = new Map();
  for (const row of rows) {
    const id = Number(row.carga_id);
    if (!mapa.has(id)) {
      mapa.set(id, {
        carga_id: id,
        numero_mufla: Number(row.numero_mufla),
        status: row.carga_status,
        ativo: Number(row.carga_ativa),
        incluido_em: row.incluido_em,
        acrilizado_em: row.acrilizado_em,
        desincluido_em: row.desincluido_em,
        pecas: []
      });
    }
    if (row.peca_id) mapa.get(id).pecas.push(row);
  }
  return [...mapa.values()];
}

async function obterResumoArticulacaoTrabalho(env, trabalhoId) {
  const resultado = await env.db.prepare(`
    SELECT
      COUNT(*) AS total_pecas,
      SUM(CASE WHEN e.status = 'CONCLUIDO' THEN 1 ELSE 0 END) AS concluidas,
      SUM(CASE WHEN e.status = 'EM_ANDAMENTO' THEN 1 ELSE 0 END) AS em_andamento,
      SUM(CASE WHEN e.status = 'AGUARDANDO' THEN 1 ELSE 0 END) AS aguardando,
      MAX(CASE WHEN e.status = 'EM_ANDAMENTO' THEN e.responsavel_id END) AS responsavel_id,
      MAX(CASE WHEN e.status = 'EM_ANDAMENTO' THEN u.nome END) AS responsavel_nome
    FROM etapas_convencionais e
    INNER JOIN pecas_convencionais p ON p.id = e.peca_id
    LEFT JOIN usuarios u ON u.id = e.responsavel_id
    WHERE p.trabalho_id = ? AND e.setor = 'ARTICULACAO'
  `).bind(trabalhoId).first();

  const total = Number(resultado?.total_pecas || 0);
  const concluidas = Number(resultado?.concluidas || 0);
  const emAndamento = Number(resultado?.em_andamento || 0);
  const aguardando = Number(resultado?.aguardando || 0);
  return {
    total,
    concluidas,
    emAndamento,
    aguardando,
    responsavel_id: resultado?.responsavel_id || null,
    responsavel_nome: resultado?.responsavel_nome || "",
    status: total > 0 && concluidas === total
      ? 'CONCLUIDO'
      : emAndamento > 0
        ? 'EM_ANDAMENTO'
        : 'AGUARDANDO'
  };
}

