async function fundirContaGerenciaNoAdministradorV355(env, administradorId, gerenciaId, executadoPorId) {
  const administrador = await obterUsuarioV31(env, Number(administradorId));
  const gerencia = await obterUsuarioV31(env, Number(gerenciaId));

  if (!administrador || administrador.perfil !== "ADMINISTRADOR" || !administrador.ativo || administrador.excluido) {
    throw new Error("A conta principal precisa ser um Administrador ativo.");
  }
  if (!gerencia || gerencia.perfil !== "GERENCIA" || gerencia.excluido) {
    throw new Error("A conta incorporada precisa ser uma Gerência válida.");
  }
  if (Number(administrador.id) === Number(gerencia.id)) {
    throw new Error("Escolha duas contas diferentes.");
  }

  // Somente vínculos de PRODUÇÃO/EXECUÇÃO são transferidos. Autoria de auditoria,
  // mensagens, criação, entrega e designação permanece na conta histórica original.
  // Isso une os relatórios sem reescrever quem praticou cada ação administrativa.
  const p = Number(administrador.id);
  const g = Number(gerencia.id);
  const statements = [
    env.db.prepare(`UPDATE etapas SET responsavel_id=? WHERE responsavel_id=?`).bind(p,g),
    env.db.prepare(`UPDATE componentes_impressao SET responsavel_id=? WHERE responsavel_id=?`).bind(p,g),
    env.db.prepare(`UPDATE retrabalhos SET executado_por=? WHERE executado_por=?`).bind(p,g),
    env.db.prepare(`UPDATE etapas_convencionais SET responsavel_id=? WHERE responsavel_id=?`).bind(p,g),
    env.db.prepare(`UPDATE retrabalhos_convencionais SET responsavel_id=? WHERE responsavel_id=?`).bind(p,g),
    env.db.prepare(`UPDATE inspecoes_qualidade_convencional SET responsavel_id=? WHERE responsavel_id=?`).bind(p,g),
    env.db.prepare(`UPDATE cargas_muflas_convencionais SET incluido_por=? WHERE incluido_por=?`).bind(p,g),
    env.db.prepare(`UPDATE cargas_muflas_convencionais SET acrilizado_por=? WHERE acrilizado_por=?`).bind(p,g),
    env.db.prepare(`UPDATE cargas_muflas_convencionais SET desincluido_por=? WHERE desincluido_por=?`).bind(p,g),
    env.db.prepare(`UPDATE muflas_convencionais SET incluido_por=? WHERE incluido_por=?`).bind(p,g),
    env.db.prepare(`UPDATE muflas_convencionais SET acrilizado_por=? WHERE acrilizado_por=?`).bind(p,g),
    env.db.prepare(`UPDATE muflas_convencionais SET desincluido_por=? WHERE desincluido_por=?`).bind(p,g),
    env.db.prepare(`UPDATE usuarios SET ativo=0, excluido=1 WHERE id=? AND perfil='GERENCIA'`).bind(g),
    env.db.prepare(`UPDATE usuario_areas SET ativo=0, atualizado_em=CURRENT_TIMESTAMP WHERE usuario_id=?`).bind(g),
    env.db.prepare(`UPDATE usuario_setores SET ativo=0, atualizado_em=CURRENT_TIMESTAMP WHERE usuario_id=?`).bind(g),
    env.db.prepare(`DELETE FROM sessoes WHERE usuario_id=?`).bind(g)
  ];

  const resultados = await env.db.batch(statements);
  const totalTransferido = resultados.slice(0,12).reduce((soma, r) => soma + Number(r?.meta?.changes || 0), 0);

  await registrarAuditoriaSistemaV31(
    env,
    Number(executadoPorId),
    "GERAL",
    "FUNDIR_CONTAS_MESMA_PESSOA",
    "USUARIO",
    p,
    "usuario_incorporado",
    `${gerencia.nome} (#${g}, ${gerencia.usuario})`,
    `${administrador.nome} (#${p}, ${administrador.usuario})`,
    `Conta de Gerência incorporada ao Administrador. ${totalTransferido} vínculo(s) de produção/execução transferido(s). A conta antiga foi desativada e ocultada, mas mantida no banco para preservar auditoria, mensagens e autoria histórica.`
  );

  return { administrador, gerencia, totalTransferido };
}

