async function listarEquipeAreaV31(env, area) {
  const resultado = await env.db.prepare(`
    SELECT
      u.id, u.nome, u.usuario, u.perfil, u.ativo, u.setor, u.setor_convencional, u.area_producao,
      COALESCE((SELECT GROUP_CONCAT(ua.area,'|') FROM usuario_areas ua WHERE ua.usuario_id=u.id AND ua.ativo=1),'') AS areas_v31,
      COALESCE((SELECT GROUP_CONCAT(us.area || ':' || us.setor,'|') FROM usuario_setores us WHERE us.usuario_id=u.id AND us.ativo=1),'') AS setores_v31
    FROM usuarios u
    WHERE u.excluido=0 AND u.ativo=1
      AND u.perfil IN ('FUNCIONARIO','GERENCIA')
      AND EXISTS (SELECT 1 FROM usuario_areas ua WHERE ua.usuario_id=u.id AND ua.area=? AND ua.ativo=1)
    ORDER BY CASE u.perfil WHEN 'GERENCIA' THEN 1 ELSE 2 END, u.nome COLLATE NOCASE
  `).bind(area).all();
  return resultado.results || [];
}

function paginaEquipeAreaV31(usuario, area, equipe) {
  const linhas = equipe.map(p => `<tr><td><strong>${escapeHtml(p.nome)}</strong><div class="mini">${escapeHtml(perfilNome(p.perfil))}</div></td><td>${p.perfil === "GERENCIA" ? "Todos os setores da área" : escapeHtml(resumoSetoresFuncionarioV31(p, area))}</td><td><a class="botao botao-sec" href="/producao-equipe?area=${encodeURIComponent(area)}">Produção / metas</a></td></tr>`).join("");
  return layout(`
    <div class="cabecalho-pagina"><div><h2>Equipe ${escapeHtml(nomeAreaProducao(area))}</h2><p class="nota">A Gerência acompanha sua própria área. Cadastro de usuários permanece com Administrador/Coordenador.</p></div><a class="botao botao-sec" href="/${area === "DIGITAL" ? "digital" : "convencional"}">← Área</a></div>
    <div class="tabela-wrap"><table><thead><tr><th>Pessoa</th><th>Setores</th><th>Produção</th></tr></thead><tbody>${linhas || `<tr><td colspan="3">Nenhuma pessoa nesta área.</td></tr>`}</tbody></table></div>
  `, `Equipe ${nomeAreaProducao(area)}`, usuario);
}

async function dadosInicioV31(env, usuario) {
  const dados = { digital: null, convencional: null, avisoImpressaoV315: "" };
  if (usuarioTemAreaDigital(usuario)) { try { dados.avisoImpressaoV315 = avisoPrioridadeHomeV315(await pendentesImpressaoV315(env)); } catch (_) {} }
  if (usuarioTemAreaDigital(usuario)) {
    const visibilidadeV345 = sqlVisibilidadeTrabalhoDigitalLiteralV345(usuario, "t");
    const visibilidadeRemessaV345 = sqlVisibilidadeTrabalhoDigitalLiteralV345(usuario, "tx");
    dados.digital = await env.db.prepare(`
      SELECT
        COUNT(*) AS total,
        SUM(CASE WHEN t.entregue=1 THEN 1 ELSE 0 END) AS entregues,
        SUM(CASE WHEN t.entregue=0 AND NOT EXISTS (
          SELECT 1 FROM etapas e WHERE e.trabalho_id=t.id AND e.status!='CONCLUIDO'
        ) THEN 1 ELSE 0 END) AS prontos,
        (SELECT COUNT(*) FROM remessas r WHERE r.data_entrega_real IS NULL AND EXISTS (
          SELECT 1 FROM trabalhos tx WHERE tx.remessa_id=r.id AND tx.excluido=0
          ${visibilidadeRemessaV345}
        )) AS remessas_abertas
      FROM trabalhos t WHERE t.excluido=0
      ${visibilidadeV345}
    `).first();
  }
  if (usuarioTemAreaConvencional(usuario)) {
    const ciclo = await obterCicloConvencional(env, 0);
    if (ciclo) {
      const cidades = await listarCidadesCicloV31(env, ciclo.id);
      dados.convencional = {
        ciclo,
        cidades: cidades.length,
        prontas: cidades.filter(c => c.status_v31 === "PRONTA").length,
        entregues: cidades.filter(c => c.status_v31 === "ENTREGUE").length,
        qualidade: cidades.filter(c => c.status_v31 === "QUALIDADE").length
      };
    } else {
      dados.convencional = { ciclo: null, cidades: 0, prontas: 0, entregues: 0, qualidade: 0 };
    }
  }
  if (usuarioTemAreaDigital(usuario)) dados.meusDesignados = await meusDesignadosV338(env, usuario, 1, 12);
  return dados;
}


/* =========================================================
   V3.4.18 · ACESSO CADASTRO
   Perfil exclusivo para remessas/municípios e pacientes.
   Não concede setores, metas, designações ou controles de produção.
========================================================= */
async function dadosCadastroV3418(env, cicloId = 0) {
  const ciclos = await listarCiclosDigitaisV311(env);
  let ciclo = await obterCicloDigitalV311(env, Number(cicloId || 0));
  if (!ciclo && ciclos.length) ciclo = ciclos.find(c => Number(c.ativo || 0)) || ciclos[0];
  if (!ciclo) return { ciclo: null, ciclos, remessas: [], pacientes: [], semRemessa: [] };

  const [remessasR, pacientesR, semRemessa] = await Promise.all([
    env.db.prepare(`
      SELECT
        r.id, r.municipio, r.numero, r.data_recebimento, r.data_prevista_entrega,
        r.data_finalizacao, r.data_entrega_real, r.observacao, r.ciclo_digital_id,
        COUNT(t.id) AS total_pacientes
      FROM remessas r
      LEFT JOIN trabalhos t ON t.remessa_id=r.id AND t.excluido=0
      WHERE r.ciclo_digital_id=?
      GROUP BY r.id
      ORDER BY CASE WHEN r.data_entrega_real IS NULL THEN 0 ELSE 1 END,
               date(r.data_prevista_entrega), r.municipio COLLATE NOCASE, r.id DESC
    `).bind(ciclo.id).all(),
    env.db.prepare(`
      SELECT t.id,t.codigo,t.paciente,t.municipio,t.superior_tipo,t.inferior_tipo,t.remessa_id,t.criado_em
      FROM trabalhos t
      INNER JOIN remessas r ON r.id=t.remessa_id
      WHERE r.ciclo_digital_id=? AND t.excluido=0
      ORDER BY r.id, t.paciente COLLATE NOCASE, t.id
    `).bind(ciclo.id).all(),
    listarPacientesDigitaisSemRemessa(env)
  ]);

  return {
    ciclo,
    ciclos,
    remessas: remessasR.results || [],
    pacientes: pacientesR.results || [],
    semRemessa: semRemessa || []
  };
}

function paginaCadastroV3418(usuario, dados, mensagem = "", tipo = "sucesso") {
  const porRemessa = new Map();
  for (const paciente of dados.pacientes || []) {
    const id = Number(paciente.remessa_id || 0);
    if (!porRemessa.has(id)) porRemessa.set(id, []);
    porRemessa.get(id).push(paciente);
  }

  const opcoesCiclos = (dados.ciclos || []).map(c => `
    <option value="${Number(c.id)}" ${Number(c.id)===Number(dados.ciclo?.id||0)?"selected":""}>
      ${escapeHtml(c.nome)} · ${escapeHtml(formatarDataCurta(c.data_inicio))} → ${escapeHtml(formatarDataCurta(c.data_fim))}${Number(c.ativo||0)?" · ATIVO":""}
    </option>`).join("");

  const cards = (dados.remessas || []).map(r => {
    const fechada = Boolean(r.data_finalizacao || r.data_entrega_real);
    const pacientes = porRemessa.get(Number(r.id)) || [];
    const municipioChave = String(r.municipio || "").trim().toLowerCase();
    const elegiveis = (dados.semRemessa || []).filter(p => String(p.municipio || "").trim().toLowerCase() === municipioChave);
    const status = r.data_entrega_real ? "Entregue" : (r.data_finalizacao ? "Finalizada" : "Aberta para cadastro");
    const classe = r.data_entrega_real ? "ok" : (r.data_finalizacao ? "andamento" : "neutro");
    const linhas = pacientes.map(p => `<tr><td><strong>${escapeHtml(p.paciente)}</strong><div class="mini">${escapeHtml(p.codigo)}</div></td><td>${escapeHtml(nomeTipo(p.superior_tipo))}</td><td>${escapeHtml(nomeTipo(p.inferior_tipo))}</td></tr>`).join("");
    const opcoesAntigos = elegiveis.map(p => `<option value="${Number(p.id)}">${escapeHtml(p.paciente)} · ${escapeHtml(p.codigo)}</option>`).join("");

    return `<section class="card" id="cadastro-remessa-${Number(r.id)}">
      <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap">
        <div>
          <span class="mini">REMESSA ${String(r.numero).padStart(2,"0")}</span>
          <h2 style="margin:3px 0">${escapeHtml(r.municipio)}</h2>
          <div class="mini">Recebida ${escapeHtml(formatarDataCurta(r.data_recebimento))} · previsão ${escapeHtml(formatarDataCurta(r.data_prevista_entrega))}</div>
        </div>
        <div style="text-align:right"><span class="badge ${classe}">${escapeHtml(status)}</span><div style="margin-top:8px"><strong style="font-size:22px">${pacientes.length}</strong> <span class="mini">paciente(s)</span></div></div>
      </div>
      ${r.observacao ? `<p class="nota">${escapeHtml(r.observacao)}</p>` : ""}

      ${!fechada ? `
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px">
          <a class="botao botao-sec" href="/remessas/${Number(r.id)}/importar-folhas">Importar foto / PDF</a>
        </div>
        ${blocoCadastroRapidoV323(r)}
        <details style="margin-top:12px"><summary style="cursor:pointer;font-weight:800">+ Cadastro individual</summary>
          <form method="POST" action="/remessas/${Number(r.id)}/novo-paciente" style="margin-top:10px"><div class="form-grid">
            <label class="full">Município<input value="${escapeHtml(r.municipio)}" readonly></label>
            <label>Paciente<input name="paciente" required minlength="2"></label>
            <label>Arcada superior<select name="superior_tipo"><option value="NONE">Sem trabalho</option><option value="PT">Prótese total</option><option value="PPR">PPR flex</option></select></label>
            <label>Arcada inferior<select name="inferior_tipo"><option value="NONE">Sem trabalho</option><option value="PT">Prótese total</option><option value="PPR">PPR flex</option></select></label>
            <div class="full"><button>Criar paciente na remessa</button></div>
          </div></form>
        </details>
        <details style="margin-top:12px"><summary style="cursor:pointer;font-weight:800">Editar remessa / município</summary>
          <form method="POST" action="/remessas/${Number(r.id)}/editar" style="margin-top:10px"><div class="form-grid">
            <label>Município<input name="municipio" required minlength="2" maxlength="120" value="${escapeHtml(r.municipio)}"></label>
            <label>Recebimento<input type="date" name="data_recebimento" required value="${escapeHtml(String(r.data_recebimento||"").slice(0,10))}"></label>
            <label>Previsão de entrega<input type="date" name="data_prevista_entrega" required value="${escapeHtml(String(r.data_prevista_entrega||"").slice(0,10))}"></label>
            <label class="full">Observação<input name="observacao" maxlength="500" value="${escapeHtml(r.observacao||"")}"></label>
            <label class="full">Motivo da alteração<input name="motivo" minlength="3" required placeholder="Ex.: correção de município ou data"></label>
            <div class="full"><button>Salvar cadastro da remessa</button></div>
          </div></form>
        </details>
        <details style="margin-top:12px"><summary style="cursor:pointer;font-weight:700">Vincular paciente antigo sem remessa</summary>
          ${elegiveis.length ? `<form method="POST" action="/remessas/${Number(r.id)}/vincular-paciente" style="margin-top:10px"><label>Paciente<select name="trabalho_id" required><option value="">Selecione</option>${opcoesAntigos}</select></label><button>Vincular paciente</button></form>` : `<p class="nota">Nenhum paciente antigo sem remessa neste município.</p>`}
        </details>
      ` : `<div class="info" style="margin-top:14px"><strong>🔒 Remessa encerrada.</strong> O perfil Cadastro pode consultar os pacientes, mas não inserir ou alterar esta remessa.</div>`}

      <details style="margin-top:14px" ${pacientes.length<=12?"open":""}><summary style="cursor:pointer;font-weight:900">Pacientes desta remessa (${pacientes.length})</summary>
        <div class="tabela-wrap" style="margin-top:10px"><table><thead><tr><th>Paciente</th><th>Superior</th><th>Inferior</th></tr></thead><tbody>${linhas || `<tr><td colspan="3">Nenhum paciente cadastrado nesta remessa.</td></tr>`}</tbody></table></div>
      </details>
    </section>`;
  }).join("");

  return layout(`
    <div class="cabecalho-pagina"><div><h2>Cadastro</h2><p class="nota">Remessas, municípios e pacientes. Este acesso não possui funções de produção, metas ou equipe.</p></div></div>
    ${mensagem ? `<div class="${tipo}">${escapeHtml(mensagem)}</div>` : ""}
    <div class="card" style="margin-bottom:16px"><div style="display:flex;justify-content:space-between;gap:14px;align-items:end;flex-wrap:wrap">
      <div><span class="mini">CICLO DIGITAL</span>${dados.ciclo ? `<h2 style="margin:3px 0">${escapeHtml(dados.ciclo.nome)}</h2><div class="mini">${escapeHtml(formatarDataCurta(dados.ciclo.data_inicio))} → ${escapeHtml(formatarDataCurta(dados.ciclo.data_fim))}</div>` : `<h2 style="margin:3px 0">Nenhum ciclo disponível</h2><p class="nota">Administrador/Coordenador deve criar o ciclo Digital antes dos cadastros.</p>`}</div>
      ${dados.ciclos.length ? `<form method="GET" action="/cadastro" style="display:flex;gap:8px;align-items:end"><label>Abrir ciclo<select name="ciclo">${opcoesCiclos}</select></label><button>Abrir</button></form>` : ""}
    </div></div>

    ${dados.ciclo ? `<details class="card" style="margin-bottom:16px" open><summary style="cursor:pointer;font-weight:900">+ Nova remessa / município</summary>
      <form method="POST" action="/remessas" style="margin-top:12px"><input type="hidden" name="origem" value="cadastro"><input type="hidden" name="ciclo_digital_id" value="${Number(dados.ciclo.id)}"><div class="form-grid">
        <label>Município<input name="municipio" required minlength="2" maxlength="120"></label>
        <label>Recebimento<input type="date" name="data_recebimento" required></label>
        <label>Previsão de entrega<input type="date" name="data_prevista_entrega" required></label>
        <label class="full">Observação <span class="mini">opcional</span><input name="observacao" maxlength="500"></label>
        <div class="full"><button>Criar remessa</button></div>
      </div></form>
    </details>` : ""}

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(390px,1fr));gap:14px">${cards || `<div class="card">Nenhuma remessa cadastrada neste ciclo.</div>`}</div>
  `, "Cadastro", usuario);
}

