function avatarEmojiV310(valor){
  const v = String(valor || "");
  if (!v) return "";
  if (v.startsWith("hex:")) {
    const m = /^hex:(#[0-9a-fA-F]{6})(?::(#[0-9a-fA-F]{6}))?(:([0-9A-Za-z\u00C0-\u024F ]{1,16}))?$/.exec(v);
    if (!m) return "";
    const cor = m[1], cor2 = m[2] || m[1], ini = (m[4] || "").trim();
    const letra = ini ? escapeHtml(ini.slice(0, 2).toUpperCase()) : "";
    return `<span style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;background:linear-gradient(135deg,${cor},${cor2});color:#fff;font-weight:900;font-size:.42em;letter-spacing:.5px">${letra}</span>`;
  }
  if (/^[\p{Extended_Pictographic}\u200d\uFE0F]+$/u.test(v)) return `<span style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;font-size:.62em;line-height:1">${escapeHtml(v)}</span>`;
  return "";
}

function rotuloAvatarV310(valor){
  const v = String(valor || "");
  if (!v) return "Sem avatar (usa as iniciais do nome)";
  if (v.startsWith("hex:")) return "Faixa de cor personalizada";
  return "Emoji";
}

function avatarUsuarioV310(usuario, avatarBanco){
  return avatarBanco || usuario?.avatar_v310 || "";
}

async function carregarNotasV310(env, usuarioId){
  const r = await env.db.prepare(`SELECT id, titulo, conteudo, criado_em, atualizado_em FROM usuario_notas_v310 WHERE usuario_id = ? AND excluida = 0 ORDER BY atualizado_em DESC, id DESC LIMIT 200`).bind(usuarioId).all();
  return r.results || [];
}

function quizNotasV310(env, usuarioId){
  return env.db.prepare(`SELECT COALESCE(SUM(LENGTH(conteudo)), 0) AS tamanho, COUNT(*) AS total FROM usuario_notas_v310 WHERE usuario_id = ? AND excluida = 0`).bind(usuarioId).first();
}

function paginaMinhasNotasV310(usuario, notas, mensagem = "", tipo = "sucesso"){
  const lista = notas.map(n => `
    <article class="nota-item-v310">
      <div class="nota-cabecalho-v310">
        <strong>${escapeHtml(n.titulo || "Sem título")}</strong>
        <span class="mini">${escapeHtml(formatarData(n.atualizado_em || n.criado_em))}</span>
      </div>
      <form method="POST" action="/minhas-notas/salvar">
        <input type="hidden" name="id" value="${Number(n.id)}">
        <input name="titulo" maxlength="80" value="${escapeHtml(n.titulo || "")}" placeholder="Título">
        <textarea name="conteudo" rows="5" maxlength="4000" placeholder="Escreva aqui...">${escapeHtml(n.conteudo || "")}</textarea>
        <div class="nota-acoes-v310">
          <button type="submit">Salvar</button>
          <span class="mini">${String(n.conteudo || "").length} caracteres</span>
        </div>
      </form>
      <form method="POST" action="/minhas-notas/excluir" onsubmit="return confirm('Excluir esta anotação?');">
        <input type="hidden" name="id" value="${Number(n.id)}">
        <button type="submit" class="botao-sec">Excluir</button>
      </form>
    </article>`).join("");
  return layout(`
    <div class="cabecalho-pagina"><div><h2>📝 Minhas anotações</h2><p class="nota">Bloco de notas particular. Só você vê o que escreve aqui. Nada é apagado automaticamente.</p></div><a class="botao botao-sec" href="/meu-perfil">← Meu perfil</a></div>
    ${mensagem ? `<div class="${tipo === "erro" ? "erro" : "sucesso"}" style="margin-bottom:14px">${escapeHtml(mensagem)}</div>` : ""}
    <section class="card" style="margin-bottom:16px">
      <h3>Nova anotação</h3>
      <form method="POST" action="/minhas-notas/salvar">
        <label>Título<input name="titulo" maxlength="80" placeholder="Ex.: Receita do dia, telefone do paciente, tarefa"></label>
        <label>Anotação<textarea name="conteudo" rows="4" maxlength="4000" placeholder="Escreva aqui..."></textarea></label>
        <button type="submit">Adicionar</button>
      </form>
    </section>
    <div class="notas-grade-v310">${lista || `<div class="card"><strong>Nenhuma anotação ainda.</strong><div class="mini">Use a caixa acima para criar a primeira.</div></div>`}</div>
  `, "Minhas anotações", usuario);
}

/* =========================================================
   V3.20.0 — MINHA EVOLUÇÃO: PAINEL PESSOAL DE DESEMPENHO
   Somente leitura. Usa produção já registrada. Não altera bônus.
   Não cria tabelas nem exige migração D1.
========================================================= */
function paginaMinhaEvolucaoV320(usuario, inicio, fim, totalAtual, totalAnterior, diasAtivos, setores) {
  const variacao = totalAnterior > 0 ? Math.round(((totalAtual-totalAnterior)/totalAnterior)*100) : null;
  const media = diasAtivos ? (totalAtual/diasAtivos).toFixed(1).replace('.', ',') : '0';
  const setoresHtml = setores.map(s => `<div class="card"><div class="mini">${escapeHtml(s.nome)}</div><strong style="font-size:25px">${s.total}</strong><div class="mini">conclusões no período</div></div>`).join('');
  const tendencia = variacao === null
    ? 'Ainda não há período anterior com produção suficiente para comparação.'
    : variacao > 0 ? `Sua produção cresceu ${variacao}% em relação ao período anterior.`
    : variacao < 0 ? `Sua produção ficou ${Math.abs(variacao)}% abaixo do período anterior.`
    : 'Sua produção manteve o mesmo volume do período anterior.';
  return layout(`
    <div class="cabecalho-pagina"><div><h2>⭐ Minha Evolução</h2><p class="nota">Acompanhe sua trajetória com base nos registros reais do Fluxo Lab. Esta tela não altera metas financeiras nem bonificações.</p></div><a class="botao botao-sec" href="/meu-espaco">← Meu Espaço</a></div>
    <section class="card" style="margin-bottom:14px"><form method="GET"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:end"><label>Início<input type="date" name="inicio" value="${escapeHtml(inicio)}"></label><label>Fim<input type="date" name="fim" value="${escapeHtml(fim)}"></label><button type="submit">Atualizar período</button></div></form></section>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:12px;margin-bottom:14px">
      <div class="card"><div class="mini">Produção concluída</div><strong style="font-size:30px">${totalAtual}</strong><div class="mini">unidades no período</div></div>
      <div class="card"><div class="mini">Dias com produção</div><strong style="font-size:30px">${diasAtivos}</strong><div class="mini">dias registrados</div></div>
      <div class="card"><div class="mini">Média por dia ativo</div><strong style="font-size:30px">${media}</strong><div class="mini">unidades por dia</div></div>
      <div class="card"><div class="mini">Comparação</div><strong style="font-size:25px">${variacao===null?'—':`${variacao>0?'+':''}${variacao}%`}</strong><div class="mini">versus período anterior equivalente</div></div>
    </div>
    <section class="card" style="margin-bottom:14px"><h3>📈 Seu ritmo</h3><p style="margin-bottom:0">${escapeHtml(tendencia)}</p></section>
    <h3>Desempenho por setor</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px">${setoresHtml||'<div class="card">Nenhuma produção encontrada neste período.</div>'}</div>
    <section class="card" style="margin-top:16px"><h3>O que este painel considera</h3><p class="nota">São contabilizadas somente operações concluídas atribuídas ao seu usuário, conforme os registros existentes. A comparação usa um período anterior com a mesma duração. Metas financeiras, valores por peça e bônus não são exibidos nem recalculados aqui.</p><p class="nota">Reconhecimentos formais, avaliações de qualidade e certificados serão incorporados em etapas futuras, quando houver registros próprios e auditáveis para eles.</p></section>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px"><a class="botao" href="/minha-producao?inicio=${encodeURIComponent(inicio)}&fim=${encodeURIComponent(fim)}">Ver histórico detalhado da produção →</a><a class="botao botao-sec" href="/lideranca-producao">Ver ranking da equipe</a></div>
  `, 'Minha Evolução', usuario);
}

/* =========================================================
   V3.19.0 — MEU ESPAÇO: CENTRAL PESSOAL
   Primeira etapa: painel e atalhos para módulos existentes.
   Não cria tabelas nem altera regras de produção/bonificação.
========================================================= */
function paginaMeuEspacoV319(usuario) {
  const nome = String(usuario?.nome || "Colaborador").trim().split(/\s+/)[0];
  const areas = areasUsuarioV31(usuario);
  const temProducao = usuario?.perfil === "FUNCIONARIO" || areasUsuarioBaseV31(usuario).length > 0;
  const podeChat = usuarioTemAreaDigital(usuario);
  const saudacao = (() => {
    const h = Number(new Intl.DateTimeFormat("pt-BR", { timeZone: "America/Sao_Paulo", hour: "2-digit", hourCycle: "h23" }).format(new Date()));
    return h < 12 ? "Bom dia" : (h < 18 ? "Boa tarde" : "Boa noite");
  })();
  const setores = areas.map(a => `${nomeAreaProducao(a)}: ${setoresUsuarioV31(usuario, a).map(s => nomeSetorAreaV31(a, s)).join(", ") || "—"}`).join(" · ") || "Acesso geral";
  const card = (icone, titulo, descricao, href, acao="Abrir") => `<a href="${href}" class="card card-meu-espaco-v319"><span class="icone-meu-espaco-v319">${icone}</span><span class="texto-meu-espaco-v319"><strong>${titulo}</strong><small>${descricao}</small><b>${acao} →</b></span></a>`;
  return layout(`
    <style>
      .nav-destaque-v319{border:1px solid rgba(32,184,181,.32)!important;background:rgba(16,139,137,.12)!important}.hero-meu-espaco-v319{background:linear-gradient(120deg,rgba(16,139,137,.24),rgba(18,43,52,.94));border:1px solid var(--borda);border-radius:18px;padding:24px;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap}
      .hero-meu-espaco-v319 h2{font-size:clamp(24px,3vw,34px);margin:4px 0 7px}.hero-meu-espaco-v319 p{margin:0;color:var(--texto-secundario)}
      .grade-meu-espaco-v319{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;margin:12px 0 22px}
      .card-meu-espaco-v319{display:flex;gap:13px;align-items:flex-start;text-decoration:none;color:inherit;min-height:112px;transition:transform .15s,border-color .15s}
      .card-meu-espaco-v319:hover{transform:translateY(-2px);border-color:var(--destaque,#20b8b5)}
      .icone-meu-espaco-v319{width:43px;height:43px;flex:0 0 43px;border-radius:12px;background:rgba(24,174,171,.14);display:grid;place-items:center;font-size:22px}
      .texto-meu-espaco-v319{display:flex;flex-direction:column;gap:6px}.texto-meu-espaco-v319 small{color:var(--texto-secundario);line-height:1.4}.texto-meu-espaco-v319 b{font-size:12px;color:#28c4bd;margin-top:3px}
      .aviso-futuro-v319{border:1px dashed var(--borda);border-radius:12px;padding:14px;background:rgba(120,140,150,.045)}
      .aviso-futuro-v319 strong{display:block;margin-bottom:4px}.aviso-futuro-v319 p{margin:0;color:var(--texto-secundario);font-size:13px}
      @media(max-width:600px){.hero-meu-espaco-v319{padding:18px}.grade-meu-espaco-v319{grid-template-columns:1fr}}
    </style>
    <section class="hero-meu-espaco-v319">
      <div><div class="mini">SUA CENTRAL PESSOAL</div><h2>${saudacao}, ${escapeHtml(nome)}! 👋</h2><p>Este é o seu espaço no Fluxo Lab. Aqui você acompanha seu trabalho e acessa suas ferramentas.</p><div class="mini" style="margin-top:10px">${escapeHtml(setores)}</div></div>
      <a class="botao" href="${temProducao?"/minha-producao":"/meu-perfil"}">${temProducao?"Ver minha produção":"Acessar meu perfil"} →</a>
    </section>
    <h3 style="margin:20px 0 8px">Meu dia e meu trabalho</h3>
    <div class="grade-meu-espaco-v319">
      ${temProducao?card("▦","Minha produção","Acompanhe sua produção, metas, bônus estimado e histórico.","/minha-producao"):""}
      ${podeChat?card("☏","Comunicação da equipe","Converse com a equipe e consulte mensagens do setor.","/digital/chat-equipe"):""}
      ${card("📝","Minhas anotações","Guarde lembretes e informações particulares.","/minhas-notas")}
      ${card("📅","Agenda e tarefas","Organize suas pendências e acompanhe tarefas atribuídas pela liderança.","/agenda-tarefas","Organizar dia")}
      ${card("👤","Meu perfil","Atualize sua foto, avatar, telefone e senha.","/meu-perfil")}
    </div>
    <h3 style="margin:20px 0 8px">Minha evolução</h3>
    <div class="grade-meu-espaco-v319">
      ${card("🎯","Minha evolução","Acompanhe sua produtividade, ritmo e comparação entre períodos.",temProducao?"/minha-evolucao":"/meu-perfil","Acompanhar")}
      ${card("🏅","Liderança da produção","Veja a classificação percentual da equipe.","/lideranca-producao","Ver ranking")}
    </div>
    <h3 style="margin:20px 0 8px">Aprendizado e comunicação</h3>
    <div class="grade-meu-espaco-v319">
      <a class="card card-meu-espaco-v319" href="/universidade"><span class="icone-meu-espaco-v319">🎓</span><span class="texto-meu-espaco-v319"><strong>Universidade Fluxo Lab</strong><small>Cursos internos, aulas, avaliações, certificados e competências.</small><b>Acessar →</b></span></a>
      <div class="aviso-futuro-v319"><strong>🧩 Minhas competências</strong><p>Habilidades por setor e trilha de desenvolvimento profissional.</p></div>
      <a class="card card-meu-espaco-v319" href="/comunicacao"><span class="icone-meu-espaco-v319">✉</span><span class="texto-meu-espaco-v319"><strong>Comunicação e solicitações</strong><small>Mural, enquetes, sugestões e pedidos internos com acompanhamento.</small><b>Acessar →</b></span></a>
      ${card("🏆","Minha coleção de emblemas","Conquistas por produção acumulada e semanas consecutivas com a meta atingida.","/emblemas","Ver coleção")}
    </div>
    <p class="nota">Esta primeira entrega organiza em um só lugar as ferramentas que já existem. Os módulos novos serão liberados gradualmente, sem alterar seus registros de produção ou as regras de bonificação.</p>
  `, "Meu Espaço", usuario);
}

