function paginaAuditoriaSistemaV31(usuario,itens){
  const linhas=itens.map(a=>`<tr><td>${escapeHtml(formatarData(a.criado_em))}</td><td>${escapeHtml(a.area)}</td><td>${escapeHtml(a.usuario_nome||`#${a.usuario_id}`)}</td><td>${escapeHtml(a.acao)}</td><td>${escapeHtml(a.entidade)}${a.registro_id?` #${escapeHtml(a.registro_id)}`:""}</td><td>${escapeHtml(a.campo||"—")}</td><td><div class="mini">Antes: ${escapeHtml(a.valor_anterior||"—")}</div><div class="mini">Depois: ${escapeHtml(a.valor_novo||"—")}</div>${a.motivo?`<div>${escapeHtml(a.motivo)}</div>`:""}</td></tr>`).join("");
  return layout(`<div class="cabecalho-pagina"><div><h2>Auditoria V3.4.4</h2><p class="nota">Registro administrativo. Histórico operacional antigo continua preservado nas auditorias específicas.</p></div><a class="botao botao-sec" href="/administracao">← Administração</a></div><div class="tabela-wrap"><table><thead><tr><th>Data</th><th>Área</th><th>Usuário</th><th>Ação</th><th>Registro</th><th>Campo</th><th>Alteração</th></tr></thead><tbody>${linhas||`<tr><td colspan="7">Sem registros.</td></tr>`}</tbody></table></div>`,"Auditoria",usuario);
}


/* =========================================================
   V3.1 · RELATÓRIOS E FECHAMENTOS POR ÁREA
========================================================= */

async function dadosRelatorioAreaV31(env, area, inicio, fim) {
  const setores = setoresAreaBonificacaoV25(area);
  const paineis = await Promise.all(setores.map(setor => obterPainelProducaoEquipeV25(env, area, setor, inicio, fim)));
  const setoresDados = setores.map((setor, indice) => {
    const painel = paineis[indice];
    const linhas = painel.linhas || [];
    return {
      setor,
      operacoes: linhas.reduce((s, x) => s + Number(x.quantidade || 0), 0),
      pt: linhas.reduce((s, x) => s + Number(x.pt || 0), 0),
      ppr: linhas.reduce((s, x) => s + Number(x.ppr || 0), 0),
      retrabalhos: linhas.reduce((s, x) => s + Number(x.retrabalhos || 0), 0),
      bonus_centavos: linhas.reduce((s, x) => s + Number(x.bonus_centavos || 0), 0),
      pessoas: linhas
    };
  });

  let unidadesConcluidas = 0;
  let entregas = 0;
  if (area === "DIGITAL") {
    const u = await env.db.prepare(`
      SELECT COUNT(*) AS total
      FROM trabalhos t
      WHERE t.excluido=0
        AND (COALESCE(t.superior_tipo,'NONE')='NONE' OR EXISTS(
          SELECT 1 FROM etapas es WHERE es.trabalho_id=t.id AND es.arcada='SUPERIOR' AND es.setor='ACABAMENTO' AND es.status='CONCLUIDO' AND es.concluido_em IS NOT NULL
        ))
        AND (COALESCE(t.inferior_tipo,'NONE')='NONE' OR EXISTS(
          SELECT 1 FROM etapas ei WHERE ei.trabalho_id=t.id AND ei.arcada='INFERIOR' AND ei.setor='ACABAMENTO' AND ei.status='CONCLUIDO' AND ei.concluido_em IS NOT NULL
        ))
        AND date((SELECT MAX(e2.concluido_em) FROM etapas e2 WHERE e2.trabalho_id=t.id AND e2.setor='ACABAMENTO' AND e2.status='CONCLUIDO'), '-3 hours') BETWEEN date(?) AND date(?)
    `).bind(inicio, fim).first();
    unidadesConcluidas = Number(u?.total || 0);
    const e = await env.db.prepare(`
      SELECT COUNT(*) AS total FROM remessas r
      WHERE r.data_entrega_real IS NOT NULL
        AND date(r.data_entrega_real) BETWEEN date(?) AND date(?)
        AND EXISTS (SELECT 1 FROM trabalhos t WHERE t.remessa_id=r.id AND t.excluido=0)
    `).bind(inicio, fim).first();
    entregas = Number(e?.total || 0);
  } else {
    const u = await env.db.prepare(`
      SELECT COUNT(*) AS total
      FROM etapas_convencionais e
      INNER JOIN pecas_convencionais p ON p.id=e.peca_id
      INNER JOIN trabalhos_convencionais t ON t.id=p.trabalho_id
      WHERE e.setor='QUALIDADE' AND e.status='CONCLUIDO' AND e.concluido_em IS NOT NULL
        AND t.excluido=0 AND date(e.concluido_em, '-3 hours') BETWEEN date(?) AND date(?)
    `).bind(inicio, fim).first();
    unidadesConcluidas = Number(u?.total || 0);
    const e = await env.db.prepare(`
      SELECT COUNT(*) AS total FROM entregas_municipios_convencionais
      WHERE date(data_entrega) BETWEEN date(?) AND date(?)
    `).bind(inicio, fim).first();
    entregas = Number(e?.total || 0);
  }

  return {
    area,
    inicio,
    fim,
    setores: setoresDados,
    total_operacoes: setoresDados.reduce((s, x) => s + x.operacoes, 0),
    total_pt: setoresDados.reduce((s, x) => s + x.pt, 0),
    total_ppr: setoresDados.reduce((s, x) => s + x.ppr, 0),
    total_retrabalhos: setoresDados.reduce((s, x) => s + x.retrabalhos, 0),
    bonus_total_centavos: setoresDados.reduce((s, x) => s + x.bonus_centavos, 0),
    unidades_concluidas: unidadesConcluidas,
    entregas
  };
}

async function dadosResumoGeralV31(env, inicio, fim) {
  const [digital, convencional] = await Promise.all([
    dadosRelatorioAreaV31(env, "DIGITAL", inicio, fim),
    dadosRelatorioAreaV31(env, "CONVENCIONAL", inicio, fim)
  ]);
  return { inicio, fim, digital, convencional };
}

function filtrosRelatorioV31(area, inicio, fim, podeGeral) {
  return `<div class="card" style="margin-bottom:14px"><form method="GET" action="/relatorios"><div style="display:flex;gap:8px;align-items:end;flex-wrap:wrap"><label>Área<select name="area"><option value="DIGITAL" ${area==="DIGITAL"?"selected":""}>Digital</option><option value="CONVENCIONAL" ${area==="CONVENCIONAL"?"selected":""}>Convencional</option>${podeGeral?`<option value="GERAL" ${area==="GERAL"?"selected":""}>Resumo geral</option>`:""}</select></label><label>Início<input type="date" name="inicio" value="${escapeHtml(inicio)}"></label><label>Fim<input type="date" name="fim" value="${escapeHtml(fim)}"></label><button>Aplicar</button></div></form></div>`;
}

function tabelaPessoasRelatorioV31(usuario, dados) {
  const podeBonus = isCoord(usuario);
  const linhas = [];
  for (const setor of dados.setores) {
    for (const p of setor.pessoas) {
      if (!Number(p.quantidade || 0) && !Number(p.retrabalhos || 0)) continue;
      linhas.push(`<tr><td>${escapeHtml(p.nome)}${p.excluido?" · excluído":(!Number(p.ativo||0)?" · inativo":"")}</td><td>${escapeHtml(perfilNome(p.perfil))}</td><td>${escapeHtml(nomeSetorAreaV31(dados.area,setor.setor))}</td><td>${Number(p.quantidade||0)}</td><td>${Number(p.dias_considerados||0)}${Number(p.meios_periodos_considerados||0)?` + ${Number(p.meios_periodos_considerados)} meio(s)`:""}</td><td>${p.meta_periodo===null||p.meta_periodo===undefined?"—":Number(p.meta_periodo)}</td><td>${p.excedente===null||p.excedente===undefined?"—":Number(p.excedente)}</td><td>${Number(p.retrabalhos||0)}</td>${podeBonus?`<td>${escapeHtml(formatarMoedaCentavosV25(p.bonus_centavos||0))}</td>`:""}</tr>`);
    }
  }
  return `<div class="tabela-wrap"><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Setor</th><th>Produção</th><th>Dias</th><th>Meta</th><th>Excedente</th><th>Retrabalhos</th>${podeBonus?"<th>Bônus</th>":""}</tr></thead><tbody>${linhas.join("")||`<tr><td colspan="9">Sem produção no período.</td></tr>`}</tbody></table></div>`;
}

function paginaRelatorioAreaV31(usuario, dados, mensagem="", tipo="sucesso") {
  const podeBonus=isCoord(usuario);
  const setorCards=dados.setores.map(s=>`<div class="card"><span class="mini">${escapeHtml(nomeSetorAreaV31(dados.area,s.setor))}</span><strong style="display:block;font-size:26px;margin:4px 0">${s.operacoes}</strong><div class="mini">PT ${s.pt} · PPR ${s.ppr} · Sem classificação ${Math.max(0,s.operacoes-s.pt-s.ppr)}</div><div class="mini">Retrabalhos: ${s.retrabalhos}</div>${podeBonus?`<div class="mini">Bônus: ${escapeHtml(formatarMoedaCentavosV25(s.bonus_centavos))}</div>`:""}</div>`).join("");
  return layout(`
    <div class="cabecalho-pagina"><div><h2>Relatório ${escapeHtml(nomeAreaProducao(dados.area))}</h2><p class="nota">${escapeHtml(formatarDataCurta(dados.inicio))} a ${escapeHtml(formatarDataCurta(dados.fim))}. As áreas nunca são misturadas para meta ou bonificação.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="botao botao-sec" href="/relatorios/exportar.csv?area=${dados.area}&inicio=${dados.inicio}&fim=${dados.fim}">CSV</a><a class="botao botao-sec" target="_blank" href="/relatorios/imprimir?area=${dados.area}&inicio=${dados.inicio}&fim=${dados.fim}">Imprimir / PDF</a></div></div>
    ${mensagem?`<div class="${tipo}">${escapeHtml(mensagem)}</div>`:""}
    ${filtrosRelatorioV31(dados.area,dados.inicio,dados.fim,isCoord(usuario))}
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-bottom:16px"><div class="card"><span class="mini">Operações</span><strong style="display:block;font-size:28px">${dados.total_operacoes}</strong></div><div class="card"><span class="mini">${dados.area==="DIGITAL"?"Pacientes concluídos":"Peças aprovadas"}</span><strong style="display:block;font-size:28px">${dados.unidades_concluidas}</strong></div><div class="card"><span class="mini">Retrabalhos</span><strong style="display:block;font-size:28px">${dados.total_retrabalhos}</strong></div><div class="card"><span class="mini">Entregas completas</span><strong style="display:block;font-size:28px">${dados.entregas}</strong></div>${podeBonus?`<div class="card"><span class="mini">Bonificação</span><strong style="display:block;font-size:24px">${escapeHtml(formatarMoedaCentavosV25(dados.bonus_total_centavos))}</strong></div>`:""}</div>
    <h2>Setores</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px;margin-bottom:20px">${setorCards}</div>
    <h2>Produção por pessoa e setor</h2>${tabelaPessoasRelatorioV31(usuario,dados)}
  `,`Relatório ${nomeAreaProducao(dados.area)}`,usuario);
}

function paginaResumoGeralV31(usuario,dados){
  const card=(nome,d)=>`<div class="card"><h2 style="margin-top:0">${nome}</h2><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px"><div><span class="mini">Operações</span><strong style="display:block;font-size:27px">${d.total_operacoes}</strong></div><div><span class="mini">Concluídas/aprovadas</span><strong style="display:block;font-size:27px">${d.unidades_concluidas}</strong></div><div><span class="mini">Retrabalhos</span><strong style="display:block;font-size:27px">${d.total_retrabalhos}</strong></div><div><span class="mini">Entregas</span><strong style="display:block;font-size:27px">${d.entregas}</strong></div></div><a class="botao botao-sec" style="margin-top:14px" href="/relatorios?area=${nome.toUpperCase()}&inicio=${dados.inicio}&fim=${dados.fim}">Abrir relatório ${nome}</a></div>`;
  return layout(`<div class="cabecalho-pagina"><div><h2>Resumo Geral</h2><p class="nota">Visão executiva. Os números permanecem separados e nunca são somados para meta.</p></div></div>${filtrosRelatorioV31("GERAL",dados.inicio,dados.fim,true)}<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:14px">${card("Digital",dados.digital)}${card("Convencional",dados.convencional)}</div>`,`Resumo Geral`,usuario);
}

function csvEscapeV31(valor){
  const s=String(valor??"");
  return `"${s.replaceAll('"','""')}"`;
}

function csvRelatorioAreaV31(usuario,dados){
  const linhas=[];
  linhas.push([`Fluxo Lab V${VERSAO_FLUXO_LAB}`,`Relatório ${nomeAreaProducao(dados.area)}`]);
  linhas.push(["Período",`${dados.inicio} a ${dados.fim}`]);
  linhas.push([]);
  linhas.push(["SETOR","OPERAÇÕES","PT","PPR","SEM CLASSIFICAÇÃO","RETRABALHOS"]);
  for(const s of dados.setores) linhas.push([nomeSetorAreaV31(dados.area,s.setor),s.operacoes,s.pt,s.ppr,Math.max(0,s.operacoes-s.pt-s.ppr),s.retrabalhos]);
  linhas.push([]);
  const cab=["PESSOA","PERFIL","SETOR","PRODUÇÃO","DIAS COMPLETOS","MEIOS PERÍODOS","META","EXCEDENTE","RETRABALHOS"];
  if(isCoord(usuario)) cab.push("BÔNUS");
  linhas.push(cab);
  for(const s of dados.setores){for(const p of s.pessoas){if(!Number(p.quantidade||0)&&!Number(p.retrabalhos||0))continue;const row=[p.nome,perfilNome(p.perfil),nomeSetorAreaV31(dados.area,s.setor),p.quantidade,p.dias_considerados,p.meios_periodos_considerados||0,p.meta_periodo??"",p.excedente??"",p.retrabalhos];if(isCoord(usuario))row.push(formatarMoedaCentavosV25(p.bonus_centavos||0));linhas.push(row)}}
  return linhas.map(row=>row.map(csvEscapeV31).join(";")).join("\r\n");
}

function paginaImpressaoRelatorioAreaV31(usuario,dados){
  const podeBonus=isCoord(usuario);
  const setores=dados.setores.map(s=>`<tr><td>${escapeHtml(nomeSetorAreaV31(dados.area,s.setor))}</td><td>${s.operacoes}</td><td>${s.pt}</td><td>${s.ppr}</td><td>${Math.max(0,s.operacoes-s.pt-s.ppr)}</td><td>${s.retrabalhos}</td></tr>`).join("");
  const pessoas=[];for(const s of dados.setores){for(const p of s.pessoas){if(!Number(p.quantidade||0)&&!Number(p.retrabalhos||0))continue;pessoas.push(`<tr><td>${escapeHtml(p.nome)}</td><td>${escapeHtml(perfilNome(p.perfil))}</td><td>${escapeHtml(nomeSetorAreaV31(dados.area,s.setor))}</td><td>${p.quantidade}</td><td>${p.dias_considerados}${Number(p.meios_periodos_considerados||0)?` + ${Number(p.meios_periodos_considerados)} meio(s)`:""}</td>${podeBonus?`<td>${escapeHtml(formatarMoedaCentavosV25(p.bonus_centavos||0))}</td>`:""}</tr>`)}}
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório ${escapeHtml(nomeAreaProducao(dados.area))}</title><style>body{font-family:Arial,sans-serif;color:#111;margin:28px}table{width:100%;border-collapse:collapse;margin:12px 0 24px}th,td{border:1px solid #bbb;padding:7px;text-align:left}th{background:#eee}.cards{display:flex;gap:10px;flex-wrap:wrap}.card{border:1px solid #bbb;padding:12px;min-width:140px}.no-print{margin-bottom:16px}@media print{.no-print{display:none}body{margin:0}}</style></head><body><div class="no-print"><button onclick="window.print()">Imprimir / Salvar PDF</button></div><h1>Fluxo Lab · ${escapeHtml(nomeAreaProducao(dados.area))}</h1><p>${escapeHtml(formatarDataCurta(dados.inicio))} a ${escapeHtml(formatarDataCurta(dados.fim))}</p><div class="cards"><div class="card">Operações<br><b>${dados.total_operacoes}</b></div><div class="card">Concluídas/aprovadas<br><b>${dados.unidades_concluidas}</b></div><div class="card">Retrabalhos<br><b>${dados.total_retrabalhos}</b></div><div class="card">Entregas<br><b>${dados.entregas}</b></div></div><h2>Setores</h2><table><thead><tr><th>Setor</th><th>Operações</th><th>PT</th><th>PPR</th><th>Sem classificação</th><th>Retrabalhos</th></tr></thead><tbody>${setores}</tbody></table><h2>Pessoas</h2><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Setor</th><th>Produção</th><th>Dias</th>${podeBonus?"<th>Bônus</th>":""}</tr></thead><tbody>${pessoas.join("")}</tbody></table></body></html>`;
}

async function listarFechamentosAreaV31(env, area=""){
  const filtro=["DIGITAL","CONVENCIONAL"].includes(area)?area:"";
  const r=await env.db.prepare(`SELECT f.*,u.nome AS fechado_por_nome,ur.nome AS reaberto_por_nome FROM fechamentos_mensais_area f LEFT JOIN usuarios u ON u.id=f.fechado_por LEFT JOIN usuarios ur ON ur.id=f.reaberto_por WHERE (?='' OR f.area=?) ORDER BY f.ano DESC,f.mes DESC,CASE f.area WHEN 'DIGITAL' THEN 1 ELSE 2 END`).bind(filtro,filtro).all();
  return r.results||[];
}

async function listarFechamentosLegadoV31(env){
  try{const r=await env.db.prepare(`SELECT id,ano,mes,status,fechado_em FROM fechamentos_mensais ORDER BY ano DESC,mes DESC LIMIT 24`).all();return r.results||[]}catch{return[]}
}

async function salvarFechamentoAreaV31(env,usuario,ano,mes,area,observacao=""){
  if(!["DIGITAL","CONVENCIONAL"].includes(area))throw new Error("Área inválida.");
  const periodoMes=periodoMesV27(ano,mes);if(!periodoMes)throw new Error("Ano ou mês inválido.");
  const existente=await env.db.prepare(`SELECT * FROM fechamentos_mensais_area WHERE ano=? AND mes=? AND area=? LIMIT 1`).bind(ano,mes,area).first();
  if(existente&&existente.status==="FECHADO")throw new Error(`${nomeAreaProducao(area)} já está fechado neste mês. Reabra antes de recalcular.`);

  // V3.4.4: todo cálculo externo acontece ANTES de tocar no snapshot anterior.
  const dados=await dadosRelatorioAreaV31(env,area,periodoMes.inicio,periodoMes.fim);
  let extras=[];
  if(area==="DIGITAL"){
    extras=(await env.db.prepare(`SELECT r.id,r.municipio,r.numero,r.data_recebimento,r.data_prevista_entrega,r.data_finalizacao,r.data_entrega_real,COUNT(t.id) AS total_trabalhos,SUM(CASE WHEN t.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM etapas e WHERE e.trabalho_id=t.id AND e.status!='CONCLUIDO') THEN 1 ELSE 0 END) AS concluidos FROM remessas r INNER JOIN trabalhos t ON t.remessa_id=r.id AND t.excluido=0 WHERE date(r.data_recebimento)<=date(?) AND (r.data_entrega_real IS NULL OR date(r.data_entrega_real)>=date(?)) GROUP BY r.id ORDER BY r.id`).bind(periodoMes.fim,periodoMes.inicio).all()).results||[];
  }else{
    const ciclos=(await env.db.prepare(`SELECT id,nome FROM ciclos_convencionais WHERE date(data_inicio)<=date(?) AND date(data_fim)>=date(?) ORDER BY id`).bind(periodoMes.fim,periodoMes.inicio).all()).results||[];
    for(const c of ciclos){for(const cidade of await listarCidadesCicloV31(env,c.id))extras.push({c,cidade});}
  }

  let id=existente?Number(existente.id):0;
  if(!id){const cr=await env.db.prepare(`INSERT INTO fechamentos_mensais_area (ano,mes,area,periodo_inicio,periodo_fim,status,fechado_por,observacao) VALUES (?,?,?,?,?,'REABERTO',?,?)`).bind(ano,mes,area,periodoMes.inicio,periodoMes.fim,usuario.id,observacao||null).run();id=Number(cr.meta.last_row_id)}

  const anterior={
    setores:(await env.db.prepare(`SELECT * FROM fechamento_setores_mensais_area WHERE fechamento_id=?`).bind(id).all()).results||[],
    pessoas:(await env.db.prepare(`SELECT * FROM fechamento_pessoas_mensais_area WHERE fechamento_id=?`).bind(id).all()).results||[],
    remessas:(await env.db.prepare(`SELECT * FROM fechamento_remessas_digitais_mensais WHERE fechamento_id=?`).bind(id).all()).results||[],
    cidades:(await env.db.prepare(`SELECT * FROM fechamento_cidades_convencionais_mensais WHERE fechamento_id=?`).bind(id).all()).results||[]
  };

  const restaurar=async()=>{
    try{
      await env.db.batch([
        env.db.prepare(`DELETE FROM fechamento_setores_mensais_area WHERE fechamento_id=?`).bind(id),
        env.db.prepare(`DELETE FROM fechamento_pessoas_mensais_area WHERE fechamento_id=?`).bind(id),
        env.db.prepare(`DELETE FROM fechamento_remessas_digitais_mensais WHERE fechamento_id=?`).bind(id),
        env.db.prepare(`DELETE FROM fechamento_cidades_convencionais_mensais WHERE fechamento_id=?`).bind(id)
      ]);
      const st=[];
      for(const r of anterior.setores)st.push(env.db.prepare(`INSERT INTO fechamento_setores_mensais_area (fechamento_id,setor,total_operacoes,total_pt,total_ppr,sem_classificacao) VALUES (?,?,?,?,?,?)`).bind(id,r.setor,r.total_operacoes,r.total_pt,r.total_ppr,r.sem_classificacao));
      for(const r of anterior.pessoas)st.push(env.db.prepare(`INSERT INTO fechamento_pessoas_mensais_area (fechamento_id,usuario_id,usuario_nome,perfil_snapshot,setor,producao_valida,dias_detectados,dias_considerados,meios_periodos_considerados,meta_diaria,meta_meio_periodo,meta_periodo,excedente,elegivel_bonus,valor_excedente_centavos,bonus_centavos,retrabalhos) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,r.usuario_id,r.usuario_nome,r.perfil_snapshot,r.setor,r.producao_valida,r.dias_detectados,r.dias_considerados,r.meios_periodos_considerados,r.meta_diaria,r.meta_meio_periodo,r.meta_periodo,r.excedente,r.elegivel_bonus,r.valor_excedente_centavos,r.bonus_centavos,r.retrabalhos));
      for(const r of anterior.remessas)st.push(env.db.prepare(`INSERT INTO fechamento_remessas_digitais_mensais (fechamento_id,remessa_id,municipio,numero,data_recebimento,data_prevista_entrega,data_finalizacao,data_entrega_real,total_trabalhos,concluidos,status_snapshot) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).bind(id,r.remessa_id,r.municipio,r.numero,r.data_recebimento,r.data_prevista_entrega,r.data_finalizacao,r.data_entrega_real,r.total_trabalhos,r.concluidos,r.status_snapshot));
      for(const r of anterior.cidades)st.push(env.db.prepare(`INSERT INTO fechamento_cidades_convencionais_mensais (fechamento_id,ciclo_municipio_id,ciclo_id,ciclo_nome,municipio,uf,total_pecas,pecas_prontas,data_entrega,status_snapshot) VALUES (?,?,?,?,?,?,?,?,?,?)`).bind(id,r.ciclo_municipio_id,r.ciclo_id,r.ciclo_nome,r.municipio,r.uf,r.total_pecas,r.pecas_prontas,r.data_entrega,r.status_snapshot));
      await executarBatchV27(env,st);
      if (existente) {
        await env.db.prepare(`UPDATE fechamentos_mensais_area SET periodo_inicio=?,periodo_fim=?,status=?,total_operacoes=?,total_unidades_concluidas=?,total_retrabalhos=?,total_entregas=?,bonus_total_centavos=?,fechado_por=?,fechado_em=?,reaberto_por=?,reaberto_em=?,motivo_reabertura=?,observacao=? WHERE id=?`).bind(existente.periodo_inicio,existente.periodo_fim,existente.status,existente.total_operacoes,existente.total_unidades_concluidas,existente.total_retrabalhos,existente.total_entregas,existente.bonus_total_centavos,existente.fechado_por,existente.fechado_em,existente.reaberto_por,existente.reaberto_em,existente.motivo_reabertura,existente.observacao,id).run();
      } else {
        await env.db.prepare(`DELETE FROM fechamentos_mensais_area WHERE id=?`).bind(id).run();
      }
    }catch(e){console.log('V3.4.4: falha ao restaurar snapshot anterior:',e?.message||e);}
  };

  try{
    await env.db.batch([
      env.db.prepare(`DELETE FROM fechamento_setores_mensais_area WHERE fechamento_id=?`).bind(id),
      env.db.prepare(`DELETE FROM fechamento_pessoas_mensais_area WHERE fechamento_id=?`).bind(id),
      env.db.prepare(`DELETE FROM fechamento_remessas_digitais_mensais WHERE fechamento_id=?`).bind(id),
      env.db.prepare(`DELETE FROM fechamento_cidades_convencionais_mensais WHERE fechamento_id=?`).bind(id)
    ]);
    const statements=[];
    for(const setor of dados.setores){
      statements.push(env.db.prepare(`INSERT INTO fechamento_setores_mensais_area (fechamento_id,setor,total_operacoes,total_pt,total_ppr,sem_classificacao) VALUES (?,?,?,?,?,?)`).bind(id,setor.setor,setor.operacoes,setor.pt,setor.ppr,Math.max(0,setor.operacoes-setor.pt-setor.ppr)));
      for(const p of setor.pessoas){if(!Number(p.quantidade||0)&&!Number(p.retrabalhos||0))continue;statements.push(env.db.prepare(`INSERT INTO fechamento_pessoas_mensais_area (fechamento_id,usuario_id,usuario_nome,perfil_snapshot,setor,producao_valida,dias_detectados,dias_considerados,meios_periodos_considerados,meta_diaria,meta_meio_periodo,meta_periodo,excedente,elegivel_bonus,valor_excedente_centavos,bonus_centavos,retrabalhos) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,p.id,p.nome,p.perfil,setor.setor,Number(p.quantidade||0),Number(p.dias_detectados||0),Number(p.dias_considerados||0),Number(p.meios_periodos_considerados||0),p.meta_diaria??null,Number(p.meta_meio_periodo||0),Number(p.meta_periodo||0),Number(p.excedente||0),p.elegivel_bonus?1:0,Number(p.valor_centavos||0),Number(p.bonus_centavos||0),Number(p.retrabalhos||0)));}
    }
    if(area==="DIGITAL")for(const r of extras){const total=Number(r.total_trabalhos||0),conc=Number(r.concluidos||0);const status=r.data_entrega_real?"ENTREGUE":(total>0&&conc===total?"PRONTA":"EM_PRODUCAO");statements.push(env.db.prepare(`INSERT INTO fechamento_remessas_digitais_mensais (fechamento_id,remessa_id,municipio,numero,data_recebimento,data_prevista_entrega,data_finalizacao,data_entrega_real,total_trabalhos,concluidos,status_snapshot) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).bind(id,r.id,r.municipio,r.numero,r.data_recebimento||null,r.data_prevista_entrega||null,r.data_finalizacao||null,r.data_entrega_real||null,total,conc,status));}
    else for(const x of extras){const c=x.c,cidade=x.cidade;statements.push(env.db.prepare(`INSERT INTO fechamento_cidades_convencionais_mensais (fechamento_id,ciclo_municipio_id,ciclo_id,ciclo_nome,municipio,uf,total_pecas,pecas_prontas,data_entrega,status_snapshot) VALUES (?,?,?,?,?,?,?,?,?,?)`).bind(id,cidade.id,c.id,c.nome,cidade.municipio,cidade.uf||"",cidade.total_pecas,cidade.pecas_prontas,cidade.data_entrega||null,cidade.status_v31));}
    await executarBatchV27(env,statements);
    await env.db.prepare(`UPDATE fechamentos_mensais_area SET periodo_inicio=?,periodo_fim=?,status='FECHADO',total_operacoes=?,total_unidades_concluidas=?,total_retrabalhos=?,total_entregas=?,bonus_total_centavos=?,fechado_por=?,fechado_em=CURRENT_TIMESTAMP,reaberto_por=NULL,reaberto_em=NULL,motivo_reabertura=NULL,observacao=? WHERE id=?`).bind(periodoMes.inicio,periodoMes.fim,dados.total_operacoes,dados.unidades_concluidas,dados.total_retrabalhos,dados.entregas,dados.bonus_total_centavos,usuario.id,observacao||null,id).run();
    const auditou=await registrarAuditoriaSistemaV31(env,usuario.id,area,"FECHAMENTO_MENSAL","FECHAMENTO",id,"status",existente?.status||"NOVO","FECHADO",observacao||null);
    if(!auditou) throw new Error("Falha ao registrar a auditoria obrigatória do fechamento.");
    return id;
  }catch(err){await restaurar();throw new Error(`Fechamento não substituído: ${err?.message||'falha ao gerar o novo snapshot.'}`);}
}

async function obterFechamentoAreaV31(env,id){
  const f=await env.db.prepare(`SELECT f.*,u.nome AS fechado_por_nome,r.nome AS reaberto_por_nome FROM fechamentos_mensais_area f LEFT JOIN usuarios u ON u.id=f.fechado_por LEFT JOIN usuarios r ON r.id=f.reaberto_por WHERE f.id=? LIMIT 1`).bind(id).first();if(!f)return null;
  const [setores,pessoas]=await Promise.all([env.db.prepare(`SELECT * FROM fechamento_setores_mensais_area WHERE fechamento_id=? ORDER BY setor`).bind(id).all(),env.db.prepare(`SELECT * FROM fechamento_pessoas_mensais_area WHERE fechamento_id=? ORDER BY usuario_nome,setor`).bind(id).all()]);
  let extras=[];if(f.area==="DIGITAL"){const x=await env.db.prepare(`SELECT * FROM fechamento_remessas_digitais_mensais WHERE fechamento_id=? ORDER BY municipio,numero`).bind(id).all();extras=x.results||[]}else{const x=await env.db.prepare(`SELECT * FROM fechamento_cidades_convencionais_mensais WHERE fechamento_id=? ORDER BY ciclo_id,municipio`).bind(id).all();extras=x.results||[]}
  return{fechamento:f,setores:setores.results||[],pessoas:pessoas.results||[],extras};
}

function paginaFechamentosV31(usuario,fechamentos,legado=[],mensagem="",tipo="sucesso"){
  const podeFechar=isCoord(usuario);
  const linhas=fechamentos.map(f=>`<tr><td>${escapeHtml(nomeMesV27(f.mes))}/${f.ano}</td><td><span class="badge neutro">${escapeHtml(nomeAreaProducao(f.area))}</span></td><td><span class="badge ${classeStatusV31(f.status)}">${escapeHtml(f.status)}</span></td><td>${Number(f.total_operacoes||0)}</td><td>${Number(f.total_entregas||0)}</td>${podeFechar?`<td>${escapeHtml(formatarMoedaCentavosV25(f.bonus_total_centavos||0))}</td>`:""}<td><a class="botao botao-sec" href="/fechamentos/${f.id}">Abrir</a></td></tr>`).join("");
  const leg=legado.map(f=>`<tr><td>${escapeHtml(nomeMesV27(f.mes))}/${f.ano}</td><td>V3.0 legado</td><td>${escapeHtml(f.status)}</td><td><a class="botao botao-sec" href="/fechamentos-legado/${f.id}">Histórico legado</a></td></tr>`).join("");
  return layout(`<div class="cabecalho-pagina"><div><h2>Fechamentos mensais</h2><p class="nota">Digital e Convencional fecham separadamente. O passado da V3.0 permanece preservado.</p></div><a class="botao botao-sec" href="/administracao">← Administração</a></div>${mensagem?`<div class="${tipo}">${escapeHtml(mensagem)}</div>`:""}${podeFechar?`<div class="card" style="margin-bottom:16px"><h3 style="margin-top:0">Fechar área do mês</h3><form method="POST" action="/fechamentos/fechar"><div class="form-grid"><label>Ano<input type="number" name="ano" min="2020" max="2100" value="${new Date().getUTCFullYear()}" required></label><label>Mês<select name="mes">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${(i+1)===(new Date().getUTCMonth()+1)?"selected":""}>${escapeHtml(nomeMesV27(i+1))}</option>`).join("")}</select></label><label>Área<select name="area"><option value="DIGITAL">Digital</option><option value="CONVENCIONAL">Convencional</option></select></label><label>Observação<input name="observacao" maxlength="500"></label><div class="full"><button>Fechar área</button></div></div></form></div>`:""}<div class="tabela-wrap"><table><thead><tr><th>Mês</th><th>Área</th><th>Status</th><th>Operações</th><th>Entregas</th>${podeFechar?"<th>Bônus</th>":""}<th>Ação</th></tr></thead><tbody>${linhas||`<tr><td colspan="7">Nenhum fechamento por área.</td></tr>`}</tbody></table></div>${legado.length?`<h2 style="margin-top:24px">Fechamentos legados V3.0</h2><div class="tabela-wrap"><table><thead><tr><th>Mês</th><th>Tipo</th><th>Status</th><th>Ação</th></tr></thead><tbody>${leg}</tbody></table></div>`:""}`,"Fechamentos",usuario);
}

function paginaFechamentoDetalheV31(usuario,dados,mensagem="",tipo="sucesso"){
  const f=dados.fechamento,podeBonus=isCoord(usuario);
  const setores=dados.setores.map(s=>`<tr><td>${escapeHtml(nomeSetorAreaV31(f.area,s.setor))}</td><td>${s.total_operacoes}</td><td>${s.total_pt}</td><td>${s.total_ppr}</td><td>${s.sem_classificacao}</td></tr>`).join("");
  const pessoas=dados.pessoas.map(p=>`<tr><td>${escapeHtml(p.usuario_nome)}</td><td>${escapeHtml(p.perfil_snapshot)}</td><td>${escapeHtml(nomeSetorAreaV31(f.area,p.setor))}</td><td>${p.producao_valida}</td><td>${p.dias_considerados}${Number(p.meios_periodos_considerados||0)?` + ${Number(p.meios_periodos_considerados)} meio(s)`:""}</td><td>${p.meta_periodo}</td><td>${p.excedente}</td>${podeBonus?`<td>${escapeHtml(formatarMoedaCentavosV25(p.bonus_centavos))}</td>`:""}</tr>`).join("");
  const extras=f.area==="DIGITAL"?dados.extras.map(r=>`<tr><td>${escapeHtml(r.municipio)} · ${String(r.numero).padStart(2,"0")}</td><td>${r.total_trabalhos}</td><td>${r.concluidos}</td><td>${escapeHtml(r.status_snapshot)}</td><td>${escapeHtml(formatarDataCurta(r.data_entrega_real))}</td></tr>`).join(""):dados.extras.map(c=>`<tr><td>${escapeHtml(c.ciclo_nome||`Ciclo #${c.ciclo_id}`)}</td><td>${escapeHtml(c.municipio)}</td><td>${c.total_pecas}</td><td>${c.pecas_prontas}</td><td>${escapeHtml(c.status_snapshot)}</td><td>${escapeHtml(formatarDataCurta(c.data_entrega))}</td></tr>`).join("");
  return layout(`<div class="cabecalho-pagina"><div><h2>${escapeHtml(nomeAreaProducao(f.area))} · ${escapeHtml(nomeMesV27(f.mes))}/${f.ano}</h2><p class="nota">Snapshot histórico: ${escapeHtml(f.status)} · ${escapeHtml(formatarDataCurta(f.periodo_inicio))} a ${escapeHtml(formatarDataCurta(f.periodo_fim))}</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="botao botao-sec" href="/fechamentos/${f.id}/exportar.csv">CSV</a><a class="botao botao-sec" target="_blank" href="/fechamentos/${f.id}/imprimir">Imprimir / PDF</a><a class="botao botao-sec" href="/fechamentos">← Fechamentos</a></div></div>${mensagem?`<div class="${tipo}">${escapeHtml(mensagem)}</div>`:""}<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-bottom:18px"><div class="card"><span class="mini">Operações</span><strong style="display:block;font-size:27px">${f.total_operacoes}</strong></div><div class="card"><span class="mini">Concluídas/aprovadas</span><strong style="display:block;font-size:27px">${f.total_unidades_concluidas}</strong></div><div class="card"><span class="mini">Retrabalhos</span><strong style="display:block;font-size:27px">${f.total_retrabalhos}</strong></div><div class="card"><span class="mini">Entregas</span><strong style="display:block;font-size:27px">${f.total_entregas}</strong></div>${podeBonus?`<div class="card"><span class="mini">Bônus</span><strong>${escapeHtml(formatarMoedaCentavosV25(f.bonus_total_centavos))}</strong></div>`:""}</div>${isCoord(usuario)&&f.status==="FECHADO"?`<div class="card" style="margin-bottom:16px"><form method="POST" action="/fechamentos/${f.id}/reabrir"><label>Motivo da reabertura<input name="motivo" required minlength="5"></label><button>Reabrir ${escapeHtml(nomeAreaProducao(f.area))}</button></form></div>`:""}<h2>Setores</h2><div class="tabela-wrap"><table><thead><tr><th>Setor</th><th>Operações</th><th>PT</th><th>PPR</th><th>Sem classificação</th></tr></thead><tbody>${setores}</tbody></table></div><h2>Pessoas</h2><div class="tabela-wrap"><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Setor</th><th>Produção</th><th>Dias</th><th>Meta</th><th>Excedente</th>${podeBonus?"<th>Bônus</th>":""}</tr></thead><tbody>${pessoas}</tbody></table></div><h2>${f.area==="DIGITAL"?"Remessas Digitais":"Cidades do Convencional"}</h2><div class="tabela-wrap"><table><tbody>${extras||`<tr><td>Sem itens no snapshot.</td></tr>`}</tbody></table></div>`,`Fechamento ${nomeAreaProducao(f.area)}`,usuario);
}

function csvFechamentoAreaV31(usuario,dados){
  const f=dados.fechamento,rows=[[`Fluxo Lab V${VERSAO_FLUXO_LAB}`,"Fechamento",nomeAreaProducao(f.area),`${f.ano}-${String(f.mes).padStart(2,"0")}`],[],["SETOR","OPERAÇÕES","PT","PPR","SEM CLASSIFICAÇÃO"]];
  for(const s of dados.setores)rows.push([nomeSetorAreaV31(f.area,s.setor),s.total_operacoes,s.total_pt,s.total_ppr,s.sem_classificacao]);rows.push([]);const cab=["PESSOA","PERFIL","SETOR","PRODUÇÃO","DIAS COMPLETOS","MEIOS PERÍODOS","META","EXCEDENTE"];if(isCoord(usuario))cab.push("BÔNUS");rows.push(cab);for(const p of dados.pessoas){const r=[p.usuario_nome,p.perfil_snapshot,nomeSetorAreaV31(f.area,p.setor),p.producao_valida,p.dias_considerados,p.meios_periodos_considerados||0,p.meta_periodo,p.excedente];if(isCoord(usuario))r.push(formatarMoedaCentavosV25(p.bonus_centavos));rows.push(r)}return rows.map(r=>r.map(csvEscapeV31).join(";")).join("\r\n");
}

function paginaImpressaoFechamentoAreaV31(usuario,dados){
  const f=dados.fechamento;return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Fechamento ${escapeHtml(nomeAreaProducao(f.area))}</title><style>body{font-family:Arial,sans-serif;color:#111;margin:28px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:7px;text-align:left}th{background:#eee}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()">Imprimir / Salvar PDF</button><h1>Fluxo Lab · ${escapeHtml(nomeAreaProducao(f.area))}</h1><h2>${escapeHtml(nomeMesV27(f.mes))}/${f.ano}</h2><p>${escapeHtml(formatarDataCurta(f.periodo_inicio))} a ${escapeHtml(formatarDataCurta(f.periodo_fim))}</p><p>Operações: <b>${f.total_operacoes}</b> · Concluídas/aprovadas: <b>${f.total_unidades_concluidas}</b> · Retrabalhos: <b>${f.total_retrabalhos}</b> · Entregas: <b>${f.total_entregas}</b></p><h2>Setores</h2><table><thead><tr><th>Setor</th><th>Operações</th><th>PT</th><th>PPR</th><th>Sem classificação</th></tr></thead><tbody>${dados.setores.map(s=>`<tr><td>${escapeHtml(nomeSetorAreaV31(f.area,s.setor))}</td><td>${s.total_operacoes}</td><td>${s.total_pt}</td><td>${s.total_ppr}</td><td>${s.sem_classificacao}</td></tr>`).join("")}</tbody></table></body></html>`;
}



