function formatarBytesV32(valor) {
  const n = Math.max(0, Number(valor || 0));
  if (n < 1000) return `${n} B`;
  if (n < 1000000) return `${(n / 1000).toFixed(1)} KB`;
  if (n < 1000000000) return `${(n / 1000000).toFixed(1)} MB`;
  return `${(n / 1000000000).toFixed(2)} GB`;
}

function categoriaStlNomeV32(valor) { return categoriaStlNomeV32ServiceV51(valor); }

function arcadaStlNomeV32(valor) { return arcadaStlNomeV32ServiceV51(valor); }

async function obterConfigArmazenamentoStlV32(env) { return await obterConfigArmazenamentoStlV32ServiceV51(env); }

async function resumoArmazenamentoStlV32(env) { return await resumoArmazenamentoStlV32ServiceV51(env); }

async function listarArquivosStlTrabalhoV32(env, trabalhoId) { return await listarArquivosStlTrabalhoV32ServiceV51(env, trabalhoId); }

async function obterArquivoStlV32(env, id) { return await obterArquivoStlV32ServiceV51(env, id); }

function stlLiberadoExclusaoV32(item) { return stlLiberadoExclusaoV32ServiceV51(item); }

function jsonResponseV32(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: cabecalhosSegurancaV30("application/json; charset=UTF-8")
  });
}

function nomeDownloadSeguroV32(nome) {
  return String(nome || "arquivo.stl")
    .replace(/[\r\n]/g, " ")
    .trim()
    .slice(0, 180) || "arquivo.stl";
}

function blocoArquivosStlV32(usuario, trabalho, arquivos, armazenamento) {
  const entregue = Number(trabalho?.entregue || 0) === 1;
  const podeUpload = false; // V3.2.1: novos envios usam pacotes/pastas multipart.
  const podeGerenciar = podeGerenciarAreaV31(usuario, "DIGITAL");
  const podeExcluirDefinitivo = isCoord(usuario);

  const cor = armazenamento.nivel === "BLOQUEADO" || armazenamento.nivel === "CRITICO"
    ? "#c73a32"
    : armazenamento.nivel === "AVISO"
      ? "#b46a0a"
      : "#159a9c";

  const aviso = armazenamento.nivel === "BLOQUEADO"
    ? `<div class="erro" style="margin-top:10px">Armazenamento STL atingiu o limite interno de ${escapeHtml(formatarBytesV32(armazenamento.limite_bytes))}. Novos uploads estão bloqueados.</div>`
    : armazenamento.nivel === "CRITICO"
      ? `<div class="erro" style="margin-top:10px">Armazenamento STL quase cheio. Restam ${escapeHtml(formatarBytesV32(armazenamento.disponivel_bytes))} até o limite de segurança.</div>`
      : armazenamento.nivel === "AVISO"
        ? `<div class="info" style="margin-top:10px">Armazenamento STL acima de ${escapeHtml(formatarBytesV32(armazenamento.aviso_bytes))}. Restam ${escapeHtml(formatarBytesV32(armazenamento.disponivel_bytes))}.</div>`
        : "";

  const linhas = arquivos.map(a => {
    const liberado = stlLiberadoExclusaoV32(a);
    const statusClasse = a.status === "ATIVO" ? "ok" : a.status === "ARQUIVADO" ? "alerta" : "neutro";
    const statusNome = a.status === "ATIVO" ? "Ativo" : a.status === "ARQUIVADO" ? "Arquivado" : "Excluído";

    const acoes = a.status === "EXCLUIDO"
      ? `<span class="mini">Excluído definitivamente em ${escapeHtml(formatarData(a.excluido_em))}</span>`
      : `
        <a class="botao botao-sec" href="/stl/${a.id}/download">Baixar</a>
        ${podeGerenciar && liberado && a.status === "ATIVO" ? `
          <details style="margin-top:6px">
            <summary style="cursor:pointer;font-weight:700">Arquivar</summary>
            <form method="POST" action="/stl/${a.id}/arquivar" style="margin-top:6px">
              <input name="motivo" required minlength="3" maxlength="300" placeholder="Motivo do arquivamento">
              <button class="botao-sec" style="margin-top:5px">Arquivar</button>
            </form>
          </details>` : ""}
        ${podeGerenciar && a.status === "ARQUIVADO" ? `
          <form method="POST" action="/stl/${a.id}/restaurar" style="margin-top:6px">
            <button class="botao-sec">Restaurar</button>
          </form>` : ""}
        ${podeExcluirDefinitivo && liberado ? `
          <details style="margin-top:6px">
            <summary style="cursor:pointer;font-weight:800;color:#b42318">Excluir definitivamente</summary>
            <form method="POST" action="/stl/${a.id}/excluir" style="margin-top:6px" onsubmit="return confirm('Excluir definitivamente este STL do R2? O arquivo físico não poderá ser recuperado pelo Fluxo Lab.');">
              <input name="motivo" required minlength="5" maxlength="300" placeholder="Motivo da exclusão definitiva">
              <button style="margin-top:5px;background:#b42318">Excluir do R2</button>
            </form>
          </details>` : ""}
      `;

    return `
      <tr>
        <td><strong>${escapeHtml(a.nome_exibicao || a.nome_original)}</strong><div class="mini">v${Number(a.versao || 1)} · ${escapeHtml(arcadaStlNomeV32(a.arcada))} · ${escapeHtml(categoriaStlNomeV32(a.categoria))}</div></td>
        <td>${escapeHtml(formatarBytesV32(a.tamanho_bytes))}</td>
        <td><span class="badge ${statusClasse}">${statusNome}</span><div class="mini">${liberado ? "Exclusão liberada: entrega registrada" : "Exclusão bloqueada até a entrega"}</div></td>
        <td>${escapeHtml(a.enviado_por_nome || "—")}<div class="mini">${escapeHtml(formatarData(a.enviado_em))}</div></td>
        <td style="min-width:190px">${acoes}</td>
      </tr>
    `;
  }).join("");

  const upload = podeUpload ? `
    <div class="card" style="margin-top:14px;background:#fbffff">
      <h3 style="margin-top:0">Enviar STL</h3>
      <p class="nota">Somente arquivos .stl. Máximo por arquivo: <strong>${escapeHtml(formatarBytesV32(armazenamento.limite_arquivo_bytes))}</strong>. O arquivo permanece privado no R2.</p>
      <form id="form-stl-v32-${trabalho.id}">
        <div class="form-grid">
          <label class="full">Arquivo STL<input id="arquivo-stl-v32-${trabalho.id}" type="file" accept=".stl,model/stl,application/sla" required></label>
          <label>Arcada<select id="arcada-stl-v32-${trabalho.id}" required><option value="SUPERIOR">Superior</option><option value="INFERIOR">Inferior</option><option value="AMBAS">Ambas</option><option value="NAO_APLICAVEL">Não aplicável</option></select></label>
          <label>Categoria<select id="categoria-stl-v32-${trabalho.id}" required><option value="BASE">Base</option><option value="DENTES">Dentes</option><option value="GENGIVA">Gengiva</option><option value="PPR_FLEX">PPR flex</option><option value="PROJETO">Projeto</option><option value="OUTRO">Outro</option></select></label>
          <div style="align-self:end"><button id="botao-stl-v32-${trabalho.id}">Enviar para o R2</button></div>
        </div>
      </form>
      <div id="status-stl-v32-${trabalho.id}" class="mini" style="margin-top:8px"></div>
    </div>
    <script>
    (() => {
      const form = document.getElementById("form-stl-v32-${trabalho.id}");
      const input = document.getElementById("arquivo-stl-v32-${trabalho.id}");
      const botao = document.getElementById("botao-stl-v32-${trabalho.id}");
      const status = document.getElementById("status-stl-v32-${trabalho.id}");
      if (!form || !input || !botao || !status) return;
      form.addEventListener("submit", async (evento) => {
        evento.preventDefault();
        const arquivo = input.files && input.files[0];
        if (!arquivo) return;
        if (!String(arquivo.name || "").toLowerCase().endsWith(".stl")) {
          status.textContent = "Selecione um arquivo .stl.";
          return;
        }
        if (arquivo.size <= 0 || arquivo.size > ${Number(armazenamento.limite_arquivo_bytes)}) {
          status.textContent = "Arquivo fora do limite permitido.";
          return;
        }
        const params = new URLSearchParams({
          nome: arquivo.name,
          tamanho: String(arquivo.size),
          arcada: document.getElementById("arcada-stl-v32-${trabalho.id}").value,
          categoria: document.getElementById("categoria-stl-v32-${trabalho.id}").value
        });
        botao.disabled = true;
        status.textContent = "Enviando STL para o armazenamento privado...";
        try {
          const resposta = await fetch("/trabalhos/${trabalho.id}/stl/upload?" + params.toString(), {
            method: "POST",
            headers: { "Content-Type": "model/stl", "x-fluxolab": "1" },
            body: arquivo
          });
          const dados = await resposta.json().catch(() => ({ mensagem: "Resposta inválida do servidor." }));
          const chave = resposta.ok ? "ok" : "erro";
          window.location.href = "/trabalhos/${trabalho.id}?" + chave + "=" + encodeURIComponent(dados.mensagem || (resposta.ok ? "STL enviado." : "Falha no upload."));
        } catch (e) {
          status.textContent = "Falha de conexão durante o upload.";
          botao.disabled = false;
        }
      });
    })();
    </script>
  ` : entregue
    ? `<div class="info" style="margin-top:14px">Entrega registrada. Novos arquivos estão bloqueados para este trabalho.</div>`
    : armazenamento.nivel === "BLOQUEADO"
      ? `<div class="erro" style="margin-top:14px">Upload bloqueado pelo limite interno de armazenamento.</div>`
      : `<div class="info" style="margin-top:14px">Novos envios agora são feitos em <a href="/trabalhos/${trabalho.id}/pacotes"><strong>Pacotes / pastas</strong></a>, com transferência CAD ↔ Fatiamento e download da pasta completa.</div>`;

  return `
    <div class="card" style="margin-top:18px">
      <div class="cabecalho-pagina" style="margin-bottom:10px">
        <div><h2 style="margin:0">Arquivos STL individuais</h2><p class="nota">Compatibilidade com arquivos enviados antes do fluxo por pastas.</p></div>
        <div style="display:flex;gap:8px;flex-wrap:wrap"><a class="botao" href="/trabalhos/${trabalho.id}/pacotes">Pacotes / pastas</a>${podeGerenciar ? `<a class="botao botao-sec" href="/armazenamento-stl">Armazenamento</a>` : ""}</div>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px">
        <div><span class="mini">Uso total</span><strong style="display:block">${escapeHtml(formatarBytesV32(armazenamento.usado_bytes))} / ${escapeHtml(formatarBytesV32(armazenamento.limite_bytes))}</strong></div>
        <div><span class="mini">Disponível</span><strong style="display:block">${escapeHtml(formatarBytesV32(armazenamento.disponivel_bytes))}</strong></div>
        <div><span class="mini">Neste paciente</span><strong style="display:block">${arquivos.filter(x => x.status !== "EXCLUIDO").length} arquivo(s)</strong></div>
      </div>
      <div style="height:10px;background:#e6ecee;border-radius:99px;overflow:hidden;margin-top:10px"><div style="width:${armazenamento.percentual.toFixed(2)}%;height:100%;background:${cor}"></div></div>
      ${aviso}
      ${upload}
      <div class="tabela-wrap" style="margin-top:14px"><table><thead><tr><th>Arquivo</th><th>Tamanho</th><th>Status</th><th>Enviado por</th><th>Ações</th></tr></thead><tbody>${linhas || `<tr><td colspan="5">Nenhum STL armazenado para este paciente.</td></tr>`}</tbody></table></div>
    </div>
  `;
}

async function listarStlLiberadosV32(env) { return await listarStlLiberadosV32ServiceV51(env); }

async function totalRealBucketV32(bucket) { return await totalRealBucketV32ServiceV51(bucket); }

function paginaArmazenamentoStlV32(usuario, resumo, liberados, real = null, mensagem = "", tipo = "sucesso") {
  const cor = resumo.nivel === "BLOQUEADO" || resumo.nivel === "CRITICO" ? "#c73a32" : resumo.nivel === "AVISO" ? "#b46a0a" : "#159a9c";
  const divergencia = real ? Number(real.total_bytes || 0) - Number(resumo.usado_bytes || 0) : null;
  const linhas = liberados.map(a => `
    <tr>
      <td><a href="/trabalhos/${a.trabalho_id}"><strong>${escapeHtml(a.paciente)}</strong></a><div class="mini">${escapeHtml(a.codigo)} · ${escapeHtml(a.municipio)}${a.remessa_numero ? ` · Remessa ${String(a.remessa_numero).padStart(2,"0")}` : ""}</div></td>
      <td>${escapeHtml(a.nome_exibicao || a.nome_original)}<div class="mini">${escapeHtml(arcadaStlNomeV32(a.arcada))} · ${escapeHtml(categoriaStlNomeV32(a.categoria))}</div></td>
      <td><strong>${escapeHtml(formatarBytesV32(a.tamanho_bytes))}</strong></td>
      <td>${escapeHtml(formatarDataCurta(a.remessa_data_entrega || a.trabalho_data_entrega))}</td>
      <td><span class="badge ok">Liberado para exclusão</span></td>
    </tr>
  `).join("");

  return layout(`
    <div class="cabecalho-pagina"><div><h2>Armazenamento de arquivos</h2><p class="nota">Cloudflare R2 privado · STL individuais + pacotes digitais · limite interno de segurança</p></div><div style="display:flex;gap:8px"><a class="botao botao-sec" href="/arquivos-digitais">Caixa de arquivos</a><a class="botao botao-sec" href="/digital">← Digital</a></div></div>
    ${mensagem ? `<div class="${tipo}">${escapeHtml(mensagem)}</div>` : ""}
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-bottom:16px">
      <div class="card"><span class="mini">Usado / reservado</span><strong style="font-size:24px;display:block">${escapeHtml(formatarBytesV32(resumo.usado_bytes))}</strong></div>
      <div class="card"><span class="mini">Limite interno</span><strong style="font-size:24px;display:block">${escapeHtml(formatarBytesV32(resumo.limite_bytes))}</strong></div>
      <div class="card"><span class="mini">Disponível</span><strong style="font-size:24px;display:block">${escapeHtml(formatarBytesV32(resumo.disponivel_bytes))}</strong></div>
      <div class="card"><span class="mini">Ativos / reservados</span><strong style="font-size:24px;display:block">${resumo.ativos} / ${resumo.reservados || 0}</strong><div class="mini">Arquivados legados: ${resumo.arquivados}</div></div>
    </div>
    <div class="card" style="margin-bottom:16px">
      <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><strong>${resumo.percentual.toFixed(1)}% do limite interno</strong><span>${escapeHtml(formatarBytesV32(resumo.usado_bytes))} de ${escapeHtml(formatarBytesV32(resumo.limite_bytes))}</span></div>
      <div style="height:15px;background:#e6ecee;border-radius:99px;overflow:hidden;margin-top:9px"><div style="width:${resumo.percentual.toFixed(2)}%;height:100%;background:${cor}"></div></div>
      <p class="nota" style="margin-bottom:0">Aviso em ${escapeHtml(formatarBytesV32(resumo.aviso_bytes))} · crítico em ${escapeHtml(formatarBytesV32(resumo.alerta_critico_bytes))} · uploads bloqueados em ${escapeHtml(formatarBytesV32(resumo.limite_bytes))}.</p>
    </div>
    ${resumo.nivel === "BLOQUEADO" ? `<div class="erro">Novos uploads STL estão bloqueados até liberar espaço.</div>` : resumo.nivel === "CRITICO" ? `<div class="erro">Armazenamento quase cheio. Priorize a exclusão de arquivos já entregues.</div>` : resumo.nivel === "AVISO" ? `<div class="info">Armazenamento acima do nível de aviso.</div>` : ""}
    <div class="card" style="margin:16px 0">
      <h3 style="margin-top:0">Conferência do bucket R2</h3>
      <p class="nota">A contagem normal usa o D1 para evitar listar todo o bucket a cada página. Esta conferência lê os objetos reais do R2 e aponta divergências, sem apagar ou corrigir nada automaticamente.</p>
      <form method="POST" action="/armazenamento-stl/recalcular"><button class="botao-sec">Conferir R2 agora</button></form>
      ${real ? `<div class="info" style="margin-top:10px"><strong>R2 real:</strong> ${escapeHtml(formatarBytesV32(real.total_bytes))} em ${Number(real.quantidade || 0)} objeto(s). <strong>D1 contabilizado:</strong> ${escapeHtml(formatarBytesV32(resumo.usado_bytes))}. <strong>Diferença:</strong> ${divergencia === 0 ? "sem divergência" : `${divergencia > 0 ? "+" : ""}${escapeHtml(formatarBytesV32(Math.abs(divergencia)))} ${divergencia > 0 ? "a mais no R2" : "a mais no D1"}`}.</div>` : ""}
    </div>
    <h2>Arquivos já liberados para exclusão</h2>
    <p class="nota">Somente trabalhos com entrega registrada entram nesta lista. Os maiores aparecem primeiro para facilitar a liberação de espaço.</p>
    <div class="tabela-wrap"><table><thead><tr><th>Paciente</th><th>Arquivo</th><th>Tamanho</th><th>Entrega</th><th>Status</th></tr></thead><tbody>${linhas || `<tr><td colspan="5">Nenhum arquivo liberado para exclusão.</td></tr>`}</tbody></table></div>
  `, "Armazenamento STL", usuario);
}


/* =========================================================
   V3.2.1 · PACOTES DE ARQUIVOS DIGITAIS · CAD ↔ FATIAMENTO
   - Pasta inteira via webkitdirectory
   - Upload multipart R2 em partes de 8 MiB, sem limite artificial por arquivo
   - Limite global interno de 9 GB continua valendo
   - Download completo como ZIP streaming, preservando subpastas
   - Destinatário pode excluir depois de confirmar recebimento e conferência do pacote completo
   - Gerência Digital / Coordenação / Administração podem enviar, baixar e excluir
========================================================= */

const PACOTE_PARTE_BYTES_V321 = 8 * 1024 * 1024;
const PACOTE_EXTENSOES_V321 = new Set([".stl", ".obj", ".goo", ".zip", ".pdf", ".png", ".jpg", ".jpeg"]);

function extensaoArquivoV321(nome) {
  const s = String(nome || "").trim().toLowerCase();
  const i = s.lastIndexOf(".");
  return i >= 0 ? s.slice(i) : "";
}

function caminhoRelativoSeguroV321(caminho, nomeFallback = "arquivo") {
  const partes = String(caminho || nomeFallback || "arquivo")
    .replace(/\\/g, "/")
    .split("/")
    .map(p => p.replace(/[\x00-\x1f\x7f]/g, " ").trim())
    .filter(p => p && p !== "." && p !== "..");
  const seguro = partes.join("/").slice(0, 700);
  return seguro || String(nomeFallback || "arquivo").replace(/[\\/]/g, "_").slice(0, 180) || "arquivo";
}

function nomePacoteSeguroV321(nome) {
  return String(nome || "Pacote de arquivos")
    .replace(/[\r\n\x00-\x1f]/g, " ")
    .replace(/[\\/:*?"<>|]/g, "-")
    .trim()
    .slice(0, 120) || "Pacote de arquivos";
}

function mimeArquivoV321(nome, informado = "") {
  const ext = extensaoArquivoV321(nome);
  if (ext === ".stl") return "model/stl";
  if (ext === ".obj") return "text/plain";
  return String(informado || "application/octet-stream").slice(0, 100);
}

function nomeSetorPacoteV321(setor) {
  return nomeSetorAreaV31("DIGITAL", setor);
}

function setoresDigitaisUsuarioV321(usuario) {
  return setoresUsuarioV31(usuario, "DIGITAL");
}

function usuarioPodeVerPacoteV321(usuario, pacote) {
  if (!usuario || !pacote || !usuarioTemAreaDigital(usuario)) return false;
  if (podeGerenciarAreaV31(usuario, "DIGITAL")) return true;
  const setores = setoresDigitaisUsuarioV321(usuario);
  return setores.includes(String(pacote.setor_origem)) || setores.includes(String(pacote.setor_destino));
}

function usuarioPodeCriarFluxoV321(usuario, origem, destino) {
  const setoresValidos = ["CAD/CAM", "FATIAMENTO", "IMPRESSAO", "ACABAMENTO"];
  if (!setoresValidos.includes(origem) || !setoresValidos.includes(destino) || origem === destino) return false;
  if (podeGerenciarAreaV31(usuario, "DIGITAL")) return true;
  const setores = setoresDigitaisUsuarioV321(usuario);
  if (!setores.includes(origem)) return false;
  return (origem === "CAD/CAM" && destino === "FATIAMENTO") ||
         (origem === "FATIAMENTO" && destino === "CAD/CAM");
}

function usuarioPodeContinuarUploadV321(usuario, pacote) {
  if (!usuario || !pacote || !usuarioTemAreaDigital(usuario)) return false;
  if (String(pacote.status || "") !== "ATIVO") return false;
  if (Number(pacote.entregue || 0) || Number(pacote.arquivado || 0) || Number(pacote.excluido || 0)) return false;
  return podeGerenciarAreaV31(usuario, "DIGITAL") || Number(pacote.criado_por) === Number(usuario.id);
}

// V3.17.1 · Entregas soltas (sem paciente cadastrado) não pertencem a nenhum trabalho.
function pacoteSoltoV3171(pacote) {
  return !Number(pacote?.trabalho_id || 0);
}

async function usuarioPodeAcessarPacoteV3171(env, usuario, pacote) {
  if (!usuario || !pacote || !usuarioTemAreaDigital(usuario)) return false;
  if (pacoteSoltoV3171(pacote)) return true;
  if (!usuarioPodeVerPacoteV321(usuario, pacote)) return false;
  return await usuarioPodeVerTrabalhoDigitalV345(env, usuario, pacote.trabalho_id);
}

async function usuarioPodeAcessarUploadPacoteV3171(env, usuario, pacote) {
  if (!usuarioPodeContinuarUploadV321(usuario, pacote)) return false;
  if (pacoteSoltoV3171(pacote)) return true;
  return await usuarioPodeVerTrabalhoDigitalV345(env, usuario, pacote.trabalho_id);
}

function urlBasePacoteV3171(pacote) {
  return pacoteSoltoV3171(pacote) ? "/arquivos-digitais" : `/trabalhos/${Number(pacote.trabalho_id)}/pacotes`;
}

function voltarSeguroV3171(valor, padrao = "/arquivos-digitais") {
  const v = String(valor || "").trim();
  return /^\/(?!\/)[^\\\r\n]*$/.test(v) ? v : padrao;
}

function anexarMensagemV3171(url, chave, mensagem) {
  return `${url}${String(url).includes("?") ? "&" : "?"}${chave}=${encodeURIComponent(mensagem)}`;
}

async function obterPacoteV321(env, id, usuarioId = 0) {
  return await env.db.prepare(`
    SELECT
      p.*,
      t.codigo,
      t.paciente,
      t.municipio,
      t.entregue,
      t.arquivado,
      t.excluido,
      u.nome AS criado_por_nome,
      (SELECT COUNT(*) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status!='EXCLUIDO') AS total_arquivos,
      (SELECT COUNT(*) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status='PENDENTE') AS pendentes,
      (SELECT COALESCE(SUM(a.tamanho_bytes),0) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status IN ('PENDENTE','ATIVO')) AS tamanho_total_bytes,
      (SELECT COUNT(*) FROM downloads_pacotes_digitais d WHERE d.pacote_id=p.id AND d.tipo_download='PACOTE_COMPLETO') AS downloads_completos,
      (SELECT COUNT(*) FROM downloads_pacotes_digitais d WHERE d.pacote_id=p.id AND d.usuario_id=? AND d.tipo_download='PACOTE_COMPLETO') AS meus_downloads
    FROM pacotes_arquivos_digitais p
    LEFT JOIN trabalhos t ON t.id=p.trabalho_id
    LEFT JOIN usuarios u ON u.id=p.criado_por
    WHERE p.id=?
    LIMIT 1
  `).bind(Number(usuarioId || 0), id).first();
}

async function listarArquivosPacoteV321(env, pacoteId, incluirExcluidos = false) {
  const r = await env.db.prepare(`
    SELECT a.*,u.nome AS enviado_por_nome
    FROM arquivos_pacotes_digitais a
    LEFT JOIN usuarios u ON u.id=a.enviado_por
    WHERE a.pacote_id=? ${incluirExcluidos ? "" : "AND a.status!='EXCLUIDO'"}
    ORDER BY a.id
  `).bind(pacoteId).all();
  return r.results || [];
}

async function listarPacotesTrabalhoV321(env, trabalhoId, usuarioId) {
  const r = await env.db.prepare(`
    SELECT
      p.*,
      u.nome AS criado_por_nome,
      (SELECT COUNT(*) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status!='EXCLUIDO') AS total_arquivos,
      (SELECT COUNT(*) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status='PENDENTE') AS pendentes,
      (SELECT COALESCE(SUM(a.tamanho_bytes),0) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status IN ('PENDENTE','ATIVO')) AS tamanho_total_bytes,
      (SELECT COUNT(*) FROM downloads_pacotes_digitais d WHERE d.pacote_id=p.id AND d.tipo_download='PACOTE_COMPLETO') AS downloads_completos,
      (SELECT COUNT(*) FROM downloads_pacotes_digitais d WHERE d.pacote_id=p.id AND d.usuario_id=? AND d.tipo_download='PACOTE_COMPLETO') AS meus_downloads
    FROM pacotes_arquivos_digitais p
    LEFT JOIN usuarios u ON u.id=p.criado_por
    WHERE p.trabalho_id=?
    ORDER BY p.id DESC
  `).bind(usuarioId, trabalhoId).all();
  return r.results || [];
}

async function listarPacotesVisiveisV321(env, usuario) {
  const r = await env.db.prepare(`
    SELECT
      p.*,
      t.codigo,t.paciente,t.municipio,t.entregue,t.arquivado,t.excluido,
      u.nome AS criado_por_nome,
      (SELECT COUNT(*) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status!='EXCLUIDO') AS total_arquivos,
      (SELECT COUNT(*) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status='PENDENTE') AS pendentes,
      (SELECT COALESCE(SUM(a.tamanho_bytes),0) FROM arquivos_pacotes_digitais a WHERE a.pacote_id=p.id AND a.status IN ('PENDENTE','ATIVO')) AS tamanho_total_bytes,
      (SELECT COUNT(*) FROM downloads_pacotes_digitais d WHERE d.pacote_id=p.id AND d.tipo_download='PACOTE_COMPLETO') AS downloads_completos,
      (SELECT COUNT(*) FROM downloads_pacotes_digitais d WHERE d.pacote_id=p.id AND d.usuario_id=? AND d.tipo_download='PACOTE_COMPLETO') AS meus_downloads
    FROM pacotes_arquivos_digitais p
    INNER JOIN trabalhos t ON t.id=p.trabalho_id
    LEFT JOIN usuarios u ON u.id=p.criado_por
    WHERE 1=1
      ${sqlVisibilidadeTrabalhoDigitalLiteralV345(usuario, "t")}
    ORDER BY CASE p.status WHEN 'ATIVO' THEN 1 WHEN 'CANCELADO' THEN 2 ELSE 3 END,p.id DESC
    LIMIT 500
  `).bind(usuario.id).all();
  return (r.results || []).filter(p => usuarioPodeVerPacoteV321(usuario, p));
}

async function registrarEventoPacoteV321(env, pacoteId, usuarioId, evento, quantidade = 0, tamanho = 0, detalhe = null) {
  await env.db.prepare(`
    INSERT INTO eventos_pacotes_digitais
      (pacote_id,usuario_id,evento,quantidade_arquivos,tamanho_bytes,detalhe)
    VALUES (?,?,?,?,?,?)
  `).bind(pacoteId, usuarioId || null, evento, Math.max(0, Number(quantidade || 0)), Math.max(0, Number(tamanho || 0)), detalhe || null).run();
}

async function usuarioPodeExcluirPacoteV321(env, usuario, pacote) {
  if (!usuario || !pacote || pacote.status !== "ATIVO" || !usuarioTemAreaDigital(usuario)) return false;
  const gestao=podeGerenciarAreaV31(usuario,"DIGITAL");
  const setores=setoresDigitaisUsuarioV321(usuario);
  if (!gestao && !setores.includes(String(pacote.setor_destino))) return false;
  const d = gestao
    ? await env.db.prepare(`SELECT id FROM downloads_pacotes_digitais WHERE pacote_id=? AND tipo_download='PACOTE_COMPLETO' LIMIT 1`).bind(pacote.id).first()
    : await env.db.prepare(`SELECT id FROM downloads_pacotes_digitais WHERE pacote_id=? AND usuario_id=? AND tipo_download='PACOTE_COMPLETO' LIMIT 1`).bind(pacote.id,usuario.id).first();
  return !!d;
}

function formularioOrigemDestinoV321(usuario) {
  const todos = ["CAD/CAM", "FATIAMENTO", "IMPRESSAO", "ACABAMENTO"];
  const gestao = podeGerenciarAreaV31(usuario, "DIGITAL");
  const setores = setoresDigitaisUsuarioV321(usuario);
  const origens = gestao ? todos : setores.filter(s => s === "CAD/CAM" || s === "FATIAMENTO");
  if (!gestao && origens.length === 1) {
    const origem = origens[0];
    const destino = origem === "CAD/CAM" ? "FATIAMENTO" : "CAD/CAM";
    return `<label>Setor de origem<select id="pacote-origem" required><option value="${escapeHtml(origem)}">${escapeHtml(nomeSetorPacoteV321(origem))}</option></select></label><label>Destino<select id="pacote-destino" required><option value="${escapeHtml(destino)}">${escapeHtml(nomeSetorPacoteV321(destino))}</option></select></label>`;
  }
  const destinos = gestao ? todos : ["CAD/CAM", "FATIAMENTO"];
  const optsO = origens.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(nomeSetorPacoteV321(s))}</option>`).join("");
  const optsD = destinos.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(nomeSetorPacoteV321(s))}</option>`).join("");
  return `<label>Setor de origem<select id="pacote-origem" ${gestao ? "" : 'data-reciproco="1"'} required>${optsO}</select></label><label>Destino<select id="pacote-destino" ${gestao ? "" : 'data-reciproco="1"'} required>${optsD}</select></label>`;
}

function blocoPacoteV321(usuario, p, arquivos) {
  const pronto = p.status === "ATIVO" && Number(p.pendentes || 0) === 0 && Number(p.total_arquivos || 0) > 0;
  const podeGestao = podeGerenciarAreaV31(usuario, "DIGITAL");
  const destinoMeu = setoresDigitaisUsuarioV321(usuario).includes(String(p.setor_destino));
  const liberadoMeu = destinoMeu && Number(p.meus_downloads || 0) > 0;
  const podeConfirmarRecebimento = pronto && destinoMeu && !liberadoMeu;
  const podeExcluirVisual = p.status === "ATIVO" && (liberadoMeu || (podeGestao && Number(p.downloads_completos || 0) > 0));
  const podeCancelar = p.status === "ATIVO" && Number(p.pendentes || 0) > 0 && usuarioPodeContinuarUploadV321(usuario, p);
  const status = p.status !== "ATIVO" ? p.status : Number(p.pendentes || 0) ? "UPLOAD INCOMPLETO" : "PRONTO";
  const classe = status === "PRONTO" ? "ok" : status === "UPLOAD INCOMPLETO" ? "alerta" : "neutro";
  const lista = arquivos.map(a => `<tr><td>${escapeHtml(a.caminho_relativo)}</td><td>${escapeHtml(formatarBytesV32(a.tamanho_bytes))}</td><td><span class="badge ${a.status === "ATIVO" ? "ok" : a.status === "PENDENTE" ? "alerta" : "neutro"}">${escapeHtml(a.status)}</span></td><td>${a.status === "ATIVO" ? `<a class="botao botao-sec" href="/pacotes/${p.id}/arquivos/${a.id}/download">Baixar</a>` : "—"}</td></tr>`).join("");

  return `<div class="card" style="margin-bottom:14px">
    <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap">
      <div><strong style="font-size:17px">${escapeHtml(p.nome_pacote)}</strong><div class="mini">${escapeHtml(nomeSetorPacoteV321(p.setor_origem))} → ${escapeHtml(nomeSetorPacoteV321(p.setor_destino))} · enviado por ${escapeHtml(p.criado_por_nome || "—")} · ${escapeHtml(formatarData(p.criado_em))}</div></div>
      <span class="badge ${classe}">${escapeHtml(status)}</span>
    </div>
    ${p.observacao ? `<p class="nota">${escapeHtml(p.observacao)}</p>` : ""}
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:9px;margin-top:10px">
      <div><span class="mini">Arquivos</span><strong style="display:block">${Number(p.total_arquivos || 0)}</strong></div>
      <div><span class="mini">Tamanho</span><strong style="display:block">${escapeHtml(formatarBytesV32(p.tamanho_total_bytes))}</strong></div>
      <div><span class="mini">Recebimentos confirmados</span><strong style="display:block">${Number(p.downloads_completos || 0)}</strong></div>
      <div><span class="mini">Exclusão</span><strong style="display:block">${liberadoMeu ? "Recebimento confirmado" : podeGestao ? (Number(p.downloads_completos||0)>0?"Recebimento confirmado pelo destino":"Aguardando confirmação do destino") : destinoMeu ? "Baixe e confirme o recebimento" : "Somente destino/gestão"}</strong></div>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">
      ${pronto ? `<a class="botao" href="/pacotes/${p.id}/download">⬇ Baixar pasta completa (.zip)</a>` : ""}
      ${podeConfirmarRecebimento ? `<form method="POST" action="/pacotes/${p.id}/confirmar-recebimento" onsubmit="return confirm('Confirma que a pasta completa foi recebida e conferida no computador de destino? Esta confirmação pode liberar a exclusão do armazenamento.');"><button class="botao-verde">✓ Confirmar recebimento e conferência</button></form>` : ""}
      ${podeCancelar ? `<form method="POST" action="/pacotes/${p.id}/cancelar" onsubmit="return confirm('Cancelar este pacote incompleto e remover arquivos já enviados?');"><button class="botao-sec">Cancelar pacote incompleto</button></form>` : ""}
    </div>
    ${podeExcluirVisual ? `<details style="margin-top:10px"><summary style="cursor:pointer;font-weight:800;color:#b42318">Excluir do armazenamento</summary><form method="POST" action="/pacotes/${p.id}/excluir" style="margin-top:8px" onsubmit="return confirm('Excluir definitivamente todos os arquivos físicos deste pacote do R2? O histórico será preservado.');"><input name="motivo" required minlength="5" maxlength="300" placeholder="Motivo da exclusão"><button style="margin-top:6px;background:#b42318">Excluir arquivos do R2</button></form></details>` : ""}
    <details style="margin-top:10px"><summary style="cursor:pointer;font-weight:700">Ver arquivos da pasta</summary><div class="tabela-wrap" style="margin-top:8px"><table><thead><tr><th>Caminho</th><th>Tamanho</th><th>Status</th><th></th></tr></thead><tbody>${lista || `<tr><td colspan="4">Sem arquivos.</td></tr>`}</tbody></table></div></details>
  </div>`;
}

function paginaPacotesTrabalhoV321(usuario, trabalho, pacotes, arquivosPorPacote, armazenamento, mensagem = "", tipo = "sucesso") {
  const podeNovo = usuarioTemAreaDigital(usuario) && !Number(trabalho.entregue || 0) && (podeGerenciarAreaV31(usuario, "DIGITAL") || setoresDigitaisUsuarioV321(usuario).some(s => s === "CAD/CAM" || s === "FATIAMENTO"));
  const cor = armazenamento.nivel === "BLOQUEADO" || armazenamento.nivel === "CRITICO" ? "#c73a32" : armazenamento.nivel === "AVISO" ? "#b46a0a" : "#159a9c";
  const cards = pacotes.map(p => blocoPacoteV321(usuario, p, arquivosPorPacote.get(Number(p.id)) || [])).join("");
  const bloqueio = armazenamento.nivel === "BLOQUEADO" ? `<div class="erro">Novos pacotes estão bloqueados porque o limite interno de ${escapeHtml(formatarBytesV32(armazenamento.limite_bytes))} foi atingido.</div>` : "";

  const form = podeNovo && armazenamento.nivel !== "BLOQUEADO" ? `<div class="card" style="margin-bottom:16px;background:#fbffff">
    <h3 style="margin-top:0">Enviar pasta / pacote</h3>
    <p class="nota">Selecione a pasta inteira. O Fluxo Lab preserva subpastas, envia arquivos .STL e .OBJ em partes para o R2 e não impõe limite artificial por arquivo. O limite geral de segurança do laboratório continua em ${escapeHtml(formatarBytesV32(armazenamento.limite_bytes))}.</p>
    <form id="form-pacote-v321">
      <div class="form-grid">
        ${formularioOrigemDestinoV321(usuario)}
        <label class="full">Nome do pacote<input id="pacote-nome" maxlength="120" placeholder="Será preenchido com o nome da pasta"></label>
        <label class="full">Pasta<input id="pacote-pasta" type="file" webkitdirectory directory multiple required></label>
        <label class="full">Observação<input id="pacote-observacao" maxlength="500" placeholder="Opcional"></label>
        <div class="full"><button id="pacote-botao">Enviar pasta para o Fluxo Lab</button></div>
      </div>
    </form>
    <div id="pacote-status" class="mini" style="margin-top:8px"></div>
    <div id="pacote-progresso" style="height:10px;background:#e6ecee;border-radius:99px;overflow:hidden;margin-top:8px;display:none"><div id="pacote-progresso-barra" style="height:100%;width:0;background:#159a9c"></div></div>
  </div>
  <script>
  (() => {
    const form=document.getElementById('form-pacote-v321');
    const input=document.getElementById('pacote-pasta');
    const nome=document.getElementById('pacote-nome');
    const origem=document.getElementById('pacote-origem');
    const destino=document.getElementById('pacote-destino');
    const obs=document.getElementById('pacote-observacao');
    const status=document.getElementById('pacote-status');
    const botao=document.getElementById('pacote-botao');
    const prog=document.getElementById('pacote-progresso');
    const barra=document.getElementById('pacote-progresso-barra');
    if(!form||!input) return;
    if(origem && destino && origem.dataset.reciproco==='1'){
      const ajustar=()=>{ if(origem.value==='CAD/CAM') destino.value='FATIAMENTO'; else if(origem.value==='FATIAMENTO') destino.value='CAD/CAM'; };
      origem.addEventListener('change',ajustar); ajustar();
    }
    input.addEventListener('change',()=>{
      const files=Array.from(input.files||[]);
      if(files.length && !nome.value){ const rel=files[0].webkitRelativePath||files[0].name; nome.value=(rel.split('/')[0]||'Pacote de arquivos').slice(0,120); }
    });
    form.addEventListener('submit',async(e)=>{
      e.preventDefault();
      const files=Array.from(input.files||[]);
      if(!files.length){status.textContent='Selecione uma pasta.';return;}
      const permitidas=['.stl','.obj'];
      for(const f of files){ const n=String(f.name||'').toLowerCase(); if(!permitidas.some(x=>n.endsWith(x))){status.textContent='A pasta contém arquivo não permitido: '+f.name+'. Use apenas STL e OBJ.';return;} if(f.size<=0){status.textContent='Arquivo vazio: '+f.name;return;} }
      const total=files.reduce((s,f)=>s+f.size,0);
      botao.disabled=true; prog.style.display='block'; barra.style.width='0%';
      status.textContent='Preparando '+files.length+' arquivo(s) · '+(total/1000000).toFixed(1)+' MB...';
      let pacoteId=0, enviado=0;
      try{
        const meta=files.map((f,indice)=>({indice,nome:f.name,caminho:f.webkitRelativePath||f.name,tamanho:f.size,mime:f.type||''}));
        const r=await fetch('/trabalhos/${trabalho.id}/pacotes/criar',{method:'POST',headers:{'Content-Type':'application/json','x-fluxolab':'1'},body:JSON.stringify({nome_pacote:nome.value||'',setor_origem:origem.value,setor_destino:destino.value,observacao:obs.value||'',arquivos:meta})});
        const d=await r.json().catch(()=>({mensagem:'Resposta inválida.'}));
        if(!r.ok) throw new Error(d.mensagem||'Não foi possível criar o pacote.');
        pacoteId=Number(d.pacote_id||0);
        for(const srv of d.arquivos){
          const f=files[Number(srv.indice)];
          status.textContent='Enviando '+f.name+'...';
          const ri=await fetch('/pacotes/'+pacoteId+'/arquivos/'+srv.id+'/mpu/criar',{method:'POST',headers:{'x-fluxolab':'1'}});
          const di=await ri.json().catch(()=>({mensagem:'Falha ao iniciar upload.'}));
          if(!ri.ok) throw new Error(di.mensagem||'Falha ao iniciar upload.');
          const uploadId=di.uploadId;
          const parts=[];
          try{
            const chunk=${PACOTE_PARTE_BYTES_V321};
            let part=1;
            for(let inicio=0;inicio<f.size;inicio+=chunk){
              const fim=Math.min(f.size,inicio+chunk);
              const blob=f.slice(inicio,fim);
              const rp=await fetch('/pacotes/'+pacoteId+'/arquivos/'+srv.id+'/mpu/parte?uploadId='+encodeURIComponent(uploadId)+'&partNumber='+part,{method:'POST',headers:{'Content-Type':'application/octet-stream','x-fluxolab':'1'},body:blob});
              const dp=await rp.json().catch(()=>({mensagem:'Falha no envio de uma parte.'}));
              if(!rp.ok) throw new Error(dp.mensagem||'Falha no envio de uma parte.');
              parts.push({partNumber:Number(dp.partNumber),etag:dp.etag});
              enviado+=blob.size;
              barra.style.width=Math.min(100,(enviado/total)*100).toFixed(2)+'%';
              status.textContent='Enviando pasta... '+(enviado/1000000).toFixed(1)+' MB de '+(total/1000000).toFixed(1)+' MB';
              part++;
            }
            const rc=await fetch('/pacotes/'+pacoteId+'/arquivos/'+srv.id+'/mpu/concluir?uploadId='+encodeURIComponent(uploadId),{method:'POST',headers:{'Content-Type':'application/json','x-fluxolab':'1'},body:JSON.stringify({parts})});
            const dc=await rc.json().catch(()=>({mensagem:'Falha ao concluir arquivo.'}));
            if(!rc.ok) throw new Error(dc.mensagem||'Falha ao concluir arquivo.');
          }catch(err){
            try{await fetch('/pacotes/'+pacoteId+'/arquivos/'+srv.id+'/mpu/abortar?uploadId='+encodeURIComponent(uploadId),{method:'POST',headers:{'x-fluxolab':'1'}});}catch(_){ }
            throw err;
          }
        }
        window.location.href='/trabalhos/${trabalho.id}/pacotes?ok='+encodeURIComponent('Pasta enviada com sucesso para '+destino.value+'.');
      }catch(err){
        if(pacoteId){ try{await fetch('/pacotes/'+pacoteId+'/cancelar',{method:'POST',headers:{'x-fluxolab':'1'}});}catch(_){ } }
        status.textContent='Falha: '+(err&&err.message?err.message:'erro no upload.'); botao.disabled=false;
      }
    });
  })();
  </script>` : Number(trabalho.entregue||0) ? `<div class="info">Este trabalho já foi entregue. Novos pacotes estão bloqueados.</div>` : "";

  return layout(`<div class="cabecalho-pagina"><div><h2>Pacotes de arquivos</h2><p class="nota">${escapeHtml(trabalho.codigo)} · ${escapeHtml(trabalho.paciente)} · ${escapeHtml(trabalho.municipio)}</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="botao botao-sec" href="/arquivos-digitais">Caixa de arquivos</a><a class="botao botao-sec" href="/trabalhos/${trabalho.id}">← Paciente</a></div></div>
  ${mensagem?`<div class="${tipo}">${escapeHtml(mensagem)}</div>`:""}
  <div class="card" style="margin-bottom:16px"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><strong>Armazenamento usado/reservado: ${escapeHtml(formatarBytesV32(armazenamento.usado_bytes))} / ${escapeHtml(formatarBytesV32(armazenamento.limite_bytes))}</strong><span>${armazenamento.percentual.toFixed(1)}%</span></div><div style="height:11px;background:#e6ecee;border-radius:99px;overflow:hidden;margin-top:8px"><div style="height:100%;width:${armazenamento.percentual.toFixed(2)}%;background:${cor}"></div></div><p class="nota" style="margin-bottom:0">O limite é do laboratório inteiro. Pacotes pendentes reservam espaço para impedir que dois uploads ultrapassem 9 GB ao mesmo tempo.</p></div>
  ${bloqueio}${form}
  <h2>Histórico de pacotes deste paciente</h2>${cards||`<div class="card"><p class="nota">Nenhum pacote enviado ainda.</p></div>`}`,
  "Pacotes de arquivos",usuario);
}

function paginaCaixaArquivosV321(usuario, pacotes, mensagem = "", tipo = "sucesso", avisoPrioridade = "", formularioEnvio = "", arquivosSoltos = []) {
  const linhas = pacotes.map(p => {
    const pronto = p.status === "ATIVO" && Number(p.pendentes||0)===0;
    const destinoMeu = setoresDigitaisUsuarioV321(usuario).includes(String(p.setor_destino));
    return `<tr><td><a href="/trabalhos/${p.trabalho_id}/pacotes"><strong>${escapeHtml(p.paciente)}</strong></a><div class="mini">${escapeHtml(p.codigo)} · ${escapeHtml(p.municipio)}</div></td><td>${escapeHtml(p.nome_pacote)}<div class="mini">${escapeHtml(nomeSetorPacoteV321(p.setor_origem))} → ${escapeHtml(nomeSetorPacoteV321(p.setor_destino))}</div></td><td>${Number(p.total_arquivos||0)}<div class="mini">${escapeHtml(formatarBytesV32(p.tamanho_total_bytes))}</div></td><td>${escapeHtml(p.criado_por_nome||"—")}<div class="mini">${escapeHtml(formatarData(p.criado_em))}</div></td><td>${p.status!=="ATIVO"?`<span class="badge neutro">${escapeHtml(p.status)}</span>`:Number(p.pendentes||0)?`<span class="badge alerta">Upload incompleto</span>`:`<span class="badge ok">Pronto</span>`}${destinoMeu?`<div class="mini">${Number(p.meus_downloads||0)>0?"Você já baixou":"Destinado ao seu setor"}</div>`:""}</td><td>${pronto?`<a class="botao botao-sec" href="/pacotes/${p.id}/download">Baixar pasta</a>`:""}</td></tr>`;
  }).join("");
  return layout(`<div class="cabecalho-pagina"><div><h2>Caixa de arquivos Digital</h2><p class="nota">Pacotes entre CAD/CAM, Fatiamento e gestão. Os mais recentes aparecem primeiro. Todo mundo da área Digital pode enviar e baixar.</p></div><a class="botao botao-sec" href="/digital">← Digital</a></div>${mensagem?`<div class="${tipo}">${escapeHtml(mensagem)}</div>`:""}${avisoPrioridade}${formularioEnvio}<div class="tabela-wrap"><table><thead><tr><th>Paciente</th><th>Pacote / fluxo</th><th>Arquivos</th><th>Enviado por</th><th>Status</th><th></th></tr></thead><tbody>${linhas||`<tr><td colspan="6">Nenhum pacote visível para seu setor.</td></tr>`}</tbody></table></div>${listaEntregasV315(arquivosSoltos, "/arquivos-digitais")}`,"Caixa de arquivos",usuario);
}

async function confirmarRecebimentoPacoteV344(env, usuario, pacote, arquivos) {
  if (!usuarioPodeVerPacoteV321(usuario,pacote)) throw new Error("Acesso negado.");
  const setores=setoresDigitaisUsuarioV321(usuario);
  if (!setores.includes(String(pacote.setor_destino)) && !podeGerenciarAreaV31(usuario,"DIGITAL")) throw new Error("Somente o setor de destino ou a gestão pode confirmar o recebimento.");
  if (pacote.status!=="ATIVO" || Number(pacote.pendentes||0)>0) throw new Error("Pacote ainda não está pronto.");
  const tamanho=arquivos.reduce((s,a)=>s+Number(a.tamanho_bytes||0),0);
  const ja=await env.db.prepare(`SELECT id FROM downloads_pacotes_digitais WHERE pacote_id=? AND usuario_id=? AND tipo_download='PACOTE_COMPLETO' LIMIT 1`).bind(pacote.id,usuario.id).first();
  if (!ja) {
    await env.db.batch([
      env.db.prepare(`INSERT INTO downloads_pacotes_digitais (pacote_id,usuario_id,tipo_download,quantidade_arquivos,tamanho_total_bytes) VALUES (?,?,'PACOTE_COMPLETO',?,?)`).bind(pacote.id,usuario.id,arquivos.length,tamanho),
      env.db.prepare(`INSERT INTO eventos_pacotes_digitais (pacote_id,usuario_id,evento,quantidade_arquivos,tamanho_bytes,detalhe) VALUES (?,?,?,?,?,?)`).bind(pacote.id,usuario.id,'RECEBIMENTO_CONFIRMADO',arquivos.length,tamanho,`${usuario.nome||"Usuário"} confirmou que recebeu e conferiu o pacote completo.`),
      env.db.prepare(`INSERT INTO eventos_pacotes_digitais (pacote_id,usuario_id,evento,quantidade_arquivos,tamanho_bytes,detalhe) VALUES (?,?,?,?,?,?)`).bind(pacote.id,usuario.id,'LIBERADO_EXCLUSAO',arquivos.length,tamanho,'Recebimento confirmado pelo setor de destino; exclusão liberada para este usuário.')
    ]);
  }
}

function respostaZipPacoteV321(env, usuario, pacote, arquivos) {
  return respostaZipPacoteV321ServiceV50(env, usuario, pacote, arquivos, { caminhoRelativoSeguroV321, registrarEventoPacoteV321, nomePacoteSeguroV321, cabecalhosSegurancaV30 });
}
async function deletarChavesR2V321(bucket, chaves) {
  return await deletarChavesR2ServiceV50(bucket, chaves);
}
/* =========================================================
   V3.3.0 · IMPORTACAO DE FOLHAS DE PRODUCAO POR FOTO / PDF
   Fase 1: rascunho + upload privado no R2 + conferencia de arquivos.
   OCR/IA ainda nao e executado nesta versao.
========================================================= */

const TIPOS_ARQUIVO_IMPORTACAO_V330 = Object.freeze({
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".png": "image/png",
  ".webp": "image/webp",
  ".pdf": "application/pdf"
});

function podeImportarFolhasV330(usuario) {
  // V3.4.18: importação é uma função de cadastro, não de produção.
  return isCoord(usuario) || isCadastro(usuario);
}

function extensaoArquivoImportacaoV330(nome) {
  const limpo = String(nome || "").trim().toLowerCase();
  const pos = limpo.lastIndexOf(".");
  if (pos < 0) return "";
  return limpo.slice(pos);
}

function mimeArquivoImportacaoV330(nome) {
  return TIPOS_ARQUIVO_IMPORTACAO_V330[extensaoArquivoImportacaoV330(nome)] || null;
}

function nomeArquivoImportacaoV330(nome) {
  return String(nome || "arquivo")
    .replace(/[\r\n\t]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 220) || "arquivo";
}

function statusImportacaoNomeV330(status) {
  const mapa = {
    RASCUNHO: "Rascunho",
    PROCESSANDO: "Processando",
    REVISAO: "Em revisão",
    PRONTO: "Pronto para confirmar",
    CONFIRMADO: "Confirmado",
    CANCELADO: "Cancelado",
    ERRO: "Erro"
  };
  return mapa[String(status || "").toUpperCase()] || status || "—";
}

function classeImportacaoV330(status) {
  const s = String(status || "").toUpperCase();
  if (["CONFIRMADO", "PRONTO"].includes(s)) return "ok";
  if (["PROCESSANDO", "REVISAO"].includes(s)) return "andamento";
  if (s === "ERRO") return "perigo";
  if (s === "CANCELADO") return "neutro";
  return "alerta";
}

async function obterImportacaoFolhaV330(env, id) {
  return await env.db.prepare(`
    SELECT
      i.*,
      r.numero AS remessa_numero,
      r.data_recebimento AS remessa_recebimento,
      r.data_prevista_entrega AS remessa_previsao,
      r.data_finalizacao AS remessa_finalizacao,
      r.data_entrega_real AS remessa_entrega,
      r.ciclo_digital_id
    FROM importacoes_folhas_producao i
    LEFT JOIN remessas r ON r.id=i.remessa_id
    WHERE i.id=?
    LIMIT 1
  `).bind(Number(id || 0)).first();
}

async function listarImportacoesRemessaV330(env, remessaId) {
  const resultado = await env.db.prepare(`
    SELECT
      i.*,
      u.nome AS criador_nome,
      SUM(CASE WHEN img.id IS NOT NULL AND img.status!='EXCLUIDA' THEN 1 ELSE 0 END) AS total_arquivos,
      COALESCE(SUM(CASE WHEN img.status!='EXCLUIDA' THEN img.tamanho_bytes ELSE 0 END),0) AS total_bytes
    FROM importacoes_folhas_producao i
    LEFT JOIN usuarios u ON u.id=i.criado_por
    LEFT JOIN imagens_importacao_folhas img ON img.importacao_id=i.id
    WHERE i.area='DIGITAL'
      AND i.remessa_id=?
    GROUP BY i.id
    ORDER BY i.id DESC
    LIMIT 30
  `).bind(Number(remessaId || 0)).all();
  return resultado.results || [];
}

async function listarArquivosImportacaoV330(env, importacaoId) {
  const resultado = await env.db.prepare(`
    SELECT *
    FROM imagens_importacao_folhas
    WHERE importacao_id=?
      AND status!='EXCLUIDA'
    ORDER BY ordem ASC, id ASC
  `).bind(Number(importacaoId || 0)).all();
  return resultado.results || [];
}

async function registrarEventoImportacaoV330(env, importacaoId, usuarioId, evento, detalhe = null) {
  await env.db.prepare(`
    INSERT INTO eventos_importacao_folhas (
      importacao_id,usuario_id,evento,detalhe,criado_em
    ) VALUES (?,?,?,?,?)
  `).bind(
    Number(importacaoId),
    usuarioId ? Number(usuarioId) : null,
    String(evento),
    detalhe ? String(detalhe).slice(0, 1000) : null,
    new Date().toISOString()
  ).run();
}

function formatarBytesImportacaoV330(bytes) {
  let n = Number(bytes || 0);
  if (!Number.isFinite(n) || n < 0) n = 0;
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 * 1024 * 1024) return `${(n / (1024 * 1024)).toFixed(1)} MB`;
  return `${(n / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

function paginaNovaImportacaoV330(usuario, remessa, importacoes, mensagem = "", tipo = "sucesso") {
  const id = Number(remessa?.id || 0);
  const fechada = Boolean(remessa?.data_finalizacao || remessa?.data_entrega_real);
  const historico = (importacoes || []).map(item => `
    <tr>
      <td><strong>#${Number(item.id)}</strong></td>
      <td>${escapeHtml(formatarData(item.criado_em))}</td>
      <td>${escapeHtml(item.criador_nome || "—")}</td>
      <td><span class="badge ${classeImportacaoV330(item.status)}">${escapeHtml(statusImportacaoNomeV330(item.status))}</span></td>
      <td>${Number(item.total_arquivos || 0)} · ${escapeHtml(formatarBytesImportacaoV330(item.total_bytes || 0))}</td>
      <td><a class="botao botao-sec" href="/importacoes/${Number(item.id)}">Abrir</a></td>
    </tr>
  `).join("");

  return layout(`
    <div class="cabecalho-pagina">
      <div>
        <h2>Importar pacientes por foto / PDF</h2>
        <p class="nota">${escapeHtml(remessa.municipio)} · Remessa ${String(remessa.numero).padStart(2,"0")}</p>
      </div>
      <a class="botao botao-sec" href="${isCadastro(usuario) ? `/cadastro?ciclo=${Number(remessa.ciclo_digital_id || 0)}` : `/digital?ciclo=${Number(remessa.ciclo_digital_id || 0)}`}">← ${isCadastro(usuario) ? "Cadastro" : "Área Digital"}</a>
    </div>

    ${mensagem ? `<div class="${tipo}">${escapeHtml(mensagem)}</div>` : ""}

    ${fechada ? `<div class="info" style="margin-bottom:16px"><strong>🔒 Remessa encerrada · somente consulta.</strong><br>Não é possível iniciar nova importação ou cadastrar pacientes nesta remessa. Crie uma nova remessa para novos pacientes.</div>` : `
    <div class="card" style="margin-bottom:16px">
      <h3 style="margin-top:0">Nova importação</h3>
      <p class="nota">
        Envie fotos (JPG, PNG ou WEBP) ou PDF. Os arquivos ficam privados no R2 e
        <strong>nenhum paciente é cadastrado nesta etapa</strong>.
      </p>
      <p class="nota">
        Anotações manuscritas pequenas/marginais, como nomes de funcionários escritos à mão,
        serão ignoradas quando o módulo de leitura for conectado.
      </p>

      <div class="form-grid">
        <label class="full">Arquivos da folha
          <input id="folhas-v330-arquivos" type="file"
            accept=".jpg,.jpeg,.png,.webp,.pdf,image/jpeg,image/png,image/webp,application/pdf"
            multiple>
        </label>
        <label class="full">Observação <span class="mini">opcional</span>
          <input id="folhas-v330-observacao" maxlength="500" placeholder="Ex.: folha recebida da cidade em 23/09">
        </label>
        <div class="full" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
          <button type="button" id="folhas-v330-enviar">Criar rascunho e enviar</button>
          <span class="mini">Os arquivos são enviados um por vez para reduzir falhas em lotes grandes.</span>
        </div>
      </div>

      <div id="folhas-v330-status" style="margin-top:12px"></div>
      <div id="folhas-v330-lista" style="margin-top:12px"></div>
    </div>
    `}

    <div class="card">
      <h3 style="margin-top:0">Importações desta remessa</h3>
      <div class="tabela-wrap">
        <table>
          <thead><tr><th>Lote</th><th>Criado em</th><th>Criado por</th><th>Status</th><th>Arquivos</th><th>Ação</th></tr></thead>
          <tbody>${historico || `<tr><td colspan="6">Nenhuma importação criada nesta remessa.</td></tr>`}</tbody>
        </table>
      </div>
    </div>

    <script>
    (()=>{
      const REMESSA_ID=${id};
      const input=document.getElementById('folhas-v330-arquivos');
      const observacao=document.getElementById('folhas-v330-observacao');
      const botao=document.getElementById('folhas-v330-enviar');
      const status=document.getElementById('folhas-v330-status');
      const lista=document.getElementById('folhas-v330-lista');
      if(!input||!botao||!status||!lista) return;

      const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      const permitidas=new Set(['jpg','jpeg','png','webp','pdf']);
      const ext=(nome)=>{const p=String(nome||'').toLowerCase().split('.');return p.length>1?p.pop():'';};
      const fmt=(n)=>{
        n=Number(n||0);
        if(n<1024)return n+' B';
        if(n<1024*1024)return (n/1024).toFixed(1)+' KB';
        return (n/(1024*1024)).toFixed(1)+' MB';
      };
      const sha256=async(file)=>{
        try{
          if(!crypto?.subtle) return '';
          const b=await file.arrayBuffer();
          const h=await crypto.subtle.digest('SHA-256',b);
          return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('');
        }catch(_){return '';}
      };

      const renderArquivos=()=>{
        const arquivos=[...(input.files||[])];
        if(!arquivos.length){lista.innerHTML='';return arquivos;}
        lista.innerHTML='<div class="tabela-wrap"><table><thead><tr><th>#</th><th>Arquivo</th><th>Tipo</th><th>Tamanho</th><th>Status</th></tr></thead><tbody>'+
          arquivos.map((f,i)=>{
            const e=ext(f.name);
            const ok=permitidas.has(e);
            return '<tr id="folhas-v330-linha-'+i+'"><td>'+(i+1)+'</td><td><strong>'+esc(f.name)+'</strong></td><td>'+esc(e.toUpperCase()||'—')+'</td><td>'+esc(fmt(f.size))+'</td><td class="estado">'+(ok?'<span class="badge neutro">Aguardando</span>':'<span class="badge perigo">Tipo não permitido</span>')+'</td></tr>';
          }).join('')+
          '</tbody></table></div>';
        return arquivos;
      };

      input.addEventListener('change',renderArquivos);

      botao.addEventListener('click',async()=>{
        const arquivos=renderArquivos();
        if(!arquivos.length){status.innerHTML='<div class="erro">Selecione pelo menos um arquivo.</div>';return;}
        const invalidos=arquivos.filter(f=>!permitidas.has(ext(f.name)));
        if(invalidos.length){status.innerHTML='<div class="erro">Remova os arquivos de tipo não permitido antes de continuar.</div>';return;}
        if(!confirm('Criar um rascunho com '+arquivos.length+' arquivo(s)? Nenhum paciente será cadastrado ainda.')) return;

        botao.disabled=true; input.disabled=true;
        status.innerHTML='<div class="info"><strong>Criando rascunho…</strong></div>';

        try{
          const inicio=await fetch('/remessas/'+REMESSA_ID+'/importacoes/iniciar',{
            method:'POST',
            headers:{'Content-Type':'application/json','Accept':'application/json'},
            credentials:'same-origin',
            body:JSON.stringify({observacao:String(observacao?.value||'').trim()})
          });
          let dados={}; try{dados=await inicio.json();}catch(_){}
          if(!inicio.ok) throw new Error(dados.mensagem||'Não foi possível criar o rascunho.');
          const importacaoId=Number(dados.importacao_id||0);
          if(!importacaoId) throw new Error('O rascunho foi criado sem identificador.');

          let enviados=0;
          for(let i=0;i<arquivos.length;i++){
            const f=arquivos[i];
            const linha=document.getElementById('folhas-v330-linha-'+i);
            const estado=linha?.querySelector('.estado');
            if(estado) estado.innerHTML='<span class="badge andamento">Preparando…</span>';
            status.innerHTML='<div class="info"><strong>Enviando '+(i+1)+' de '+arquivos.length+':</strong> '+esc(f.name)+'</div>';

            const hash=await sha256(f);
            if(estado) estado.innerHTML='<span class="badge andamento">Enviando…</span>';
            const form=new FormData();
            form.append('arquivo',f,f.name);
            if(hash) form.append('hash_sha256',hash);

            const resp=await fetch('/importacoes/'+importacaoId+'/arquivos',{
              method:'POST',
              credentials:'same-origin',
              headers:{'Accept':'application/json'},
              body:form
            });
            let rd={}; try{rd=await resp.json();}catch(_){}
            if(!resp.ok){
              if(estado) estado.innerHTML='<span class="badge perigo">Falhou</span>';
              throw new Error(rd.mensagem||('Falha ao enviar '+f.name));
            }
            enviados++;
            if(estado) estado.innerHTML='<span class="badge ok">Enviado</span>';
          }

          status.innerHTML='<div class="sucesso"><strong>'+enviados+' arquivo(s) enviado(s).</strong> Abrindo o rascunho para conferência…</div>';
          window.location.href='/importacoes/'+importacaoId+'?ok='+encodeURIComponent(enviados+' arquivo(s) enviado(s) com sucesso.');
        }catch(err){
          status.innerHTML='<div class="erro"><strong>Envio interrompido:</strong> '+esc(err?.message||'Erro inesperado.')+'<br><span class="mini">Arquivos já enviados permanecem no rascunho e podem ser conferidos pela lista de importações.</span></div>';
          botao.disabled=false; input.disabled=false;
        }
      });
    })();
    </script>
  `, "Importar por foto / PDF", usuario);
}

function paginaImportacaoV330(usuario, importacao, arquivos, mensagem = "", tipo = "sucesso", dadosV331 = {arquivos:[],linhas:[],itens:[]}) {
  const ativa = !["CONFIRMADO","CANCELADO"].includes(String(importacao.status || "").toUpperCase());

  const cards = (arquivos || []).map(arquivo => {
    const id = Number(arquivo.id);
    const mime = String(arquivo.mime_type || "");
    const url = `/importacoes/${Number(importacao.id)}/arquivos/${id}/visualizar`;
    const visual = mime.startsWith("image/")
      ? `<a href="${url}" target="_blank" rel="noopener" style="display:block;background:#0f171c;border-radius:10px;overflow:hidden;min-height:180px">
           <img src="${url}" alt="" loading="lazy" style="display:block;width:100%;height:220px;object-fit:contain;background:#0b1115">
         </a>`
      : `<a class="card" href="${url}" target="_blank" rel="noopener" style="display:flex;min-height:180px;align-items:center;justify-content:center;text-decoration:none">
           <div style="text-align:center"><div style="font-size:44px">PDF</div><strong>Abrir documento</strong></div>
         </a>`;

    return `
      <div class="card">
        ${visual}
        <div style="margin-top:10px">
          <strong>${escapeHtml(arquivo.nome_original)}</strong>
          <div class="mini">${escapeHtml(String(arquivo.mime_type || "arquivo"))} · ${escapeHtml(formatarBytesImportacaoV330(arquivo.tamanho_bytes))}</div>
          ${mime === "application/pdf" && !arquivo.processado_em ? `<div class="mini">Quantidade de páginas será identificada na etapa de leitura.</div>` : ""}
        </div>
        ${ativa ? `
          <form method="POST" action="/importacoes/${Number(importacao.id)}/arquivos/${id}/excluir"
            style="margin-top:10px"
            onsubmit="return confirm('Remover este arquivo do rascunho?');">
            <button class="botao-perigo">Remover arquivo</button>
          </form>
        ` : ""}
      </div>
    `;
  }).join("");

  return layout(`
    <div class="cabecalho-pagina">
      <div>
        <h2>Importação #${Number(importacao.id)}</h2>
        <p class="nota">${escapeHtml(importacao.municipio)} · Remessa ${String(importacao.remessa_numero || "").padStart(2,"0")}</p>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <a class="botao botao-sec" href="/remessas/${Number(importacao.remessa_id)}/importar-folhas">← Importações</a>
        <a class="botao botao-sec" href="${isCadastro(usuario) ? `/cadastro?ciclo=${Number(importacao.ciclo_digital_id || 0)}` : `/digital?ciclo=${Number(importacao.ciclo_digital_id || 0)}`}">${isCadastro(usuario) ? "Cadastro" : "Área Digital"}</a>
      </div>
    </div>

    ${mensagem ? `<div class="${tipo}">${escapeHtml(mensagem)}</div>` : ""}

    <div class="card" style="margin-bottom:16px">
      <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap">
        <div>
          <strong>Status</strong><br>
          <span class="badge ${classeImportacaoV330(importacao.status)}">${escapeHtml(statusImportacaoNomeV330(importacao.status))}</span>
        </div>
        <div><span class="mini">Criada em</span><br><strong>${escapeHtml(formatarData(importacao.criado_em))}</strong></div>
        <div><span class="mini">Arquivos</span><br><strong>${Number((arquivos || []).length)}</strong></div>
      </div>
      ${importacao.observacao ? `<p style="margin-bottom:0"><strong>Observação:</strong> ${escapeHtml(importacao.observacao)}</p>` : ""}
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px;margin-bottom:16px">
      ${cards || `<div class="card">Nenhum arquivo ativo neste rascunho.</div>`}
    </div>

    ${painelLeituraV331(importacao, dadosV331, usuario)}
    ${ativa ? `
      <div class="card">
        <h3 style="margin-top:0">Cancelar rascunho</h3>
        <p class="nota">
          O cancelamento remove os arquivos temporários. Os dados de auditoria permanecem. Cancelar não cria trabalhos; os dados de auditoria permanecem disponíveis.
        </p>
        <form method="POST" action="/importacoes/${Number(importacao.id)}/cancelar"
          onsubmit="return confirm('Cancelar esta importação e remover os arquivos do R2?');">
          <button class="botao-perigo">Cancelar importação e remover arquivos</button>
        </form>
      </div>
    ` : ""}
  `, `Importação #${Number(importacao.id)}`, usuario);
}


/* =========================================================
   V3.2.3 · CADASTRO RAPIDO DE PACIENTES EM LOTE
   Objetivo: cadastrar centenas de pacientes dentro da remessa
   com uma unica operacao, sem recarregar a pagina a cada paciente.
========================================================= */

const LIMITE_CADASTRO_RAPIDO_V323 = 300;

function tipoProteseRapidoV323(valor, padrao = "NONE") {
  let v = String(valor ?? "").trim();
  if (!v) v = String(padrao || "NONE");
  v = v.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/\s+/g, " ").trim();
  if (["NONE", "SEM", "SEM TRABALHO", "NENHUM", "NAO", "-"].includes(v)) return "NONE";
  if (["PT", "TOTAL", "PROTESE TOTAL", "PROTESE TOTAL", "DENTADURA"].includes(v)) return "PT";
  if (["PPR", "PPR FLEX", "PPR FLEXIVEL", "FLEX", "FLEXIVEL"].includes(v)) return "PPR";
  return null;
}

async function gerarCodigosTrabalhoLoteV323(env, quantidade) {
  const primeiro = await gerarCodigoTrabalho(env);
  const m = String(primeiro || "").match(/^(.*-)(\d+)$/);
  if (!m) throw new Error("Nao foi possivel gerar a sequencia de codigos dos pacientes.");
  const prefixo = m[1];
  const inicio = Number(m[2]);
  if (!Number.isFinite(inicio) || inicio < 1) throw new Error("Sequencia de codigos invalida.");
  return Array.from({ length: quantidade }, (_, i) => `${prefixo}${String(inicio + i).padStart(3, "0")}`);
}

async function executarBatchResultadosV323(env, statements, tamanho = 60) {
  const resultados = [];
  try {
    for (let i = 0; i < statements.length; i += tamanho) {
      const bloco = statements.slice(i, i + tamanho);
      if (!bloco.length) continue;
      const r = await env.db.batch(bloco);
      resultados.push(...r);
    }
    return resultados;
  } catch (erro) {
    try { erro.resultadosParciaisV323 = resultados; } catch (_) { }
    throw erro;
  }
}

function statementsEstruturaTrabalhoV323(env, trabalhoId, superiorTipo, inferiorTipo, agora) {
  const statements = [];
  const etapas = [];
  const componentes = [];
  for (const [arcada, tipo] of [["SUPERIOR", superiorTipo], ["INFERIOR", inferiorTipo]]) {
    if (tipo === "NONE") continue;
    for (const setor of SETORES) {
      etapas.push([trabalhoId, setor, arcada, tipo, setor === "CAD/CAM" ? agora : null]);
    }
    const comps = tipo === "PT" ? ["BASE", "DENTES", "GENGIVA"] : ["PPR_FLEX"];
    for (const componente of comps) componentes.push([trabalhoId, arcada, componente]);
  }
  if (etapas.length) {
    const valores = etapas.map(() => "(?,?,?,?,?,'AGUARDANDO',NULL,NULL,NULL,NULL,NULL,0)").join(",");
    const args = [];
    for (const [id, setor, arcada, tipo, recebido] of etapas) args.push(id, setor, arcada, tipo, recebido);
    statements.push(env.db.prepare(`
      INSERT INTO etapas (
        trabalho_id,setor,arcada,tipo_protese,recebido_em,status,
        responsavel_id,iniciado_em,concluido_em,conferido_por,conferido_em,retrabalhos
      ) VALUES ${valores}
    `).bind(...args));
  }
  if (componentes.length) {
    const valores = componentes.map(() => "(?,?,?,'AGUARDANDO',NULL)").join(",");
    const args = [];
    for (const [id, arcada, componente] of componentes) args.push(id, arcada, componente);
    statements.push(env.db.prepare(`
      INSERT OR IGNORE INTO componentes_impressao (
        trabalho_id,arcada,componente,status,recebido_em
      ) VALUES ${valores}
    `).bind(...args));
  }
  return statements;
}

async function limparCadastroRapidoParcialV323(env, ids) {
  const limpos = [...new Set((ids || []).map(Number).filter(Number.isFinite).filter(x => x > 0))];
  if (!limpos.length) return;
  for (const id of limpos) {
    try {
      const atividade = await env.db.prepare(`
        SELECT CASE WHEN
          EXISTS(SELECT 1 FROM etapas WHERE trabalho_id=? AND (status!='AGUARDANDO' OR responsavel_id IS NOT NULL OR iniciado_em IS NOT NULL OR concluido_em IS NOT NULL))
          OR EXISTS(SELECT 1 FROM componentes_impressao WHERE trabalho_id=? AND (status!='AGUARDANDO' OR responsavel_id IS NOT NULL OR iniciado_em IS NOT NULL OR concluido_em IS NOT NULL))
          OR EXISTS(SELECT 1 FROM retrabalhos WHERE trabalho_id=? )
          OR EXISTS(SELECT 1 FROM historico WHERE trabalho_id=? AND acao NOT IN ('TRABALHO_CRIADO'))
          THEN 1 ELSE 0 END AS tem_atividade
      `).bind(id,id,id,id).first();
      if (Number(atividade?.tem_atividade || 0)) {
        console.log(`V3.4.4: limpeza compensatória preservou trabalho ${id} porque já possui atividade real.`);
        continue;
      }
      await env.db.batch([
        env.db.prepare(`DELETE FROM componentes_impressao WHERE trabalho_id=?`).bind(id),
        env.db.prepare(`DELETE FROM etapas WHERE trabalho_id=?`).bind(id),
        env.db.prepare(`DELETE FROM historico WHERE trabalho_id=?`).bind(id),
        env.db.prepare(`DELETE FROM auditoria_sistema_v31 WHERE area='DIGITAL' AND acao='CRIAR_PACIENTE_LOTE' AND entidade='TRABALHO' AND registro_id=?`).bind(String(id)),
        env.db.prepare(`DELETE FROM trabalhos WHERE id=? AND NOT EXISTS(SELECT 1 FROM retrabalhos r WHERE r.trabalho_id=trabalhos.id)`).bind(id)
      ]);
    } catch (erro) {
      console.log("Limpeza cadastro rápido V3.4.4:", erro?.message || erro);
    }
  }
}

function blocoCadastroRapidoV323(remessa) {
  const id = Number(remessa?.id || 0);
  if (!id || remessa?.data_finalizacao || remessa?.data_entrega_real) return "";
  return `
    <details style="margin-top:12px;border-top:1px solid #2b3338;padding-top:12px" class="cadastro-rapido-v323">
      <summary style="cursor:pointer;font-weight:900;font-size:16px">⚡ Cadastro rápido / lote</summary>
      <div style="margin-top:12px">
        <div class="info" style="margin-bottom:12px">
          <strong>Modo rápido:</strong> cole uma lista inteira do Excel ou digite um paciente por linha. Se todos tiverem a mesma prótese, escolha o padrão uma vez. Para exceções, cole 3 colunas: <strong>Paciente · Superior · Inferior</strong>.
        </div>
        <div class="form-grid">
          <label>Padrão superior
            <select id="rapido-sup-v323-${id}">
              <option value="NONE">Sem trabalho</option>
              <option value="PT">Prótese total</option>
              <option value="PPR">PPR flex</option>
            </select>
          </label>
          <label>Padrão inferior
            <select id="rapido-inf-v323-${id}">
              <option value="NONE">Sem trabalho</option>
              <option value="PT">Prótese total</option>
              <option value="PPR">PPR flex</option>
            </select>
          </label>
          <label class="full">Pacientes
            <textarea id="rapido-texto-v323-${id}" rows="9" placeholder="JOÃO DA SILVA\nMARIA SOUZA\nCARLOS PEREIRA\tPT\tPPR"></textarea>
          </label>
          <label class="full">Ou carregar lista CSV/TXT <span class="mini">(Excel em colunas ou CSV separado por ;)</span>
            <input id="rapido-arquivo-v323-${id}" type="file" accept=".csv,.txt,text/csv,text/plain">
          </label>
          <div class="full" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
            <button type="button" class="botao botao-sec" id="rapido-validar-v323-${id}">Conferir lista</button>
            <button type="button" id="rapido-enviar-v323-${id}" disabled>Cadastrar lote</button>
            <span class="mini">Até ${LIMITE_CADASTRO_RAPIDO_V323} pacientes por envio.</span>
          </div>
        </div>
        <div id="rapido-status-v323-${id}" style="margin-top:10px"></div>
        <div id="rapido-preview-v323-${id}" style="margin-top:10px"></div>
      </div>
      <script>
      (()=>{
        const REMESSA_ID=${id};
        const LIMITE=${LIMITE_CADASTRO_RAPIDO_V323};
        const sup=document.getElementById('rapido-sup-v323-'+REMESSA_ID);
        const inf=document.getElementById('rapido-inf-v323-'+REMESSA_ID);
        const texto=document.getElementById('rapido-texto-v323-'+REMESSA_ID);
        const arquivo=document.getElementById('rapido-arquivo-v323-'+REMESSA_ID);
        const validarBtn=document.getElementById('rapido-validar-v323-'+REMESSA_ID);
        const enviarBtn=document.getElementById('rapido-enviar-v323-'+REMESSA_ID);
        const status=document.getElementById('rapido-status-v323-'+REMESSA_ID);
        const preview=document.getElementById('rapido-preview-v323-'+REMESSA_ID);
        if(!sup||!inf||!texto||!validarBtn||!enviarBtn) return;

        try{
          const s=localStorage.getItem('fluxolab-v323-sup');
          const i=localStorage.getItem('fluxolab-v323-inf');
          if(['NONE','PT','PPR'].includes(s)) sup.value=s;
          if(['NONE','PT','PPR'].includes(i)) inf.value=i;
        }catch(_){ }
        const guardar=()=>{try{localStorage.setItem('fluxolab-v323-sup',sup.value);localStorage.setItem('fluxolab-v323-inf',inf.value);}catch(_){ }};
        sup.addEventListener('change',guardar); inf.addEventListener('change',guardar);

        const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
        const normalizarTipo=(valor,padrao)=>{
          let v=String(valor??'').trim(); if(!v) v=padrao;
          v=v.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toUpperCase().replace(/\\s+/g,' ').trim();
          if(['NONE','SEM','SEM TRABALHO','NENHUM','NAO','-'].includes(v)) return 'NONE';
          if(['PT','TOTAL','PROTESE TOTAL','DENTADURA'].includes(v)) return 'PT';
          if(['PPR','PPR FLEX','PPR FLEXIVEL','FLEX','FLEXIVEL'].includes(v)) return 'PPR';
          return null;
        };
        const partesLinha=(linha)=>{
          if(linha.includes('\\t')) return linha.split('\\t');
          if(linha.includes(';')) return linha.split(';');
          if(linha.includes('|')) return linha.split('|');
          return [linha];
        };
        const analisar=()=>{
          const linhas=String(texto.value||'').replace(/\\r/g,'').split('\\n');
          const itens=[],erros=[];
          for(let i=0;i<linhas.length;i++){
            const original=linhas[i].trim(); if(!original) continue;
            const p=partesLinha(original).map(x=>String(x||'').trim());
            const nome=String(p[0]||'').trim();
            const cab=nome.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toUpperCase();
            if((cab==='PACIENTE'||cab==='NOME'||cab==='NOME DO PACIENTE')&&itens.length===0) continue;
            const s=normalizarTipo(p.length>1?p[1]:'',sup.value);
            const n=normalizarTipo(p.length>2?p[2]:'',inf.value);
            if(nome.length<2||nome.length>160){erros.push('Linha '+(i+1)+': nome inválido.');continue;}
            if(!s||!n){erros.push('Linha '+(i+1)+': use PT, PPR ou NONE/SEM nas arcadas.');continue;}
            if(s==='NONE'&&n==='NONE'){erros.push('Linha '+(i+1)+': paciente sem trabalho nas duas arcadas.');continue;}
            itens.push({paciente:nome,superior_tipo:s,inferior_tipo:n});
          }
          if(itens.length>LIMITE) erros.push('A lista possui '+itens.length+' pacientes. O limite por envio é '+LIMITE+'.');
          return {itens,erros};
        };
        const render=()=>{
          guardar(); const r=analisar();
          if(r.erros.length){
            status.innerHTML='<div class="erro"><strong>Corrija a lista:</strong><br>'+r.erros.slice(0,10).map(esc).join('<br>')+(r.erros.length>10?'<br>… mais '+(r.erros.length-10)+' erro(s).':'')+'</div>';
            preview.innerHTML=''; enviarBtn.disabled=true; enviarBtn.textContent='Cadastrar lote'; return r;
          }
          if(!r.itens.length){status.innerHTML='<div class="info">Cole ou digite os pacientes acima.</div>';preview.innerHTML='';enviarBtn.disabled=true;enviarBtn.textContent='Cadastrar lote';return r;}
          status.innerHTML='<div class="sucesso"><strong>'+r.itens.length+' paciente(s) pronto(s) para cadastro.</strong> Nenhuma página será recarregada durante o envio.</div>';
          const amostra=r.itens.slice(0,12).map((x,i)=>'<tr><td>'+(i+1)+'</td><td><strong>'+esc(x.paciente)+'</strong></td><td>'+esc(x.superior_tipo)+'</td><td>'+esc(x.inferior_tipo)+'</td></tr>').join('');
          preview.innerHTML='<div class="tabela-wrap"><table><thead><tr><th>#</th><th>Paciente</th><th>Superior</th><th>Inferior</th></tr></thead><tbody>'+amostra+'</tbody></table></div>'+(r.itens.length>12?'<div class="mini" style="margin-top:6px">Prévia dos 12 primeiros · '+(r.itens.length-12)+' restante(s).</div>':'');
          enviarBtn.disabled=false; enviarBtn.textContent='Cadastrar '+r.itens.length+' paciente(s)'; return r;
        };
        validarBtn.addEventListener('click',render);
        texto.addEventListener('input',()=>{enviarBtn.disabled=true;status.innerHTML='';preview.innerHTML='';});
        if(arquivo) arquivo.addEventListener('change',async()=>{const f=arquivo.files&&arquivo.files[0];if(!f)return;try{texto.value=await f.text();render();}catch(_){status.innerHTML='<div class="erro">Não foi possível ler esse arquivo.</div>';}});
        enviarBtn.addEventListener('click',async()=>{
          const r=render(); if(r.erros.length||!r.itens.length) return;
          if(!confirm('Cadastrar '+r.itens.length+' paciente(s) nesta remessa?')) return;
          enviarBtn.disabled=true; validarBtn.disabled=true;
          const antigo=enviarBtn.textContent; enviarBtn.textContent='Cadastrando…';
          status.innerHTML='<div class="info"><strong>Cadastrando '+r.itens.length+' paciente(s)…</strong> Aguarde esta única operação.</div>';
          try{
            const resp=await fetch('/remessas/'+REMESSA_ID+'/pacientes-lote',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},credentials:'same-origin',body:JSON.stringify({pacientes:r.itens})});
            let dados={}; try{dados=await resp.json();}catch(_){ }
            if(!resp.ok) throw new Error(dados.mensagem||'Falha ao cadastrar lote.');
            const qtd=Number(dados.quantidade||r.itens.length);
            const qtdProteses=Number(dados.proteses||r.itens.reduce((s,p)=>s+([p.superior_tipo,p.inferior_tipo].filter(v=>['PT','PPR'].includes(String(v||'').toUpperCase())).length),0));
            status.innerHTML='<div class="sucesso"><strong>'+qtd+' paciente(s) e '+qtdProteses+' prótese(s) cadastrados.</strong> Você pode colar o próximo lote sem recarregar a página.</div>';
            texto.value=''; preview.innerHTML=''; enviarBtn.textContent='Cadastrar lote'; enviarBtn.disabled=true;
            const resumo=document.getElementById('resumo-remessa-v323-'+REMESSA_ID);
            const pct=document.getElementById('percentual-remessa-v323-'+REMESSA_ID);
            const barra=document.getElementById('barra-remessa-v323-'+REMESSA_ID);
            const badgeProteses=document.getElementById('proteses-remessa-v325-'+REMESSA_ID);
            if(resumo){const p=Number(resumo.dataset.prontos||0),t=Number(resumo.dataset.total||0)+qtd;resumo.dataset.total=String(t);resumo.textContent=p+'/'+t;const per=t?Math.round((p/t)*100):0;if(pct)pct.textContent='pacientes prontos · '+per+'%';if(barra)barra.style.width=per+'%';}
            if(badgeProteses){const novoTotal=Number(badgeProteses.dataset.total||0)+qtdProteses;badgeProteses.dataset.total=String(novoTotal);badgeProteses.textContent=novoTotal+' prótese(s) cadastrada(s)';}
          }catch(err){status.innerHTML='<div class="erro"><strong>Cadastro não concluído:</strong> '+esc(err&&err.message?err.message:'Erro inesperado.')+'</div>';enviarBtn.disabled=false;enviarBtn.textContent=antigo;}
          finally{validarBtn.disabled=false;}
        });
      })();
      </script>
    </details>
  `;
}


/* =========================================================
   V3.2.2 · DESIGNACAO EM LOTE DIGITAL
========================================================= */

function setorDigitalValidoV322(setor) {
  return SETORES.includes(String(setor || "").toUpperCase());
}

async function listarFuncionariosSetorDigitalV322(env, setor) { return await listarFuncionariosSetorDigitalV322DomainV45(env, setor); }

async function listarCiclosDesignacaoDigitalV322(env) {
  return await listarCiclosDigitaisV311(env);
}

async function listarRemessasDesignacaoDigitalV322(env, cicloId) { return await listarRemessasDesignacaoDigitalV322DomainV45(env, cicloId); }

async function listarTrabalhosDesignacaoDigitalV322(env, setor, cicloId, remessaId = 0, busca = "") { return await listarTrabalhosDesignacaoDigitalV322DomainV45(env, setor, cicloId, remessaId, busca, { setorDigitalValidoV322 }); }

function resumoDesignacaoAtualV322(item) {
  const nomes = String(item.responsaveis || "").split(",").map(x => x.trim()).filter(Boolean);
  if (!nomes.length && Number(item.andamento || 0) > 0) {
    return `<span class="badge alerta">Em andamento · responsável não identificado</span>`;
  }
  if (!nomes.length) return `<span class="badge neutro">Sem designação</span>`;
  if (nomes.length === 1) return `<span class="badge andamento">${escapeHtml(nomes[0])}</span>`;
  return `<span class="badge alerta">Múltiplos: ${escapeHtml(nomes.join(" / "))}</span>`;
}

function trabalhoJaDesignadoV3412(item) {
  const nomes = String(item?.responsaveis || "").split(",").map(x => x.trim()).filter(Boolean);
  return nomes.length > 0 || Number(item?.andamento || 0) > 0;
}

function paginaDesignacoesDigitaisV322(usuario, dados, mensagem = "", tipo = "sucesso") {
  const setor = dados.setor;
  const ciclo = dados.ciclo;
  const remessas = dados.remessas || [];
  const funcionarios = dados.funcionarios || [];
  const trabalhos = dados.trabalhos || [];

  const opcoesSetor = SETORES.map(s => `<option value="${escapeHtml(s)}" ${s===setor?"selected":""}>${escapeHtml(s)}</option>`).join("");
  const opcoesCiclo = (dados.ciclos || []).map(c => `<option value="${c.id}" ${Number(c.id)===Number(ciclo?.id||0)?"selected":""}>${escapeHtml(c.nome)}${Number(c.ativo)?" · ATIVO":""}</option>`).join("");
  const opcoesRemessa = `<option value="">Todas as remessas</option>` + remessas.map(r => `<option value="${r.id}" ${Number(r.id)===Number(dados.remessaId||0)?"selected":""}>${escapeHtml(r.municipio)} · Remessa ${String(r.numero).padStart(2,"0")}</option>`).join("");
  const opcoesFuncionario = funcionarios.map(f => `<option value="${f.id}">${escapeHtml(f.nome)}</option>`).join("");

  const linhaDesignacaoV3412 = (t, grupo) => {
    const andamento = Number(t.andamento || 0);
    const bloqueado = grupo === "JA" ? !t.pode_redesignar : !t.pode_designar;
    const classeGrupo = grupo === "SEM" ? "chk-sem-designacao-v3412" : "chk-ja-designado-v3412";
    const tituloSelecao = grupo === "JA"
      ? (bloqueado ? "Trabalho já iniciado: não pode ser redesignado." : "Pode ser redesignado porque ainda não foi iniciado.")
      : "Selecionar para designação";
    return `<tr>
      <td><input class="chk-designacao-v322 ${classeGrupo}" type="checkbox" name="trabalho_id" value="${t.id}" ${bloqueado?"disabled":""} title="${escapeHtml(tituloSelecao)}"></td>
      <td><strong>${escapeHtml(t.paciente)}</strong><div class="mini">${escapeHtml(t.codigo)} · ${escapeHtml(t.municipio)}</div></td>
      <td>Remessa ${String(t.remessa_numero||0).padStart(2,"0")}<div class="mini">Entrega ${escapeHtml(formatarDataCurta(t.data_prevista_entrega))}</div></td>
      <td>${resumoDesignacaoAtualV322(t)}</td>
      <td><span class="mini">Aguardando: ${Number(t.aguardando||0)} · disponíveis agora: ${Number(t.disponiveis||0)}</span>${andamento?`<div><span class="badge alerta">${andamento} em andamento</span></div>`:""}</td>
      <td><a class="botao botao-sec" href="/trabalhos/${t.id}">Abrir</a></td>
    </tr>`;
  };

  const trabalhosJaDesignados = trabalhos.filter(trabalhoJaDesignadoV3412);
  const trabalhosSemDesignacao = trabalhos.filter(t => !trabalhoJaDesignadoV3412(t) && Number(t.aguardando || 0) > 0);
  const linhasSemDesignacao = trabalhosSemDesignacao.map(t => linhaDesignacaoV3412(t, "SEM")).join("");
  const linhasJaDesignados = trabalhosJaDesignados.map(t => linhaDesignacaoV3412(t, "JA")).join("");

  return layout(`
    <div class="cabecalho-pagina">
      <div><h2>Designar trabalhos em lote</h2><p class="nota">Área Digital · trabalhos separados entre sem designação e já designados. Escolha setor, funcionário e vários pacientes. Somente etapas ainda aguardando são alteradas.</p></div>
      <a class="botao botao-sec" href="/digital${ciclo?`?ciclo=${ciclo.id}`:""}">← Digital</a>
    </div>
    ${mensagem ? `<div class="${tipo}">${escapeHtml(mensagem)}</div>` : ""}

    <div class="card" style="margin-bottom:16px">
      <form method="GET" action="/digital/designacoes">
        <div class="form-grid">
          <label>Setor<select name="setor" onchange="this.form.submit()">${opcoesSetor}</select></label>
          <label>Ciclo<select name="ciclo" onchange="this.form.submit()">${opcoesCiclo}</select></label>
          <label>Remessa<select name="remessa">${opcoesRemessa}</select></label>
          <label>Buscar<input name="q" value="${escapeHtml(dados.busca||"")}" placeholder="Paciente, código ou município"></label>
          <div style="align-self:end"><button>Filtrar</button></div>
        </div>
      </form>
    </div>

    ${!funcionarios.length ? `<div class="erro">Nenhum funcionário ativo está cadastrado no setor ${escapeHtml(setor)}.</div>` : ""}

    <form method="POST" action="/digital/designacoes/lote" id="form-designacao-v322">
      <input type="hidden" name="setor" value="${escapeHtml(setor)}">
      <input type="hidden" name="ciclo" value="${Number(ciclo?.id||0)}">
      <input type="hidden" name="remessa" value="${Number(dados.remessaId||0)}">
      <input type="hidden" name="q" value="${escapeHtml(dados.busca||"")}">
      <div class="card" style="margin-bottom:12px">
        <div class="form-grid">
          <label>Funcionário do ${escapeHtml(setor)}
            <select name="funcionario_id" ${funcionarios.length?"required":"disabled"}>
              <option value="">Selecione</option>${opcoesFuncionario}
            </select>
          </label>
          <label>Motivo / observação <span class="mini">opcional</span><input name="motivo" maxlength="300" placeholder="Ex.: divisão da carga da manhã"></label>
          <div class="full" style="display:flex;gap:8px;flex-wrap:wrap">
            <button type="submit" name="acao" value="ATRIBUIR" ${funcionarios.length?"":"disabled"}>Designar livres</button>
            <button type="submit" name="acao" value="REDESIGNAR" ${funcionarios.length?"":"disabled"}>↻ Redesignar para outro funcionário</button>
            <button class="botao-sec" type="submit" name="acao" value="REMOVER">Remover designação</button>
          </div>
          <div class="full mini"><strong id="contador-designacao-v322">0</strong> paciente(s) selecionado(s). <strong>Redesignação só é permitida antes do início do trabalho.</strong> Qualquer item já em andamento fica bloqueado.</div>
        </div>
      </div>

      <div class="card" style="padding:0;overflow:hidden;margin-bottom:14px;border-color:rgba(21,154,156,.55)">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 16px;background:rgba(21,154,156,.11);border-bottom:1px solid var(--borda);flex-wrap:wrap">
          <div><strong style="font-size:15px">○ Sem designação</strong><div class="mini">Pacientes ainda livres para distribuição neste setor.</div></div>
          <span class="badge neutro">${trabalhosSemDesignacao.length} paciente(s)</span>
        </div>
        <div class="tabela-wrap">
          <table>
            <thead><tr><th><input type="checkbox" id="todos-sem-designacao-v3412" title="Selecionar todos sem designação"></th><th>Paciente</th><th>Remessa</th><th>Responsável</th><th>Situação no setor</th><th></th></tr></thead>
            <tbody>${linhasSemDesignacao || `<tr><td colspan="6"><strong>Nenhum trabalho sem designação neste filtro.</strong></td></tr>`}</tbody>
          </table>
        </div>
      </div>

      <div class="card" style="padding:0;overflow:hidden;margin-bottom:12px">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 16px;background:rgba(23,92,211,.10);border-bottom:1px solid var(--borda);flex-wrap:wrap">
          <div><strong style="font-size:15px">✓ Já designados</strong><div class="mini">Pacientes com responsável. Os ainda não iniciados podem ser selecionados e redesignados para outro funcionário.</div></div>
          <span class="badge andamento">${trabalhosJaDesignados.length} paciente(s)</span>
        </div>
        <div class="tabela-wrap">
          <table>
            <thead><tr><th><input type="checkbox" id="todos-ja-designados-v3412" title="Selecionar todos já designados"></th><th>Paciente</th><th>Remessa</th><th>Responsável</th><th>Situação no setor</th><th></th></tr></thead>
            <tbody>${linhasJaDesignados || `<tr><td colspan="6"><strong>Nenhum trabalho já designado neste filtro.</strong></td></tr>`}</tbody>
          </table>
        </div>
      </div>
    </form>

    <script>
      (()=>{
        const todosSem=document.getElementById('todos-sem-designacao-v3412');
        const todosJa=document.getElementById('todos-ja-designados-v3412');
        const caixas=[...document.querySelectorAll('.chk-designacao-v322:not(:disabled)')];
        const caixasSem=[...document.querySelectorAll('.chk-sem-designacao-v3412:not(:disabled)')];
        const caixasJa=[...document.querySelectorAll('.chk-ja-designado-v3412:not(:disabled)')];
        const contador=document.getElementById('contador-designacao-v322');
        const marcarGrupo=(caixasGrupo,controle)=>{if(!controle)return;controle.addEventListener('change',()=>{caixasGrupo.forEach(c=>c.checked=controle.checked);atualizar();});};
        const atualizar=()=>{
          const n=caixas.filter(c=>c.checked).length;
          if(contador)contador.textContent=String(n);
          if(todosSem)todosSem.checked=caixasSem.length>0&&caixasSem.every(c=>c.checked);
          if(todosJa)todosJa.checked=caixasJa.length>0&&caixasJa.every(c=>c.checked);
        };
        marcarGrupo(caixasSem,todosSem);
        marcarGrupo(caixasJa,todosJa);
        caixas.forEach(c=>c.addEventListener('change',atualizar));
        atualizar();
      })();
    </script>
  `, "Designar trabalhos", usuario);
}

async function aplicarDesignacaoLoteDigitalV322(env, usuario, setor, funcionarioId, trabalhoIds, acao, motivo="") {
  if (!podeGerenciarAreaV31(usuario, "DIGITAL")) throw new Error("Apenas a gestão Digital pode designar trabalhos.");
  if (!setorDigitalValidoV322(setor)) throw new Error("Setor Digital inválido.");
  const ids=[...new Set((trabalhoIds||[]).map(Number).filter(n=>Number.isInteger(n)&&n>0))].slice(0,500);
  if(!ids.length) throw new Error("Selecione pelo menos um paciente.");
  const remover=acao==="REMOVER";
  const redesignar=acao==="REDESIGNAR";
  const atribuir=acao==="ATRIBUIR";
  if(!["ATRIBUIR","REDESIGNAR","REMOVER"].includes(acao)) throw new Error("Ação de designação inválida.");

  let funcionario=null;
  if(!remover){
    funcionario=await env.db.prepare(`
      SELECT u.id,u.nome
      FROM usuarios u
      WHERE u.id=? AND u.perfil='FUNCIONARIO' AND u.ativo=1 AND u.excluido=0
        AND EXISTS (SELECT 1 FROM usuario_areas ua WHERE ua.usuario_id=u.id AND ua.area='DIGITAL' AND ua.ativo=1)
        AND EXISTS (SELECT 1 FROM usuario_setores us WHERE us.usuario_id=u.id AND us.area='DIGITAL' AND us.setor=? AND us.ativo=1)
      LIMIT 1
    `).bind(funcionarioId,setor).first();
    if(!funcionario) throw new Error("O funcionário selecionado não está ativo neste setor.");
  }

  const agora=new Date().toISOString();
  let pacientesAlterados=0, unidadesAlteradas=0, ignorados=0;
  for(const trabalhoId of ids){
    const trabalho=await env.db.prepare(`SELECT id,codigo,paciente,entregue FROM trabalhos WHERE id=? AND excluido=0 LIMIT 1`).bind(trabalhoId).first();
    if(!trabalho||Number(trabalho.entregue)){ignorados++;continue;}

    const estado = setor === "IMPRESSAO"
      ? await env.db.prepare(`
          SELECT
            SUM(CASE WHEN status='AGUARDANDO' THEN 1 ELSE 0 END) AS aguardando,
            SUM(CASE WHEN status='AGUARDANDO' AND responsavel_id IS NOT NULL THEN 1 ELSE 0 END) AS atribuidas,
            SUM(CASE WHEN status='EM_ANDAMENTO' THEN 1 ELSE 0 END) AS andamento,
            GROUP_CONCAT(DISTINCT CASE WHEN status='AGUARDANDO' AND responsavel_id IS NOT NULL THEN CAST(responsavel_id AS TEXT) END) AS ids
          FROM componentes_impressao
          WHERE trabalho_id=?
        `).bind(trabalhoId).first()
      : await env.db.prepare(`
          SELECT
            SUM(CASE WHEN status='AGUARDANDO' THEN 1 ELSE 0 END) AS aguardando,
            SUM(CASE WHEN status='AGUARDANDO' AND responsavel_id IS NOT NULL THEN 1 ELSE 0 END) AS atribuidas,
            SUM(CASE WHEN status='EM_ANDAMENTO' THEN 1 ELSE 0 END) AS andamento,
            GROUP_CONCAT(DISTINCT CASE WHEN status='AGUARDANDO' AND responsavel_id IS NOT NULL THEN CAST(responsavel_id AS TEXT) END) AS ids
          FROM etapas
          WHERE trabalho_id=? AND setor=?
        `).bind(trabalhoId,setor).first();

    const aguardando=Number(estado?.aguardando||0);
    const atribuidas=Number(estado?.atribuidas||0);
    const andamento=Number(estado?.andamento||0);
    if(!aguardando){ignorados++;continue;}
    if(redesignar && (andamento>0 || atribuidas===0)){ignorados++;continue;}
    if(atribuir && atribuidas>0){ignorados++;continue;}

    let alteradas=0;
    if(setor==="IMPRESSAO"){
      if(remover){
        const rc=await env.db.prepare(`UPDATE componentes_impressao SET responsavel_id=NULL,designado_por=NULL,designado_em=NULL WHERE trabalho_id=? AND status='AGUARDANDO' AND responsavel_id IS NOT NULL`).bind(trabalhoId).run();
        await env.db.prepare(`UPDATE etapas SET responsavel_id=NULL,designado_por=NULL,designado_em=NULL WHERE trabalho_id=? AND setor='IMPRESSAO' AND status='AGUARDANDO' AND responsavel_id IS NOT NULL`).bind(trabalhoId).run();
        alteradas=Number(rc.meta?.changes||0);
      }else if(redesignar){
        const rc=await env.db.prepare(`UPDATE componentes_impressao SET responsavel_id=?,designado_por=?,designado_em=? WHERE trabalho_id=? AND status='AGUARDANDO'`).bind(funcionario.id,usuario.id,agora,trabalhoId).run();
        await env.db.prepare(`UPDATE etapas SET responsavel_id=?,designado_por=?,designado_em=? WHERE trabalho_id=? AND setor='IMPRESSAO' AND status='AGUARDANDO'`).bind(funcionario.id,usuario.id,agora,trabalhoId).run();
        alteradas=Number(rc.meta?.changes||0);
      }else{
        const rc=await env.db.prepare(`UPDATE componentes_impressao SET responsavel_id=?,designado_por=?,designado_em=? WHERE trabalho_id=? AND status='AGUARDANDO' AND responsavel_id IS NULL`).bind(funcionario.id,usuario.id,agora,trabalhoId).run();
        await env.db.prepare(`UPDATE etapas SET responsavel_id=?,designado_por=?,designado_em=? WHERE trabalho_id=? AND setor='IMPRESSAO' AND status='AGUARDANDO' AND responsavel_id IS NULL`).bind(funcionario.id,usuario.id,agora,trabalhoId).run();
        alteradas=Number(rc.meta?.changes||0);
      }
    }else{
      const rc=remover
        ? await env.db.prepare(`UPDATE etapas SET responsavel_id=NULL,designado_por=NULL,designado_em=NULL WHERE trabalho_id=? AND setor=? AND status='AGUARDANDO' AND responsavel_id IS NOT NULL`).bind(trabalhoId,setor).run()
        : redesignar
          ? await env.db.prepare(`UPDATE etapas SET responsavel_id=?,designado_por=?,designado_em=? WHERE trabalho_id=? AND setor=? AND status='AGUARDANDO'`).bind(funcionario.id,usuario.id,agora,trabalhoId,setor).run()
          : await env.db.prepare(`UPDATE etapas SET responsavel_id=?,designado_por=?,designado_em=? WHERE trabalho_id=? AND setor=? AND status='AGUARDANDO' AND responsavel_id IS NULL`).bind(funcionario.id,usuario.id,agora,trabalhoId,setor).run();
      alteradas=Number(rc.meta?.changes||0);
    }

    if(alteradas>0){
      pacientesAlterados++;unidadesAlteradas+=alteradas;
      const detalhe=remover
        ? `Designação pendente removida em ${setor}.${motivo?` Motivo: ${motivo}`:""}`
        : redesignar
          ? `${setor} redesignado para ${funcionario.nome} antes do início.${motivo?` Motivo: ${motivo}`:""}`
          : `${setor} designado para ${funcionario.nome} em lote.${motivo?` Motivo: ${motivo}`:""}`;
      const acaoHist=remover?"DESIGNACAO_REMOVIDA":redesignar?"REDESIGNACAO_LOTE":"DESIGNACAO_LOTE";
      const acaoAud=remover?"REMOVER_DESIGNACAO_LOTE":redesignar?"REDESIGNAR_LOTE":"DESIGNAR_LOTE";
      await registrarHistorico(env,trabalhoId,usuario.id,acaoHist,detalhe);
      await registrarAuditoriaSistemaV31(env,usuario.id,"DIGITAL",acaoAud,"TRABALHO",trabalhoId,`responsavel_${setor}`,estado?.ids||null,remover?null:String(funcionario.id),motivo||null);
    }else ignorados++;
  }
  return {pacientesAlterados,unidadesAlteradas,ignorados};
}

