async function limparTemporariosV331(env){
  if(!env.IMPORT_BUCKET||!env.db)return;
  const limite=new Date(Date.now()-7*86400000).toISOString();
  const r=await env.db.prepare(`SELECT DISTINCT i.id FROM importacoes_folhas_producao i JOIN imagens_importacao_folhas a ON a.importacao_id=i.id WHERE a.status!='EXCLUIDA' AND (i.status IN ('CONFIRMADO','CANCELADO') OR julianday(i.atualizado_em)<julianday(?)) ORDER BY i.atualizado_em ASC LIMIT 1`).bind(limite).all();
  for(const row of r.results||[]){
    let token;
    try{
      token=await bloquearFolhaV331(env,row.id);
      const imp=await env.db.prepare('SELECT * FROM importacoes_folhas_producao WHERE id=?').bind(row.id).first();
      if(!['CONFIRMADO','CANCELADO'].includes(imp.status)&&Date.parse(imp.atualizado_em)>Date.parse(limite))continue;
      const arquivos=await listarArquivosImportacaoV330(env,row.id);let n=0;
      for(const a of arquivos.slice(0,20)){
        if(!a.chave_r2.startsWith(`importacoes/${row.id}/`))continue;
        await env.IMPORT_BUCKET.delete(a.chave_r2);
        await env.db.prepare("UPDATE imagens_importacao_folhas SET status='EXCLUIDA',erro='Arquivo temporário removido por encerramento ou 7 dias sem alterações.' WHERE id=?").bind(a.id).run();n++;
      }
      if(n)await registrarEventoImportacaoV330(env,row.id,null,'REVISAO_SALVA',`Limpeza de temporários: ${n} arquivo(s) removido(s). Dados estruturados preservados.`);
    }catch{/* Próxima execução tenta novamente. Não registra dados pessoais. */}
    finally{if(token)await liberarFolhaV331(env,row.id,token);}
  }
}

