const CATEGORIAS_POPUP_V318 = [
  ["AVISO_ADMINISTRATIVO", "Aviso administrativo"],
  ["COMUNICADO_GERAL", "Comunicado geral"],
  ["ATENCAO", "Atenção"],
  ["INFORMACAO_IMPORTANTE", "Informação importante"],
  ["RECONHECIMENTO", "Reconhecimento"],
  ["META_ATINGIDA", "Meta atingida"]
];
const PRIORIDADES_POPUP_V318 = [
  ["BAIXA", "Baixa"], ["NORMAL", "Normal"], ["ALTA", "Alta"]
];
const DESTINOS_META_POPUP_V318 = [
  ["INDIVIDUAL", "Somente o colaborador"],
  ["SETOR", "Colaborador e setor"],
  ["EQUIPE", "Colaborador e equipe inteira"]
];

function rotuloCategoriaPopupV318(v) {
  const item = CATEGORIAS_POPUP_V318.find(x => x[0] === String(v || "").toUpperCase());
  return item ? item[1] : "Comunicado geral";
}
function rotuloPrioridadePopupV318(v) {
  const item = PRIORIDADES_POPUP_V318.find(x => x[0] === String(v || "").toUpperCase());
  return item ? item[1] : "Normal";
}
function categoriaPopupValidaV318(v) {
  const s = String(v || "").toUpperCase();
  return CATEGORIAS_POPUP_V318.some(x => x[0] === s) ? s : "COMUNICADO_GERAL";
}
function prioridadePopupValidaV318(v) {
  const s = String(v || "").toUpperCase();
  return PRIORIDADES_POPUP_V318.some(x => x[0] === s) ? s : "NORMAL";
}
function exigeConfirmacaoPopupV318(prioridade) {
  return prioridadePopupValidaV318(prioridade) === "ALTA" ? 1 : 0;
}
function erroMigracaoPopupV318(erro) {
  return /no such table:\s*(mensagens_popup_v318|mensagens_popup_destinos_v318|mensagens_popup_metas_v318|configuracao_popup_meta_v318|metas_pessoais_lideranca_v318)/i
    .test(String(erro?.message || erro));
}
function agoraIsoV318() { return new Date().toISOString(); }
function diaLocalV318() { return hojeNegocioV344(); }
function chaveSetorPopupV318(area, setor) {
  return `${String(area || "").toUpperCase()}:${String(setor || "").toUpperCase()}`;
}
function podeEnviarPopupV318(usuario) { return isCoord(usuario); }
function podeVerRankingCompletoV318(usuario) { return isCoord(usuario) || isGerencia(usuario); }

function linkLiderancaV318(usuario) {
  if (!usuario || isCadastro(usuario)) return "";
  const area = isGerencia(usuario) ? areaGerenciaV31(usuario) : "";
  const q = area ? `?area=${encodeURIComponent(area)}` : "";
  return `<a href="/lideranca-producao${q}"><span class="nav-icone">🏆</span><span>Liderança da produção</span></a>`;
}
