      await env.db.prepare(`UPDATE faixas_convencionais SET municipio=?,uf=? WHERE id IN (SELECT faixa_id FROM ciclo_municipio_faixas WHERE ciclo_municipio_id=?)`).bind(municipio, uf || null, cidadeId).run();
      await env.db.prepare(`UPDATE trabalhos_convencionais SET municipio=?,uf=? WHERE id IN (SELECT trabalho_id FROM ciclo_municipio_trabalhos WHERE ciclo_municipio_id=?) AND excluido=0`).bind(municipio, uf || null, cidadeId).run();
