      await registrarAuditoriaSistemaV31(env, usuario.id, "CONVENCIONAL", "CORRIGIR_ENTREGA_CIDADE", "CICLO_MUNICIPIO", cidadeId, "data_entrega", antes.data_entrega, entregaInformada, motivo);
