    if (cidade.data_entrega) return redirect(`/convencional?ciclo=${base.ciclo_id}&erro=${encodeURIComponent("A entrega desta cidade já foi registrada.")}`);
    await env.db.prepare(`INSERT INTO entregas_municipios_convencionais (ciclo_municipio_id,data_entrega,registrado_por) VALUES (?,?,?)`).bind(id, data, usuario.id).run();
    await registrarAuditoriaSistemaV31(env, usuario.id, "CONVENCIONAL", "ENTREGA_CIDADE", "CICLO_MUNICIPIO", id, "data_entrega", null, data, null);
