    const fimAtualDate = new Date(`${f.fim}T12:00:00-03:00`);
    const duracao = Math.max(1, Math.round((fimAtualDate-inicioAnteriorDate)/86400000)+1);
    const fimAnteriorDate = new Date(inicioAnteriorDate.getTime()-86400000);
    const inicioAnterior = new Date(fimAnteriorDate.getTime()-(duracao-1)*86400000).toISOString().slice(0,10);
    const fimAnterior = fimAnteriorDate.toISOString().slice(0,10);
