/* =========================================================
   V3.6 · CONSUMO DE MATERIAIS DIGITAL
   - Catálogo de resinas, glaze e outros materiais.
   - Consumo vinculado à remessa para calcular pacientes e próteses/arcadas.
   - Rendimento por embalagem, quantidade física por prótese e custo médio opcional.
   - Lançamentos anulados permanecem no banco para auditoria e não entram nos cálculos.
========================================================= */

function categoriaMaterialV36(valor) {
  const v = String(valor || "OUTRO").trim().toUpperCase();
  return ["RESINA", "GLAZE", "LAVAGEM", "GLICERINA", "OUTRO"].includes(v) ? v : "OUTRO";
}

function rotuloCategoriaMaterialV36(valor) {
  return ({RESINA:"Resina", GLAZE:"Glaze", LAVAGEM:"Lavagem", GLICERINA:"Glicerina", OUTRO:"Outro"})[categoriaMaterialV36(valor)] || "Outro";
}

function unidadeMedidaMaterialV36(valor) {
  const v = String(valor || "").trim().toLowerCase();
  return ["g", "kg", "ml", "l", "un"].includes(v) ? v : "";
}

function numeroMaterialV36(valor, casas = 2) {
  const n = Number(valor || 0);
  return new Intl.NumberFormat("pt-BR", {minimumFractionDigits:0, maximumFractionDigits:casas}).format(Number.isFinite(n) ? n : 0);
}

function hojeSaoPauloV36() {
  return new Intl.DateTimeFormat("en-CA", {timeZone:"America/Sao_Paulo", year:"numeric", month:"2-digit", day:"2-digit"}).format(new Date());
}

function arcadaAtivaMaterialV36(tipo) {
  const v = String(tipo || "").trim().toUpperCase();
  return !["", "NONE", "NENHUMA", "SEM_TRABALHO"].includes(v);
}

async function opcoesMateriaisV36(env) {
  const [materiaisR, remessasR, municipiosR] = await Promise.all([
    env.db.prepare(`SELECT id,nome,categoria,embalagem,conteudo_embalagem,unidade_medida,custo_embalagem_centavos,ativo FROM materiais_v36 ORDER BY ativo DESC,nome COLLATE NOCASE`).all(),
    env.db.prepare(`
      SELECT r.id,r.municipio,r.numero,r.data_recebimento,r.data_entrega_real
      FROM remessas r
      WHERE r.ciclo_digital_id IS NOT NULL
         OR EXISTS (SELECT 1 FROM trabalhos t WHERE t.remessa_id=r.id AND t.excluido=0)
      ORDER BY r.municipio COLLATE NOCASE,r.numero DESC,r.id DESC
    `).all(),
    env.db.prepare(`
      SELECT municipio FROM (
        SELECT trim(municipio) AS municipio FROM remessas WHERE trim(COALESCE(municipio,''))<>''
        UNION
        SELECT trim(municipio) AS municipio FROM trabalhos WHERE excluido=0 AND trim(COALESCE(municipio,''))<>''
      ) GROUP BY municipio COLLATE NOCASE ORDER BY municipio COLLATE NOCASE
    `).all()
  ]);
  return {
    materiais: materiaisR.results || [],
    remessas: remessasR.results || [],
    municipios: (municipiosR.results || []).map(x=>String(x.municipio||"").trim()).filter(Boolean)
  };
}

function filtrosMateriaisV36(url) {
  const municipio = String(url.searchParams.get("municipio") || "").trim();
  const remessaRaw = Number(url.searchParams.get("remessa") || 0);
  const remessa = Number.isSafeInteger(remessaRaw) && remessaRaw > 0 ? remessaRaw : 0;
  return {municipio, remessa};
}

async function resumoMateriaisV36(env, filtros) {
  const where = ["c.excluido=0"];
  const params = [];
  if (filtros?.municipio) { where.push("lower(trim(c.municipio))=lower(trim(?))"); params.push(filtros.municipio); }
  if (Number(filtros?.remessa || 0) > 0) { where.push("c.remessa_id=?"); params.push(Number(filtros.remessa)); }
  const cond = where.join(" AND ");
  const sql = `
    WITH cf AS (
      SELECT c.* FROM consumos_materiais_v36 c WHERE ${cond}
    ), agg AS (
      SELECT material_id,
        SUM(embalagens) AS embalagens,
        COUNT(*) AS lancamentos,
        SUM(CASE WHEN conteudo_embalagem_snapshot IS NOT NULL THEN embalagens*conteudo_embalagem_snapshot ELSE 0 END) AS quantidade_fisica,
        SUM(CASE WHEN conteudo_embalagem_snapshot IS NOT NULL THEN 1 ELSE 0 END) AS lancamentos_com_conteudo,
        MAX(unidade_medida_snapshot) AS unidade_medida,
        MAX(embalagem_snapshot) AS embalagem,
        SUM(CASE WHEN custo_embalagem_centavos_snapshot IS NOT NULL THEN embalagens*custo_embalagem_centavos_snapshot ELSE 0 END) AS custo_centavos,
        SUM(CASE WHEN custo_embalagem_centavos_snapshot IS NOT NULL THEN 1 ELSE 0 END) AS lancamentos_com_custo
      FROM cf GROUP BY material_id
    ), rm AS (
      SELECT DISTINCT material_id,remessa_id FROM cf WHERE remessa_id IS NOT NULL
    ), prod AS (
      SELECT rm.material_id,
        COUNT(DISTINCT t.id) AS pacientes,
        COUNT(DISTINCT CASE WHEN upper(trim(COALESCE(t.superior_tipo,''))) NOT IN ('','NONE','NENHUMA','SEM_TRABALHO') THEN CAST(t.id AS TEXT)||':SUP' END)
        + COUNT(DISTINCT CASE WHEN upper(trim(COALESCE(t.inferior_tipo,''))) NOT IN ('','NONE','NENHUMA','SEM_TRABALHO') THEN CAST(t.id AS TEXT)||':INF' END) AS proteses
      FROM rm INNER JOIN trabalhos t ON t.remessa_id=rm.remessa_id AND t.excluido=0
      GROUP BY rm.material_id
    )
    SELECT m.id,m.nome,m.categoria,m.embalagem AS embalagem_atual,m.conteudo_embalagem,m.unidade_medida AS unidade_atual,m.custo_embalagem_centavos,
      a.embalagens,a.lancamentos,a.quantidade_fisica,a.lancamentos_com_conteudo,a.unidade_medida,a.embalagem,a.custo_centavos,a.lancamentos_com_custo,
      COALESCE(p.pacientes,0) AS pacientes,COALESCE(p.proteses,0) AS proteses
    FROM agg a INNER JOIN materiais_v36 m ON m.id=a.material_id
    LEFT JOIN prod p ON p.material_id=a.material_id
    ORDER BY m.categoria,m.nome COLLATE NOCASE
  `;
  return (await env.db.prepare(sql).bind(...params).all()).results || [];
}

async function historicoMateriaisV36(env, filtros) {
  const where = ["c.excluido=0"];
  const params = [];
  if (filtros?.municipio) { where.push("lower(trim(c.municipio))=lower(trim(?))"); params.push(filtros.municipio); }
  if (Number(filtros?.remessa || 0) > 0) { where.push("c.remessa_id=?"); params.push(Number(filtros.remessa)); }
  params.push(100);
  const r = await env.db.prepare(`
    SELECT c.*,m.nome AS material_nome,m.categoria,r.numero AS remessa_numero,u.nome AS registrado_por_nome
    FROM consumos_materiais_v36 c
    INNER JOIN materiais_v36 m ON m.id=c.material_id
    LEFT JOIN remessas r ON r.id=c.remessa_id
    LEFT JOIN usuarios u ON u.id=c.registrado_por
    WHERE ${where.join(" AND ")}
    ORDER BY c.data_consumo DESC,c.id DESC LIMIT ?
  `).bind(...params).all();
  return r.results || [];
}

function cardResumoMaterialV36(item) {
  const embalagens = Number(item.embalagens || 0);
  const pacientes = Number(item.pacientes || 0);
  const proteses = Number(item.proteses || 0);
  const rendimento = embalagens > 0 ? proteses / embalagens : 0;
  const mediaFisica = proteses > 0 && Number(item.lancamentos_com_conteudo||0) > 0 ? Number(item.quantidade_fisica||0) / proteses : null;
  const custoMedio = proteses > 0 && Number(item.lancamentos_com_custo||0) > 0 ? Math.round(Number(item.custo_centavos||0) / proteses) : null;
  const embalagem = String(item.embalagem || item.embalagem_atual || "embalagem");
  const unidade = String(item.unidade_medida || item.unidade_atual || "");
  return `
    <article class="card" style="padding:14px">
      <div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap">
        <div><span class="mini">${escapeHtml(rotuloCategoriaMaterialV36(item.categoria))}</span><h3 style="margin:3px 0 0">${escapeHtml(item.nome)}</h3></div>
        <span class="badge andamento">${numeroMaterialV36(embalagens)} ${escapeHtml(embalagem)}${embalagens===1?'':'(s)'}</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px">
        <div><span class="mini">Pacientes vinculados</span><strong style="display:block;font-size:24px">${pacientes}</strong></div>
        <div><span class="mini">Próteses / arcadas</span><strong style="display:block;font-size:24px">${proteses}</strong></div>
        <div><span class="mini">Rendimento</span><strong style="display:block">${numeroMaterialV36(rendimento,1)} próteses/${escapeHtml(embalagem)}</strong></div>
        <div><span class="mini">Média por prótese</span><strong style="display:block">${mediaFisica===null?'—':`${numeroMaterialV36(mediaFisica,2)} ${escapeHtml(unidade)}`}</strong></div>
      </div>
      ${Number(item.lancamentos_com_conteudo||0)>0 ? `<p class="mini" style="margin:10px 0 0">Quantidade física usada: ${numeroMaterialV36(item.quantidade_fisica,2)} ${escapeHtml(unidade)}.</p>` : `<p class="mini" style="margin:10px 0 0">Cadastre o conteúdo da embalagem para calcular g/ml por prótese.</p>`}
      ${custoMedio===null ? "" : `<p class="mini" style="margin:4px 0 0">Custo estimado: ${escapeHtml(formatarMoedaCentavosV25(Math.round(Number(item.custo_centavos||0))))} · média ${escapeHtml(formatarMoedaCentavosV25(custoMedio))}/prótese.</p>`}
    </article>
  `;
}

function paginaMateriaisV36(usuario, dados, filtros, mensagem="", tipo="sucesso") {
  const materiaisAtivos = (dados.materiais || []).filter(x=>Number(x.ativo)===1);
  const optMateriais = materiaisAtivos.map(m=>`<option value="${Number(m.id)}">${escapeHtml(m.nome)} · ${escapeHtml(rotuloCategoriaMaterialV36(m.categoria))}</option>`).join("");
  const optMunicipios = `<option value="">Todos os municípios</option>` + (dados.municipios||[]).map(m=>`<option value="${escapeHtml(m)}" ${String(filtros.municipio).toLocaleLowerCase('pt-BR')===String(m).toLocaleLowerCase('pt-BR')?'selected':''}>${escapeHtml(m)}</option>`).join("");
  const optRemessasFiltro = `<option value="">Todas as remessas</option>` + (dados.remessas||[]).map(r=>`<option value="${Number(r.id)}" ${Number(filtros.remessa)===Number(r.id)?'selected':''}>${escapeHtml(r.municipio)} · Remessa ${String(Number(r.numero||0)).padStart(2,'0')}</option>`).join("");
  const optRemessasConsumo = (dados.remessas||[]).map(r=>`<option value="${Number(r.id)}" data-municipio="${escapeHtml(String(r.municipio||'').toLocaleLowerCase('pt-BR'))}">${escapeHtml(r.municipio)} · Remessa ${String(Number(r.numero||0)).padStart(2,'0')}${r.data_entrega_real?' · entregue':''}</option>`).join("");
  const resumo = (dados.resumo||[]).map(cardResumoMaterialV36).join("");
  const historico = (dados.historico||[]).map(c=>{
    const qtd = Number(c.embalagens||0);
    const fisica = c.conteudo_embalagem_snapshot===null||c.conteudo_embalagem_snapshot===undefined ? "" : ` · ${numeroMaterialV36(qtd*Number(c.conteudo_embalagem_snapshot||0),2)} ${escapeHtml(c.unidade_medida_snapshot||'')}`;
    return `<tr><td>${escapeHtml(String(c.data_consumo||'').split('-').reverse().join('/'))}</td><td><strong>${escapeHtml(c.material_nome)}</strong><div class="mini">${escapeHtml(rotuloCategoriaMaterialV36(c.categoria))}</div></td><td>${escapeHtml(c.municipio)}<div class="mini">Remessa ${String(Number(c.remessa_numero||0)).padStart(2,'0')}</div></td><td>${numeroMaterialV36(qtd)} ${escapeHtml(c.embalagem_snapshot||'embalagem')}${fisica}</td><td>${escapeHtml(c.registrado_por_nome||'—')}</td><td>${escapeHtml(c.observacao||'—')}</td><td><form method="POST" action="/materiais/consumos/${Number(c.id)}/anular" onsubmit="return confirm('Anular este lançamento? Ele sairá dos cálculos, mas continuará preservado para auditoria.');"><button class="botao botao-sec">Anular</button></form></td></tr>`;
  }).join("");
  const catalogo = (dados.materiais||[]).map(m=>`<tr><td><strong>${escapeHtml(m.nome)}</strong></td><td>${escapeHtml(rotuloCategoriaMaterialV36(m.categoria))}</td><td>${escapeHtml(m.embalagem||'—')}</td><td>${m.conteudo_embalagem?`${numeroMaterialV36(m.conteudo_embalagem,2)} ${escapeHtml(m.unidade_medida||'')}`:'—'}</td><td>${m.custo_embalagem_centavos===null||m.custo_embalagem_centavos===undefined?'—':escapeHtml(formatarMoedaCentavosV25(Number(m.custo_embalagem_centavos)))}</td><td><span class="badge ${Number(m.ativo)?'ok':'perigo'}">${Number(m.ativo)?'Ativo':'Inativo'}</span></td>${isCoord(usuario)?`<td><form method="POST" action="/materiais/${Number(m.id)}/toggle"><button class="botao botao-sec">${Number(m.ativo)?'Desativar':'Ativar'}</button></form></td>`:'<td>—</td>'}</tr>`).join("");
  return layout(`
    <div class="cabecalho-pagina"><div><h1>◈ Consumo de materiais · V3.6</h1><p class="nota">Resinas, glaze e outros materiais ligados às remessas para medir rendimento por paciente e por prótese.</p></div><a class="botao botao-sec" href="/digital">← Digital</a></div>
    ${mensagem?`<div class="${tipo==='erro'?'erro':'sucesso'}">${escapeHtml(mensagem)}</div>`:''}

    <section class="card">
      <div style="display:flex;justify-content:space-between;gap:14px;align-items:end;flex-wrap:wrap">
        <div><span class="mini">ANÁLISE</span><h2 style="margin:3px 0">Consumo por município / remessa</h2><p class="nota" style="margin:0">Os pacientes e próteses são calculados a partir das remessas vinculadas aos lançamentos, sem contar a mesma remessa duas vezes para o mesmo material.</p></div>
        <form method="GET" action="/materiais" style="display:flex;gap:8px;align-items:end;flex-wrap:wrap"><label style="margin:0">Município<select name="municipio">${optMunicipios}</select></label><label style="margin:0">Remessa<select name="remessa">${optRemessasFiltro}</select></label><button>Aplicar</button><a class="botao botao-sec" href="/materiais">Limpar</a></form>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px;margin-top:14px">${resumo||'<div class="nota">Nenhum consumo registrado para este filtro.</div>'}</div>
    </section>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:14px;margin-top:16px">
      <section class="card"><h2>Registrar consumo</h2><form method="POST" action="/materiais/consumo" class="form-grid">
        <label>Material<select name="material_id" required><option value="">Selecione</option>${optMateriais}</select></label>
        <label>Data<input type="date" name="data_consumo" value="${escapeHtml(hojeSaoPauloV36())}" required></label>
        <label class="full">Remessa<select name="remessa_id" required><option value="">Selecione município / remessa</option>${optRemessasConsumo}</select></label>
        <label>Embalagens utilizadas<input type="number" name="embalagens" min="0.01" step="0.01" required placeholder="Ex.: 3"></label>
        <label class="full">Observação<input name="observacao" maxlength="300" placeholder="Ex.: produção da carga semanal"></label>
        <div class="full"><button>Registrar consumo</button></div>
      </form><p class="mini">Pode usar decimal: 0,5 embalagem equivale a meia embalagem. O rendimento usa pacientes e arcadas da remessa escolhida.</p></section>

      <section class="card"><h2>Cadastrar material</h2><form method="POST" action="/materiais/catalogo" class="form-grid">
        <label class="full">Nome<input name="nome" required maxlength="100" placeholder="Ex.: SmartDent Bite Splint"></label>
        <label>Categoria<select name="categoria"><option value="RESINA">Resina</option><option value="GLAZE">Glaze</option><option value="LAVAGEM">Lavagem</option><option value="GLICERINA">Glicerina</option><option value="OUTRO">Outro</option></select></label>
        <label>Tipo de embalagem<input name="embalagem" maxlength="30" value="pote" placeholder="pote, frasco, galão"></label>
        <label>Conteúdo por embalagem<input type="number" name="conteudo_embalagem" min="0" step="0.01" placeholder="Ex.: 1000"></label>
        <label>Unidade<select name="unidade_medida"><option value="">Não informar</option><option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="l">L</option><option value="un">unidade</option></select></label>
        <label>Custo por embalagem (R$)<input type="number" name="custo_embalagem" min="0" step="0.01" placeholder="Opcional"></label>
        <div class="full"><button>Cadastrar material</button></div>
      </form><p class="mini">Conteúdo e custo são opcionais. Se preenchidos, o Fluxo Lab calcula consumo físico e custo médio por prótese.</p></section>
    </div>

    <section class="card" style="margin-top:16px"><h2>Histórico de consumo</h2><div class="tabela-wrap"><table><thead><tr><th>Data</th><th>Material</th><th>Município / remessa</th><th>Quantidade</th><th>Registrado por</th><th>Observação</th><th>Ação</th></tr></thead><tbody>${historico||'<tr><td colspan="7">Nenhum lançamento neste filtro.</td></tr>'}</tbody></table></div></section>

    <details class="card" style="margin-top:16px"><summary style="cursor:pointer;font-weight:800">Catálogo de materiais</summary><div class="tabela-wrap" style="margin-top:12px"><table><thead><tr><th>Material</th><th>Categoria</th><th>Embalagem</th><th>Conteúdo</th><th>Custo</th><th>Status</th><th>Ação</th></tr></thead><tbody>${catalogo||'<tr><td colspan="7">Nenhum material cadastrado.</td></tr>'}</tbody></table></div></details>
  `,"Materiais",usuario);
}

async function rotaMateriaisV36(request, env, url, caminho) {
  if (!caminho.startsWith("/materiais")) return null;
  const usuario = await obterUsuarioLogado(request, env);
  if (!usuario) return redirect("/");
  if (!usuarioPodeMateriaisV317(usuario)) return textResponse("Acesso negado ao controle de materiais.", 403);

  if (request.method === "GET" && caminho === "/materiais-consumo") {
    const q = new URLSearchParams(url.searchParams);
    return redirect(`/materiais${q.toString()?`?${q.toString()}`:""}`);
  }

  if (request.method === "GET" && caminho === "/materiais") return null;

  if (request.method === "POST" && caminho === "/materiais/catalogo") {
    const f = await request.formData();
    const nome = String(f.get("nome")||"").trim();
    const categoria = categoriaMaterialV36(f.get("categoria"));
    const embalagem = String(f.get("embalagem")||"embalagem").trim().slice(0,30) || "embalagem";
    const conteudoRaw = String(f.get("conteudo_embalagem")||"").trim();
    const conteudo = conteudoRaw ? Number(conteudoRaw) : null;
    const unidade = unidadeMedidaMaterialV36(f.get("unidade_medida")) || null;
    const custoRaw = String(f.get("custo_embalagem")||"").trim();
    const custo = custoRaw ? Math.round(Number(custoRaw)*100) : null;
    if (nome.length < 2 || (conteudo!==null && (!Number.isFinite(conteudo)||conteudo<=0)) || (custo!==null && (!Number.isSafeInteger(custo)||custo<0))) return redirect(`/materiais?erro=${encodeURIComponent("Confira nome, conteúdo e custo do material.")}`);
    try {
      const agora = new Date().toISOString();
      const r = await env.db.prepare(`INSERT INTO materiais_v36(nome,categoria,embalagem,conteudo_embalagem,unidade_medida,custo_embalagem_centavos,ativo,criado_por,criado_em,atualizado_em) VALUES (?,?,?,?,?,?,1,?,?,?)`).bind(nome,categoria,embalagem,conteudo,unidade,custo,usuario.id,agora,agora).run();
      await registrarAuditoriaSistemaV31(env,usuario.id,"DIGITAL","MATERIAL_CADASTRADO","MATERIAL",r.meta?.last_row_id||null,"nome",null,nome,`${categoria} · ${embalagem}`);
      return redirect(`/materiais?ok=${encodeURIComponent(`${nome} cadastrado.`)}`);
    } catch (erro) {
      const duplicado=String(erro?.message||"").toLowerCase().includes("unique");
      return redirect(`/materiais?erro=${encodeURIComponent(duplicado?"Já existe um material com esse nome.":"Não foi possível cadastrar o material.")}`);
    }
  }

  if (request.method === "POST" && caminho === "/materiais/consumo") {
    const f = await request.formData();
    const materialId = Number(f.get("material_id"));
    const remessaId = Number(f.get("remessa_id"));
    const dataConsumo = String(f.get("data_consumo")||"").trim();
    const embalagens = Number(String(f.get("embalagens")||"").replace(",","."));
    const observacao = String(f.get("observacao")||"").trim().slice(0,300);
    if (!Number.isSafeInteger(materialId)||materialId<1||!Number.isSafeInteger(remessaId)||remessaId<1||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(dataConsumo)||!Number.isFinite(embalagens)||embalagens<=0) return redirect(`/materiais?erro=${encodeURIComponent("Preencha material, remessa, data e quantidade corretamente.")}`);
    const [material,remessa] = await Promise.all([
      env.db.prepare(`SELECT * FROM materiais_v36 WHERE id=? AND ativo=1 LIMIT 1`).bind(materialId).first(),
      env.db.prepare(`SELECT id,municipio,numero FROM remessas WHERE id=? LIMIT 1`).bind(remessaId).first()
    ]);
    if (!material||!remessa) return redirect(`/materiais?erro=${encodeURIComponent("Material ou remessa não encontrado.")}`);
    const agora = new Date().toISOString();
    const r = await env.db.prepare(`INSERT INTO consumos_materiais_v36(material_id,municipio,remessa_id,data_consumo,embalagens,embalagem_snapshot,conteudo_embalagem_snapshot,unidade_medida_snapshot,custo_embalagem_centavos_snapshot,observacao,registrado_por,criado_em,excluido) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,0)`).bind(materialId,String(remessa.municipio||"").trim(),remessaId,dataConsumo,embalagens,material.embalagem||"embalagem",material.conteudo_embalagem??null,material.unidade_medida??null,material.custo_embalagem_centavos??null,observacao||null,usuario.id,agora).run();
    await registrarAuditoriaSistemaV31(env,usuario.id,"DIGITAL","CONSUMO_MATERIAL","CONSUMO_MATERIAL",r.meta?.last_row_id||null,"embalagens",null,String(embalagens),`${material.nome} · ${remessa.municipio} · Remessa ${String(Number(remessa.numero||0)).padStart(2,"0")}`);
    return redirect(`/materiais?municipio=${encodeURIComponent(remessa.municipio)}&remessa=${remessaId}&ok=${encodeURIComponent("Consumo registrado e vinculado à produção da remessa.")}`);
  }

  let m = caminho.match(/^\/materiais\/(\d+)\/toggle$/);
  if (request.method === "POST" && m) {
    if (!isCoord(usuario)) return textResponse("Somente Administrador ou Coordenador pode ativar/desativar materiais.",403);
    const id=Number(m[1]);
    const mat=await env.db.prepare(`SELECT id,nome,ativo FROM materiais_v36 WHERE id=?`).bind(id).first();
    if(!mat)return textResponse("Material não encontrado.",404);
    const novo=Number(mat.ativo)?0:1;
    await env.db.prepare(`UPDATE materiais_v36 SET ativo=?,atualizado_em=? WHERE id=?`).bind(novo,new Date().toISOString(),id).run();
    await registrarAuditoriaSistemaV31(env,usuario.id,"DIGITAL",novo?"MATERIAL_ATIVADO":"MATERIAL_DESATIVADO","MATERIAL",id,"ativo",String(Number(mat.ativo)),String(novo),mat.nome);
    return redirect(`/materiais?ok=${encodeURIComponent(`${mat.nome} ${novo?'ativado':'desativado'}.`)}`);
  }

  m = caminho.match(/^\/materiais\/consumos\/(\d+)\/anular$/);
  if (request.method === "POST" && m) {
    const id=Number(m[1]);
    const c=await env.db.prepare(`SELECT c.*,m.nome AS material_nome FROM consumos_materiais_v36 c JOIN materiais_v36 m ON m.id=c.material_id WHERE c.id=? AND c.excluido=0`).bind(id).first();
    if(!c)return redirect(`/materiais?erro=${encodeURIComponent("Lançamento não encontrado ou já anulado.")}`);
    const agora=new Date().toISOString();
    await env.db.prepare(`UPDATE consumos_materiais_v36 SET excluido=1,excluido_por=?,excluido_em=? WHERE id=? AND excluido=0`).bind(usuario.id,agora,id).run();
    await registrarAuditoriaSistemaV31(env,usuario.id,"DIGITAL","CONSUMO_MATERIAL_ANULADO","CONSUMO_MATERIAL",id,"excluido","0","1",`${c.material_nome} · ${c.municipio} · ${c.embalagens} ${c.embalagem_snapshot}`);
    return redirect(`/materiais?municipio=${encodeURIComponent(c.municipio||'')}&ok=${encodeURIComponent("Lançamento anulado. O histórico de auditoria foi preservado.")}`);
  }

  return null;
}

