function clienteTemaV339(){
  const raiz=document.documentElement;
  const botao=document.getElementById('alternar-tema-fluxo');
  const ordem=['light','dark','odonto-light','odonto-dark'];
  const rotulos={'light':'☀ Fluxo Lab claro','dark':'☾ Fluxo Lab escuro','odonto-light':'🦷 Odonto Prótese claro','odonto-dark':'🦷 Odonto Prótese escuro'};
  const originais=new WeakMap();
  function trocarNome(odonto){
    const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;
    while((n=w.nextNode())){
      if(n.parentElement&&['SCRIPT','STYLE','TEXTAREA'].includes(n.parentElement.tagName))continue;
      if(!originais.has(n)){if(!/Fluxo Lab/.test(n.nodeValue))continue;originais.set(n,n.nodeValue);}
      n.nodeValue=odonto?originais.get(n).replace(/Fluxo Lab/g,'Odonto Prótese'):originais.get(n);
    }
    document.querySelectorAll('[placeholder*="Fluxo Lab"],[placeholder*="Odonto Prótese"]').forEach(el=>{
      if(!el.dataset.phOriginal)el.dataset.phOriginal=el.placeholder;
      el.placeholder=odonto?el.dataset.phOriginal.replace(/Fluxo Lab/g,'Odonto Prótese'):el.dataset.phOriginal;
    });
    if(!raiz.dataset.tituloOriginal)raiz.dataset.tituloOriginal=document.title;
    document.title=odonto?raiz.dataset.tituloOriginal.replace(/Fluxo Lab/g,'Odonto Prótese'):raiz.dataset.tituloOriginal;
  }
  function modoAtual(){return (raiz.dataset.marca==='odonto'?'odonto-':'')+(raiz.dataset.tema==='light'?'light':'dark');}
  function aplicar(modo){
    const escuro=modo.endsWith('dark'),odonto=modo.startsWith('odonto');
    raiz.dataset.tema=escuro?'dark':'light';
    if(odonto)raiz.dataset.marca='odonto';else delete raiz.dataset.marca;
    trocarNome(odonto);
    const prox=ordem[(ordem.indexOf(modo)+1)%ordem.length];
    if(botao){botao.textContent=rotulos[modo];botao.title='Clique para mudar para: '+rotulos[prox];botao.setAttribute('aria-pressed',String(escuro));botao.setAttribute('aria-label','Tema atual: '+rotulos[modo]+'. Mudar para '+rotulos[prox]);}
    const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=odonto?(escuro?'#082E2B':'#0E5A4E'):(escuro?'#0c181d':'#159a9c');
  }
  aplicar(modoAtual());
  if(botao)botao.addEventListener('click',()=>{const m=ordem[(ordem.indexOf(modoAtual())+1)%ordem.length];aplicar(m);try{localStorage.setItem('fluxo-lab-tema',m);}catch{}});
  window.addEventListener('storage',e=>{if(e.key==='fluxo-lab-tema'&&ordem.includes(e.newValue))aplicar(e.newValue);});
}
