/* V3.4.2 — Busca geral autenticada e separada pelas áreas permitidas. */
function opcoesBuscaV342(url){
  const tipos=['pacientes','municipios','remessas','ciclos'];
  const q=String(url.searchParams.get('q')||'').trim().slice(0,120);
  const tipo=tipos.includes(url.searchParams.get('tipo'))?url.searchParams.get('tipo'):'';
  const area=['DIGITAL','CONVENCIONAL'].includes(url.searchParams.get('area'))?url.searchParams.get('area'):'';
  const remessa=Number(url.searchParams.get('remessa'));
  return {q,tipo,area,remessa:tipo==='pacientes'&&Number.isSafeInteger(remessa)&&remessa>0?remessa:0,pagina:Math.max(1,Math.min(10000,Math.floor(Number(url.searchParams.get('pagina'))||1)))};
}
function consultaBuscaV342(u,o){
  const areas=areasUsuarioV31(u).filter(a=>['DIGITAL','CONVENCIONAL'].includes(a)&&(!o.area||o.area===a));
  const selects=[];
  const add=(tipo,area,sql)=>{if(areas.includes(area)&&(!o.tipo||o.tipo===tipo))selects.push(sql)};
  for(const area of areas){
    const digital=area==='DIGITAL',tabela=digital?'trabalhos':'trabalhos_convencionais',ciclos=digital?'ciclos_digitais':'ciclos_convencionais';
    const ciclo=digital?'r.ciclo_digital_id':'t.ciclo_id';
    const codigo=digital?"COALESCE(t.codigo,'')":"'Articulador '||COALESCE(CAST(t.numero_articulador AS TEXT),'—')";
    add('pacientes',area,`SELECT 'pacientes' AS tipo,'${area}' AS area,t.id, t.paciente AS titulo,
      ${codigo}||' · '||COALESCE(t.municipio,'')||CASE WHEN r.id IS NOT NULL THEN ' · Remessa '||printf('%02d',r.numero) ELSE '' END||CASE WHEN c.id IS NOT NULL THEN ' · Ciclo '||c.nome ELSE '' END AS detalhe,
      t.municipio,COALESCE(t.remessa_id,0) AS remessa_id,COALESCE(c.id,0) AS ciclo_id,
      COALESCE(t.paciente,'')||' '||${codigo}||' '||COALESCE(t.municipio,'')||' '||CASE WHEN r.id IS NOT NULL THEN 'Remessa '||printf('%02d',r.numero)||' '||r.numero ELSE '' END||' '||COALESCE(c.nome,'') AS texto
      FROM ${tabela} t LEFT JOIN remessas r ON r.id=t.remessa_id LEFT JOIN ${ciclos} c ON c.id=${ciclo} WHERE t.excluido=0${digital?sqlVisibilidadeTrabalhoDigitalLiteralV345(u,'t'):''}`);
    const fontes=digital?`SELECT municipio FROM trabalhos WHERE excluido=0 UNION SELECT municipio FROM remessas WHERE ciclo_digital_id IS NOT NULL`:`SELECT municipio FROM trabalhos_convencionais WHERE excluido=0 UNION SELECT municipio FROM ciclo_municipios_convencionais WHERE cancelado=0`;
    add('municipios',area,`SELECT 'municipios' AS tipo,'${area}' AS area,0 AS id,municipio AS titulo,'Município · ${digital?'Digital':'Convencional'}' AS detalhe,municipio,0 AS remessa_id,0 AS ciclo_id,municipio AS texto FROM (${fontes}) WHERE municipio IS NOT NULL AND trim(municipio)!='' GROUP BY municipio COLLATE NOCASE`);
    const cr=digital?'r.ciclo_digital_id':`(SELECT MIN(t.ciclo_id) FROM trabalhos_convencionais t WHERE t.remessa_id=r.id AND t.excluido=0)`;
    const acesso=digital?`r.ciclo_digital_id IS NOT NULL OR EXISTS(SELECT 1 FROM trabalhos t WHERE t.remessa_id=r.id AND t.excluido=0)`:`EXISTS(SELECT 1 FROM trabalhos_convencionais t WHERE t.remessa_id=r.id AND t.excluido=0) OR EXISTS(SELECT 1 FROM faixas_convencionais f WHERE f.remessa_id=r.id)`;
    add('remessas',area,`SELECT 'remessas' AS tipo,'${area}' AS area,r.id,'Remessa '||printf('%02d',r.numero)||' · '||r.municipio AS titulo,
      'Recebimento: '||COALESCE(r.data_recebimento,'—')||' · Entrega prevista: '||COALESCE(r.data_prevista_entrega,'—')||CASE WHEN c.id IS NOT NULL THEN ' · Ciclo '||c.nome ELSE '' END AS detalhe,
      r.municipio,r.id AS remessa_id,COALESCE(c.id,0) AS ciclo_id,
      'Remessa '||printf('%02d',r.numero)||' '||r.numero||' '||r.municipio||' '||COALESCE(c.nome,'')||' '||COALESCE(r.data_recebimento,'') AS texto
      FROM remessas r LEFT JOIN ${ciclos} c ON c.id=${cr} WHERE (${acesso})`);
    add('ciclos',area,`SELECT 'ciclos' AS tipo,'${area}' AS area,c.id,c.nome AS titulo,COALESCE(c.data_inicio,'—')||' → '||COALESCE(c.data_fim,'—')||CASE WHEN c.ativo=1 THEN ' · Ativo' ELSE ' · Inativo' END AS detalhe,'' AS municipio,0 AS remessa_id,c.id AS ciclo_id,c.nome||' '||COALESCE(c.data_inicio,'')||' '||COALESCE(c.data_fim,'') AS texto FROM ${ciclos} c`);
  }
  if(!selects.length)return null;
  const ctes=[`b0 AS (${selects.join(' UNION ALL ')})`];
  const acentos='áàâãäéèêëíìîïóòôõöúùûüçñ';
  const simples='aaaaaeeeeiiiiooooouuuucn';
  const pares=[...acentos].map((c,i)=>[c,simples[i]]).concat([...acentos.toUpperCase()].map((c,i)=>[c,simples[i]]));
  // Expressões curtas em CTEs para não exceder a profundidade do parser SQLite.
  for(let i=0;i<pares.length;i+=8){const n=Math.floor(i/8),expr=pares.slice(i,i+8).reduce((e,[a,b])=>`replace(${e},'${a}','${b}')`,'texto');ctes.push(`b${n+1} AS (SELECT tipo,area,id,titulo,detalhe,municipio,remessa_id,ciclo_id,${expr} AS texto FROM b${n})`);}
  const tokens=o.q.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().split(/\s+/).filter(Boolean).slice(0,8);
  const params=tokens.map(t=>'%'+t.replace(/[\\%_]/g,'\\$&')+'%');
  const where=tokens.map(()=>"lower(texto) LIKE ? ESCAPE '\\'");
  if(o.remessa){where.push('remessa_id=?');params.push(o.remessa)}
  params.push(31,(o.pagina-1)*30);
  return {sql:`WITH ${ctes.join(',')} SELECT tipo,area,id,titulo,detalhe,municipio,remessa_id,ciclo_id FROM b${Math.ceil(pares.length/8)} ${where.length?'WHERE '+where.join(' AND '):''} ORDER BY CASE tipo WHEN 'pacientes' THEN 1 WHEN 'municipios' THEN 2 WHEN 'remessas' THEN 3 ELSE 4 END,titulo COLLATE NOCASE,area,id LIMIT ? OFFSET ?`,params};
}
function urlBuscaV342(o,alteracoes={}){const v={...o,...alteracoes},q=new URLSearchParams();for(const k of ['q','tipo','area','remessa','pagina'])if(v[k])q.set(k,String(v[k]));return '/busca?'+q;}
function paginaBuscaV342(u,o,lista,mais,erro=''){
  const nomes={pacientes:'Pacientes',municipios:'Municípios',remessas:'Remessas',ciclos:'Ciclos'};
  const areas=areasUsuarioV31(u).filter(a=>['DIGITAL','CONVENCIONAL'].includes(a));
  const cards=lista.map(r=>{
    let href,label='Abrir';
    if(r.tipo==='pacientes')href=(r.area==='DIGITAL'?'/trabalhos/':'/convencional/trabalhos/')+Number(r.id);
    else if(r.tipo==='ciclos')href=(r.area==='DIGITAL'?'/digital':'/convencional')+'?ciclo='+Number(r.id);
    else if(r.tipo==='remessas'){href=urlBuscaV342({tipo:'pacientes',area:r.area,remessa:Number(r.id),pagina:1});label='Ver pacientes da remessa';}
    else {href=urlBuscaV342({q:r.municipio,tipo:'pacientes',area:r.area,pagina:1});label='Ver pacientes';}
    return `<article class="card busca-resultado-v342"><div class="mini">${escapeHtml(nomes[r.tipo])} · ${escapeHtml(nomeAreaProducao(r.area))}</div><h3><a href="${escapeHtml(href)}">${escapeHtml(r.titulo||'Sem nome')}</a></h3><p class="nota">${escapeHtml(r.detalhe||'')}</p><a class="botao botao-sec" href="${escapeHtml(href)}">${label}</a></article>`;
  }).join('');
  const realizada=o.q.length>=2||o.remessa;
  return layout(`<div class="cabecalho-pagina"><div><h1>Busca geral</h1><p class="nota">Encontre pacientes, municípios, remessas e ciclos nas áreas às quais você tem acesso.</p></div></div>
    <section class="card"><form action="/busca" method="GET" class="busca-filtros-v342" role="search"><label class="busca-termo-v342">O que você procura?<input type="search" name="q" maxlength="120" value="${escapeHtml(o.q)}" placeholder="Nome, município, código, remessa ou ciclo"></label><label>Tipo<select name="tipo"><option value="">Tudo</option>${Object.entries(nomes).map(([v,n])=>`<option value="${v}" ${o.tipo===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Área<select name="area"><option value="">Minhas áreas</option>${areas.map(a=>`<option value="${a}" ${o.area===a?'selected':''}>${escapeHtml(nomeAreaProducao(a))}</option>`).join('')}</select></label><button>Buscar</button>${o.remessa?`<input type="hidden" name="remessa" value="${o.remessa}">`:''}</form><p class="mini">Você pode pesquisar sem acentos. Use pelo menos 2 caracteres. Trabalhos excluídos não aparecem.</p>${o.remessa?`<p>Pacientes da remessa selecionada. <a href="/busca">Limpar filtro da remessa</a></p>`:''}</section>
    ${erro?`<div class="erro" role="alert">${escapeHtml(erro)}</div>`:!realizada?'<p class="nota">Exemplos: Maria, Potiraguá, Remessa 01 ou setembro.</p>':`<p role="status">${lista.length} resultado(s) nesta página${mais?' · há mais resultados':''}.</p>${lista.length?'':'<div class="card">Nenhum resultado encontrado. Tente parte do nome ou selecione Tudo e Minhas áreas.</div>'}`}
    <div class="busca-lista-v342">${cards}</div>${realizada&&!erro?`<nav class="busca-paginas-v342" aria-label="Páginas da busca">${o.pagina>1?`<a class="botao botao-sec" href="${escapeHtml(urlBuscaV342(o,{pagina:o.pagina-1}))}">← Anterior</a>`:''}<span>Página ${o.pagina}</span>${mais?`<a class="botao" href="${escapeHtml(urlBuscaV342(o,{pagina:o.pagina+1}))}">Próxima →</a>`:''}</nav>`:''}`,'Busca geral',u);
}
async function rotaBuscaV342(request,env,url,caminho){
  if(caminho!=='/busca')return null;
  const u=await obterUsuarioLogado(request,env);if(!u)return redirect('/');
  if(isCadastro(u))return textResponse('Acesso restrito ao módulo Cadastro.',403);
  if(request.method!=='GET')return textResponse('Método não permitido.',405);
  const o=opcoesBuscaV342(url);let lista=[],mais=false,erro='';
  if(o.q.length>=2||o.remessa){
    const consulta=consultaBuscaV342(u,o);
    if(consulta){try{const r=await env.db.prepare(consulta.sql).bind(...consulta.params).all();lista=r.results||[];mais=lista.length>30;lista=lista.slice(0,30);}catch{erro='Não foi possível consultar a busca agora. Tente novamente.';}}
  }
  const response=htmlResponse(paginaBuscaV342(u,o,lista,mais,erro));
  response.headers.set('Cache-Control','private, no-store');return response;
}


